      observations: dayInput.observations || [],
      adaptations: dayInput.adaptations || "",
      safetyNotes: dayInput.safetyNotes || "",
      items: (Array.isArray(dayInput.items) ? dayInput.items : [])
        .map((item) => authorizedCurriculumDailyPlanItemDto(item))
