function ensureStore() {
  if (!fs.existsSync(dataDir)) fs.mkdirSync(dataDir, { recursive: true });
  if (!fs.existsSync(storePath)) {
    fs.writeFileSync(storePath, JSON.stringify(defaultStore(), null, 2));
  }
}

function readStore() {
  if (usePostgresStore()) return structuredClone(storeCache || defaultStore());
  ensureStore();
  return JSON.parse(fs.readFileSync(storePath, "utf8"));
}

/** In-process mutable store for helpers that batch writes (deferPersist / webhook flush). */
function writableStore() {
  if (usePostgresStore()) {
    if (!storeCache) storeCache = defaultStore();
    return storeCache;
  }
  return peekStore();
}

async function readStoreFresh() {
  if (usePostgresStore()) {
    await postgresWriteChain.catch(() => {});
    if (postgresPool && databaseReady) {
      try {
        const result = await postgresQueryWithTransientRetry(
          "SELECT data FROM llh_store WHERE id = $1",
          [storeRecordId],
          { label: "Postgres readStoreFresh" },
        );
        if (result.rows[0]?.data) storeCache = result.rows[0].data;
      } catch (error) {
        console.warn("[store] readStoreFresh fell back to in-memory cache:", error.message || error);
      }
    }
    return structuredClone(storeCache || defaultStore());
  }
  return readStore();
}

// Returns the store without deep-cloning. Safe for read-only handlers that never
// mutate the returned object (or that intentionally mutate storeCache in place).
// For Postgres this avoids an expensive structuredClone of lesson plans, analytics,
// and child records on every request — the prior OOM crash source on Render starter.
function peekStore() {
  if (usePostgresStore()) {
    if (!storeCache) readStore();
    return storeCache || defaultStore();
  }
  ensureStore();
  // Cache local-json peeks by mtime so hot DTO loops do not re-parse multi-MB stores.
  try {
    const stat = fs.statSync(storePath);
    if (storeCache && storeCache._llhLocalMtimeMs === stat.mtimeMs) {
      return storeCache;
    }
    const parsed = JSON.parse(fs.readFileSync(storePath, "utf8"));
    parsed._llhLocalMtimeMs = stat.mtimeMs;
    storeCache = parsed;
    return storeCache;
  } catch {
    return JSON.parse(fs.readFileSync(storePath, "utf8"));
  }
}

// Full-document upsert that never drops Founding emails already persisted by a
// concurrent multi-instance claim (unions foundingMembers arrays).
const POSTGRES_UPSERT_STORE = `
INSERT INTO llh_store (id, data, updated_at) VALUES ($1, $2::jsonb, NOW())
ON CONFLICT (id) DO UPDATE SET
  data = jsonb_set(
    EXCLUDED.data,
    '{foundingMembers}',
    COALESCE((
      SELECT jsonb_agg(to_jsonb(email) ORDER BY email)
      FROM (
        SELECT DISTINCT lower(btrim(value)) AS email
        FROM (
          SELECT jsonb_array_elements_text(COALESCE(llh_store.data->'foundingMembers', '[]'::jsonb)) AS value
          UNION ALL
          SELECT jsonb_array_elements_text(COALESCE(EXCLUDED.data->'foundingMembers', '[]'::jsonb)) AS value
        ) emails
        WHERE btrim(value) <> ''
      ) uniq
    ), '[]'::jsonb),
    true
  ),
  updated_at = NOW()
`;
/** Stable advisory-lock namespace shared by Founding claims and Postgres store upserts. */
const FOUNDING_ADVISORY_LOCK_NS = 87442201;
const POSTGRES_WRITE_CHAIN_WAIT_MS = 20000;
const POSTGRES_QUERY_TIMEOUT_MS = 45000;
// Monotonic generation so a stale write queued behind a newer write cannot clobber it.
// Production bug: analytics/adminSession writeStore(readStore()) captured an old clone and
// overwrote a successful curriculum writeStoreAsync on the Postgres chain.
let postgresWriteGeneration = 0;

function withTimeout(promise, timeoutMs, label = "Operation") {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      reject(new Error(`${label} timed out after ${timeoutMs}ms.`));
    }, timeoutMs);
    Promise.resolve(promise).then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (error) => {
        clearTimeout(timer);
        reject(error);
      },
    );
  });
}

// Persist the latest in-memory storeCache. Stale generations are skipped so concurrent
// fire-and-forget writeStore() callers cannot erase a newer writeStoreAsync() result.
function storeInventoryCounts(store = peekStore()) {
  const users = store?.users || {};
  const messages = Array.isArray(store?.messages) ? store.messages : [];
  const notifications = Array.isArray(store?.notifications) ? store.notifications : [];
  const conversations = new Set(
    messages
      .map((m) => normalizeEmail(m.conversationEmail || m.toEmail || ""))
      .filter(Boolean),
  );
  const curriculum = normalizedCurriculumStore(store?.siteContent?.curriculum);
  return {
    users: Object.keys(users).length,
    messages: messages.length,
    conversations: conversations.size,
    foundingMembers: Array.isArray(store?.foundingMembers) ? store.foundingMembers.length : 0,
    notifications: notifications.length,
    supportTickets: Array.isArray(store?.supportTickets) ? store.supportTickets.length : 0,
    // Lesson plans are the public library source of truth — protect them like user inventory.
    curriculumLessonPlans: curriculum.lessonPlans.length,
    curriculumActivities: curriculum.activities.length,
  };
}

function storeCountDropReasons(nextCounts, prevCounts = lastPersistedStoreCounts) {
  if (!prevCounts || !nextCounts) return [];
  const reasons = [];
  const droppedHalf = (prev, next, minPrev) => prev >= minPrev && next < Math.floor(prev * 0.5);
  if (droppedHalf(prevCounts.users, nextCounts.users, 10)) {
    reasons.push(`users ${prevCounts.users} → ${nextCounts.users}`);
  }
  if (droppedHalf(prevCounts.messages, nextCounts.messages, 10)) {
    reasons.push(`messages ${prevCounts.messages} → ${nextCounts.messages}`);
  }
  if (droppedHalf(prevCounts.foundingMembers, nextCounts.foundingMembers, 5)) {
    reasons.push(`foundingMembers ${prevCounts.foundingMembers} → ${nextCounts.foundingMembers}`);
  }
  if (droppedHalf(prevCounts.curriculumLessonPlans, nextCounts.curriculumLessonPlans, 5)) {
    reasons.push(`curriculumLessonPlans ${prevCounts.curriculumLessonPlans} → ${nextCounts.curriculumLessonPlans}`);
  }
  // Lesson plans and activities are wiped by the same failure mode but are independent
  // arrays — an activities-only drop (lessonPlans looks intact) must be caught too, or this
  // general Postgres-write safety net misses exactly the failure mode the dedicated
  // curriculum-activities wipe-protection test covers for the site-content save endpoint.
  if (droppedHalf(prevCounts.curriculumActivities, nextCounts.curriculumActivities, 5)) {
    reasons.push(`curriculumActivities ${prevCounts.curriculumActivities} → ${nextCounts.curriculumActivities}`);
  }
  return reasons;
}

// Admin site-content saves often draft from a public hydrate (no curriculum payload) or an
// emptyCurriculum() fill. Never wipe a populated curriculum through that path unless the
// caller explicitly confirms REPLACE_CURRICULUM (dedicated wipe endpoint stays separate).
function shouldPreserveExistingCurriculum(existingCurriculum, incomingCurriculum, { allowReplace = false } = {}) {
  if (allowReplace) return false;
  const existing = normalizedCurriculumStore(existingCurriculum);
  const incoming = normalizedCurriculumStore(incomingCurriculum);
  // Lesson plans and activities are wiped together by the same failure mode (a full
  // curriculum object replace), but guard each independently — activities are what
  // populate the Activity Center and can otherwise go empty even if lessonPlans looks intact.
  const lessonPlansWiped = curriculumFieldDroppedTooMuch(existing.lessonPlans.length, incoming.lessonPlans.length);
  const activitiesWiped = curriculumFieldDroppedTooMuch(existing.activities.length, incoming.activities.length);
  return lessonPlansWiped || activitiesWiped;
}

function curriculumFieldDroppedTooMuch(existingCount, incomingCount) {
  if (existingCount <= 0) return false;
  if (incomingCount === 0) return true;
  if (existingCount >= 5 && incomingCount < Math.floor(existingCount * 0.5)) return true;
  return false;
}

async function maybeAlertStoreSafety(kind, detail = {}) {
  const now = Date.now();
  if (now - lastStoreSafetyAlertAt < STORE_SAFETY_ALERT_COOLDOWN_MS) return;
  lastStoreSafetyAlertAt = now;
  const subject = `[LLH SAFETY] ${kind}`;
  const text = [
    `Little Learner Hub store safety alert: ${kind}`,
    `Time: ${new Date(now).toISOString()}`,
    `Detail: ${JSON.stringify(detail)}`,
    `Database ready: ${databaseReady}`,
    `Last Postgres error: ${lastPostgresError || "(none)"}`,
  ].join("\n");
  console.error("[store-safety]", kind, detail);
  try {
    if (supportEmailConfigStatus().ready) {
      await sendEmail({
        to: SUPPORT_EMAIL_TO,
        subject,
        text,
        html: `<pre>${text.replace(/[<>&]/g, (c) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;" }[c]))}</pre>`,
      });
    }
  } catch (error) {
    console.warn("[store-safety] alert email failed:", error.message);
  }
}

function logStorePersistence(kind, detail = {}) {
  console.log(`[store-persistence] ${kind}`, detail);
}

function createStorePersistenceError(message, code, extra = {}) {
  const err = new Error(message);
  err.code = code;
  Object.assign(err, extra);
  return err;
}

function isProductionPostgresDeployment() {
  return usePostgresStore()
    && String(process.env.NODE_ENV || "").toLowerCase() === "production";
}

function classifyPostgresDisconnectReason(reason = "") {
  const text = String(reason || "").toLowerCase();
  if (text.includes("deploy") || text.includes("boot")) return "temporary_deploy_disconnect";
  if (text.includes("write_async") || text.includes("write_failed")) return "failed_write";
  if (text.includes("reconnect")) return "database_unavailable";
  return "database_unavailable";
}

function maybeAlertPostgresDisconnect(reason = "postgres_unavailable") {
  const now = Date.now();
  if (now - lastPostgresDisconnectAlertAt < STORE_SAFETY_ALERT_COOLDOWN_MS) return;
  lastPostgresDisconnectAlertAt = now;
  const category = classifyPostgresDisconnectReason(reason);
  logStorePersistence(category, { reason, lastError: lastPostgresError || "" });
  maybeAlertStoreSafety(`postgres_disconnect:${category}`, {
    reason,
    category,
    lastError: lastPostgresError || "",
  }).catch(() => {});
}

function assertSafePostgresStoreReplacement(nextStore) {
  const nextCounts = storeInventoryCounts(nextStore);
  const dropReasons = storeCountDropReasons(nextCounts);
  if (!dropReasons.length) return nextCounts;
  if (ALLOW_DESTRUCTIVE_STORE_WRITE) {
    console.warn("[store-safety] destructive store write allowed by ALLOW_DESTRUCTIVE_STORE_WRITE:", dropReasons);
    return nextCounts;
  }
  const err = new Error(
    `Refusing full-store Postgres write that would drop inventory (${dropReasons.join("; ")}). Set ALLOW_DESTRUCTIVE_STORE_WRITE=true only for an intentional rebuild.`,
  );
  err.code = "store_count_drop_blocked";
  err.dropReasons = dropReasons;
  err.previousCounts = lastPersistedStoreCounts;
  err.nextCounts = nextCounts;
  throw err;
}

async function createLogicalStoreBackup({ source = "scheduled" } = {}) {
  if (!usePostgresStore() || !postgresPool || !databaseReady) {
    return { ok: false, reason: "postgres_not_ready" };
  }
  const store = peekStore();
  const counts = storeInventoryCounts(store);
  const id = `backup_${new Date().toISOString().replace(/[:.]/g, "-")}_${source}`;
  const payload = JSON.stringify(store);
  await postgresPool.query(
    `INSERT INTO llh_store_backups (
      id, source, user_count, message_count, founding_count, notification_count, support_ticket_count, verified, data
    ) VALUES ($1,$2,$3,$4,$5,$6,$7,FALSE,$8::jsonb)`,
    [
      id,
      source,
      counts.users,
      counts.messages,
      counts.foundingMembers,
      counts.notifications,
      counts.supportTickets,
      payload,
    ],
  );
  const verify = await postgresPool.query(
    "SELECT user_count, message_count, founding_count FROM llh_store_backups WHERE id = $1",
    [id],
  );
  const row = verify.rows[0] || {};
  const verified = Number(row.user_count) === counts.users
    && Number(row.message_count) === counts.messages
    && Number(row.founding_count) === counts.foundingMembers;
  if (verified) {
    await postgresPool.query("UPDATE llh_store_backups SET verified = TRUE WHERE id = $1", [id]);
  }
  await postgresPool.query(`
    DELETE FROM llh_store_backups
    WHERE id IN (
      SELECT id FROM llh_store_backups
      ORDER BY created_at DESC
      OFFSET $1
    )
  `, [STORE_BACKUP_RETENTION]);
  return { ok: true, id, counts, verified, source };
}

function startStoreBackupScheduler() {
  if (!usePostgresStore()) return;
  if (global.__llhStoreBackupSchedulerStarted) return;
  global.__llhStoreBackupSchedulerStarted = true;
  const tick = async () => {
    if (!databaseReady || !postgresPool) return;
    try {
      const latest = await postgresPool.query(
        "SELECT created_at FROM llh_store_backups ORDER BY created_at DESC LIMIT 1",
      );
      const lastMs = latest.rows[0]?.created_at ? new Date(latest.rows[0].created_at).getTime() : 0;
      if (lastMs && Date.now() - lastMs < STORE_BACKUP_INTERVAL_MS) return;
      const result = await createLogicalStoreBackup({ source: "daily" });
      if (result.ok) {
        console.log(`[store-backup] created ${result.id} users=${result.counts.users} verified=${result.verified}`);
      }
    } catch (error) {
      console.warn("[store-backup] scheduled backup failed:", error.message || error);
    }
  };
  setTimeout(() => { tick().catch(() => {}); }, 45 * 1000);
  setInterval(() => { tick().catch(() => {}); }, 60 * 60 * 1000);
}

function writeLocalJsonStore(store) {
  if (isProductionPostgresDeployment()) {
    storeWriteMetrics.ephemeralOnlyAttempts += 1;
    logStorePersistence("ephemeral_only", {
      action: "skip_local_json",
      note: "Render ephemeral filesystem — not treating local file as durable",
    });
    return;
  }
  ensureStore();
  fs.writeFileSync(storePath, JSON.stringify(store, null, 2));
}

function scheduleDebouncedPostgresStoreWrite() {
  if (!usePostgresStore() || !postgresPool || !databaseReady) return;
  if (debouncedStoreWriteTimer) {
    storeWriteMetrics.debouncedCoalesced += 1;
  } else {
    storeWriteMetrics.debouncedScheduled += 1;
  }
  debouncedStoreWritePending = true;
  if (debouncedStoreWriteTimer) clearTimeout(debouncedStoreWriteTimer);
  debouncedStoreWriteTimer = setTimeout(() => {
    debouncedStoreWriteTimer = null;
    if (!debouncedStoreWritePending) return;
    debouncedStoreWritePending = false;
    storeWriteMetrics.debouncedFlushed += 1;
    logStorePersistence("debounced_flushed", {});
    enqueuePostgresStoreWrite().writePromise.catch((error) => {
      if (error?.code === "store_count_drop_blocked") {
        console.error("[store] debounced write blocked by inventory guard:", error.message);
        return;
      }
      logStorePersistence("failed_write", { action: "debounced_flush", error: error.message || String(error) });
    });
  }, STORE_WRITE_DEBOUNCE_MS);
}

async function flushPendingStoreWritesForShutdown() {
  if (shutdownFlushInProgress) return;
  shutdownFlushInProgress = true;
  logStorePersistence("shutdown_flush_start", {});
  try {
    await flushDebouncedPostgresStoreWrite();
    await postgresWriteChain.catch(() => {});
  } catch (error) {
    logStorePersistence("shutdown_flush_failed", { error: error.message || String(error) });
  }
  logStorePersistence("shutdown_flush_complete", {});
}

function registerGracefulShutdownHandlers() {
  if (global.__llhShutdownHandlersRegistered) return;
  global.__llhShutdownHandlersRegistered = true;
  const onSignal = (signal) => {
    logStorePersistence("temporary_deploy_disconnect", {
      signal,
      note: "graceful shutdown — flushing debounced store writes before exit",
    });
    flushPendingStoreWritesForShutdown()
      .then(() => process.exit(0))
      .catch(() => process.exit(1));
  };
  process.once("SIGTERM", () => onSignal("SIGTERM"));
  process.once("SIGINT", () => onSignal("SIGINT"));
}

function startAnalyticsRetentionScheduler() {
  if (!usePostgresStore() || global.__llhAnalyticsPruneStarted) return;
  global.__llhAnalyticsPruneStarted = true;
  const tick = async () => {
    if (!postgresPool || !databaseReady) return;
    try {
      const result = await analyticsStore.pruneOldAnalyticsEvents(
        postgresPool,
        postgresQueryWithTransientRetry,
        { retentionDays: ANALYTICS_TABLE_RETENTION_DAYS, maxRows: ANALYTICS_TABLE_MAX_ROWS },
      );
      if (result.deletedByAge || result.deletedByCount) {
        console.log("[analytics] pruned table rows", result);
      }
    } catch (error) {
      console.warn("[analytics] retention prune skipped:", error.message);
    }
  };
  setTimeout(() => { tick().catch(() => {}); }, 60 * 1000);
  setInterval(() => { tick().catch(() => {}); }, ANALYTICS_PRUNE_INTERVAL_MS);
}

async function flushDebouncedPostgresStoreWrite() {
  if (debouncedStoreWriteTimer) {
    clearTimeout(debouncedStoreWriteTimer);
    debouncedStoreWriteTimer = null;
  }
  if (!debouncedStoreWritePending) return;
  debouncedStoreWritePending = false;
  if (!usePostgresStore() || !postgresPool || !databaseReady) return;
  const { writePromise } = enqueuePostgresStoreWrite();
  await writePromise.catch((error) => {
    if (error?.code !== "store_count_drop_blocked") throw error;
  });
}

async function executePostgresStoreUpsert(payload, nextCounts) {
  let lastError;
  for (let attempt = 0; attempt <= POSTGRES_STORE_WRITE_RETRY_COUNT; attempt += 1) {
    const started = Date.now();
    try {
      const client = await postgresPool.connect();
      try {
        await client.query("BEGIN");
        await client.query(
          "SELECT pg_advisory_xact_lock($1, hashtext($2))",
          [FOUNDING_ADVISORY_LOCK_NS, `founding:${storeRecordId}`],
        );
        await client.query(POSTGRES_UPSERT_STORE, [storeRecordId, payload]);
        await client.query("COMMIT");
      } catch (error) {
        try { await client.query("ROLLBACK"); } catch { /* ignore */ }
        throw error;
      } finally {
        client.release();
      }
      const durationMs = Date.now() - started;
      storeWriteMetricsLib.recordWriteSuccess(storeWriteMetrics, durationMs);
      if (attempt > 0) {
        storeWriteMetrics.retrySuccesses += 1;
        logStorePersistence("retry_success", { attempt, durationMs, payloadBytes: payload.length });
      }
      databaseReady = true;
      lastPostgresError = "";
      lastPersistedStoreCounts = nextCounts;
      return;
    } catch (error) {
      lastError = error;
      const canRetry = isTransientPostgresConnectionError(error) && attempt < POSTGRES_STORE_WRITE_RETRY_COUNT;
      if (!canRetry) throw error;
      storeWriteMetrics.retryAttempts += 1;
      const delay = POSTGRES_WRITE_RETRY_BACKOFF_MS[Math.min(attempt, POSTGRES_WRITE_RETRY_BACKOFF_MS.length - 1)];
      logStorePersistence("write_retry", {
        attempt: attempt + 1,
        maxAttempts: POSTGRES_STORE_WRITE_RETRY_COUNT,
        delayMs: delay,
        error: error.message || String(error),
      });
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
  throw lastError;
}

function enqueuePostgresStoreWrite() {
  const writeGeneration = ++postgresWriteGeneration;
  const writePromise = (async () => {
    try {
      await withTimeout(
        postgresWriteChain.catch((error) => {
          console.error("Pending write chain error before async write:", error.message);
        }),
        POSTGRES_WRITE_CHAIN_WAIT_MS,
        "Pending Postgres write chain",
      );
    } catch (error) {
      console.error(error.message);
      // Break a stuck chain so the latest full-state write can proceed.
      postgresWriteChain = Promise.resolve();
    }
    if (writeGeneration !== postgresWriteGeneration) {
      storeWriteMetrics.staleGenerationsSkipped += 1;
      console.log("[store-write] skip stale generation", {
        writeGeneration,
        latest: postgresWriteGeneration,
      });
      return;
    }
    const pruned = testAccountGuard.pruneEphemeralTestAccountsFromStore(storeCache);
    if (pruned.removedUsers || pruned.removedFeatureRequests) {
      console.log("[test-account-guard] pruned ephemeral test accounts before Postgres write", pruned);
    }
    let nextCounts;
    try {
      nextCounts = assertSafePostgresStoreReplacement(storeCache);
    } catch (error) {
      maybeAlertStoreSafety("store_replacement_blocked", {
        code: error.code || "store_count_drop_blocked",
        dropReasons: error.dropReasons || [],
        previousCounts: error.previousCounts || lastPersistedStoreCounts,
        nextCounts: error.nextCounts || storeInventoryCounts(storeCache),
      }).catch(() => {});
      throw error;
    }
    const payload = JSON.stringify(storeCache);
    storeWriteMetricsLib.recordWriteStart(storeWriteMetrics, Buffer.byteLength(payload, "utf8"));
    logStorePersistence("full_store_write_start", {
      generation: writeGeneration,
      payloadBytes: Buffer.byteLength(payload, "utf8"),
    });
    await executePostgresStoreUpsert(payload, nextCounts);
    logStorePersistence("full_store_write_success", {
      generation: writeGeneration,
      payloadBytes: Buffer.byteLength(payload, "utf8"),
      lastDurationMs: storeWriteMetrics.lastDurationMs,
    });
  })();
  postgresWriteChain = writePromise.catch((error) => {
    if (error?.code !== "store_count_drop_blocked") {
      databaseReady = false;
      lastPostgresError = error.message || "Postgres store write failed.";
      storeWriteMetricsLib.recordWriteFailure(storeWriteMetrics);
      logStorePersistence("failed_write", { error: lastPostgresError });
      maybeAlertPostgresDisconnect("postgres_write_failed");
    }
    console.error("Could not persist launch store to Postgres:", lastPostgresError || error.message);
  });
  return { writeGeneration, writePromise };
}

// Analytics/adminSession/etc. often do readStore() → mutate → writeStore().
// If a curriculum/site-content write landed in between, the stale clone would wipe
// siteContent (including curriculum). Keep the newer siteContent by updatedAt stamp.
function mergeStorePreferNewerSiteContent(incomingStore) {
  if (!storeCache || !incomingStore || typeof incomingStore !== "object") return incomingStore;
  const incomingStamp = normalizedShortText(incomingStore.siteContent?.updatedAt, 80);
  const cachedStamp = normalizedShortText(storeCache.siteContent?.updatedAt, 80);
  if (cachedStamp && (!incomingStamp || cachedStamp > incomingStamp)) {
    console.log("[store-write] preserve newer siteContent", {
      incomingStamp: incomingStamp || "(empty)",
      cachedStamp,
    });
    return {
      ...incomingStore,
      siteContent: storeCache.siteContent,
    };
  }
  return incomingStore;
}

// Same race class as siteContent: a stale writeStore(readStore()) clone captured before
// createAdminToken() used to wipe live adminSessions, leaving the browser "unlocked"
// while every /api/admin/* call returned "Admin access is required."
function mergeStorePreserveAdminSessions(incomingStore) {
  if (!incomingStore || typeof incomingStore !== "object") return incomingStore;
  const cachedSessions = storeCache?.adminSessions || {};
  const incomingSessions = incomingStore.adminSessions || {};
  if (!Object.keys(cachedSessions).length && !Object.keys(incomingSessions).length) {
    return incomingStore;
  }
  const mergedSessions = { ...incomingSessions };
  let preserved = 0;
  Object.entries(cachedSessions).forEach(([token, session]) => {
    if (!mergedSessions[token]) {
      mergedSessions[token] = session;
      preserved += 1;
      return;
    }
    const cachedMs = Date.parse(session?.createdAt || "") || 0;
    const incomingMs = Date.parse(mergedSessions[token]?.createdAt || "") || 0;
    if (cachedMs > incomingMs) {
      mergedSessions[token] = session;
      preserved += 1;
    }
  });
  if (preserved) {
    console.log("[store-write] preserve adminSessions", {
      preserved,
      total: Object.keys(mergedSessions).length,
    });
  }
  return {
    ...incomingStore,
    adminSessions: mergedSessions,
  };
}

function mergeStorePreserveEmailCampaigns(incomingStore) {
  const cachedCampaigns = storeCache?.emailEngagement?.campaigns;
  if (!cachedCampaigns || typeof cachedCampaigns !== "object" || !Object.keys(cachedCampaigns).length) {
    return incomingStore;
  }
  const incomingEngagement = incomingStore?.emailEngagement && typeof incomingStore.emailEngagement === "object"
    ? incomingStore.emailEngagement
    : {};
  return {
    ...incomingStore,
    emailEngagement: {
      ...incomingEngagement,
      campaigns: {
        ...(incomingEngagement.campaigns || {}),
        ...cachedCampaigns,
      },
    },
  };
}

function mergeStorePreserveSignupTransactionalStamps(store) {
  if (!store?.users || !storeCache?.users) return store;
  for (const [email, incoming] of Object.entries(store.users)) {
    if (!incoming || typeof incoming !== "object") continue;
    const live = storeCache.users[email] || storeCache.users[normalizeEmail(email)];
    if (!live) continue;
    preserveSignupTransactionalFields(incoming, live, incoming);
  }
  return store;
}

// Welcome/admin alert paths often hold a writableStore() reference across awaits.
// Concurrent analytics writeStoreAsync() replaces storeCache; a later writeStore(stale)
// must not wipe newer analyticsEvents (or the reverse for a stale analytics clone).
function mergeStorePreserveAnalyticsEvents(incomingStore) {
  if (!incomingStore || typeof incomingStore !== "object") return incomingStore;
  const cached = Array.isArray(storeCache?.analyticsEvents) ? storeCache.analyticsEvents : [];
  const incoming = Array.isArray(incomingStore.analyticsEvents) ? incomingStore.analyticsEvents : [];
  if (!cached.length && !incoming.length) return incomingStore;
  if (!cached.length) return incomingStore;
  if (!incoming.length) {
    return { ...incomingStore, analyticsEvents: cached.slice() };
  }
  const byId = new Map();
  incoming.forEach((evt) => {
    if (evt?.id) byId.set(evt.id, evt);
  });
  let added = 0;
  cached.forEach((evt) => {
    if (evt?.id && !byId.has(evt.id)) {
      byId.set(evt.id, evt);
      added += 1;
    }
  });
  if (!added && incoming.length >= cached.length) return incomingStore;
  const merged = Array.from(byId.values()).sort(
    (a, b) => new Date(a.createdAt || 0) - new Date(b.createdAt || 0),
  );
  // Soft cap here (MAX_ANALYTICS_EVENTS is declared later); pruneAnalyticsEventsInStore enforces the real cap.
  const cap = 5000;
  return {
    ...incomingStore,
    analyticsEvents: merged.length > cap ? merged.slice(-cap) : merged,
  };
}

function applyStoreWriteMerges(store, { preferIncomingSiteContent = false } = {}) {
  let next = mergeStorePreserveSignupTransactionalStamps(store);
  next = mergeStorePreserveAnalyticsEvents(next);
  if (!preferIncomingSiteContent) {
    next = mergeStorePreferNewerSiteContent(next);
  }
  next = mergeStorePreserveAdminSessions(next);
  next = mergeStorePreserveEmailCampaigns(next);
  return next;
}

function writeStore(store, { immediate = true, debounced = false } = {}) {
  const nextStore = applyStoreWriteMerges(store);
  storeCache = nextStore;
  // Only upsert to Postgres after the authentic DB store is loaded. While on local
  // fallback, never push a sparse in-memory store over production membership data.
  if (usePostgresStore() && postgresPool && databaseReady) {
    if (debounced && !immediate) {
      scheduleDebouncedPostgresStoreWrite();
    } else {
      enqueuePostgresStoreWrite().writePromise.catch((error) => {
        if (error?.code === "store_count_drop_blocked") {
          console.error("[store] fire-and-forget write blocked by inventory guard:", error.message);
        }
      });
    }
    return;
  }
  if (usePostgresStore() && !databaseReady) {
    logStorePersistence("database_unavailable", {
      action: "writeStore_memory_only",
      note: "Changes kept in memory only until Postgres reconnects",
    });
    return;
  }
  writeLocalJsonStore(nextStore);
  stampLocalStoreCacheMtime(nextStore);
}

function stampLocalStoreCacheMtime(store) {
  if (!store || usePostgresStore()) return;
  try {
    store._llhLocalMtimeMs = fs.statSync(storePath).mtimeMs;
  } catch {
    /* ignore */
  }
}

// Writes the store and waits for the Postgres write to complete before returning.
// Throws if the database write fails so the caller can surface the error to the client
// instead of reporting a false success. Use this for admin writes where persistence must
// be confirmed before responding (e.g. lesson plan visibility changes, site content saves).
async function writeStoreAsync(store) {
  // Intentional full-state writes (curriculum / site-content) may carry a newer stamp.
  // Do not merge-prefer siteContent from cache — the caller already built the next siteContent.
  // Still preserve adminSessions, signup email stamps, and analyticsEvents against races.
  storeCache = applyStoreWriteMerges(store, { preferIncomingSiteContent: true });
  if (usePostgresStore() && !databaseReady) {
    logStorePersistence("database_unavailable", {
      action: "writeStoreAsync_rejected",
      note: "Refusing to report success without Postgres persistence",
    });
    throw createStorePersistenceError(
      "Database is not ready. Your changes were not saved to production storage.",
      "store_not_persisted",
      { persistence: "memory_only" },
    );
  }
  if (usePostgresStore() && postgresPool && databaseReady) {
    try {
      await flushDebouncedPostgresStoreWrite();
      const { writeGeneration, writePromise } = enqueuePostgresStoreWrite();
      await writePromise;
      // If a newer write superseded us while we waited, wait for that newer persist too
      // so the caller does not return success before the latest state is durable.
      if (writeGeneration !== postgresWriteGeneration) {
        await postgresWriteChain.catch(() => {});
      }
      return;
    } catch (error) {
      // Never persist a blocked destructive replacement to local JSON — that recreates the wipe path.
      if (error?.code === "store_count_drop_blocked") {
        console.error("[store] Postgres writeAsync blocked by inventory guard:", error.message);
        throw error;
      }
      databaseReady = false;
      lastPostgresError = error.message || "Postgres store write failed.";
      logStorePersistence("failed_write", { action: "writeStoreAsync", error: lastPostgresError });
      maybeAlertPostgresDisconnect("postgres_write_async_failed");
      throw createStorePersistenceError(
        "Could not save to the database. Please try again in a moment.",
        "store_write_failed",
        { persistence: "none", cause: lastPostgresError },
      );
    }
  }
  writeLocalJsonStore(storeCache);
  stampLocalStoreCacheMtime(storeCache);
}

function storePersistenceFailureStatus(error) {
  return error?.code === "store_not_persisted" || error?.code === "store_write_failed" ? 503 : 500;
}

/** Await durable Postgres persistence; return false and respond 503 on failure. */
async function persistStoreOr503(store, response, failMessage = "Could not save. Please try again.") {
  try {
    await writeStoreAsync(store);
    return true;
  } catch (error) {
    jsonResponse(response, storePersistenceFailureStatus(error), {
      ok: false,
      error: failMessage,
      code: error?.code || "store_write_failed",
    });
    return false;
  }
}

/** Await durable Postgres persistence before returning success to the client. */
async function respondAfterPersist(store, response, status, body, failMessage = "Could not save. Please try again.") {
  if (!(await persistStoreOr503(store, response, failMessage))) return;
  jsonResponse(response, status, body);
}

function normalizeEmail(email) {
  return String(email || "").trim().toLowerCase();
}

async function claimEmailCampaignDelivery({ campaignId, email, contentHash }) {
  const cleanEmail = normalizeEmail(email);
  if (usePostgresStore()) {
    const inserted = await postgresPool.query(
      `INSERT INTO llh_email_campaign_deliveries
        (campaign_id, email, content_hash, status)
       VALUES ($1, $2, $3, 'pending')
       ON CONFLICT (campaign_id, email) DO NOTHING
       RETURNING campaign_id, email, content_hash, status, provider, message_id, error, claimed_at, completed_at`,
      [campaignId, cleanEmail, contentHash],
    );
    if (inserted.rows[0]) return { claimed: true, delivery: inserted.rows[0] };
    const reclaimed = await postgresPool.query(
      `UPDATE llh_email_campaign_deliveries
       SET claimed_at = NOW(), error = ''
       WHERE campaign_id = $1 AND email = $2 AND status = 'pending'
         AND claimed_at < NOW() - INTERVAL '30 minutes'
         AND claimed_at > NOW() - INTERVAL '24 hours'
       RETURNING campaign_id, email, content_hash, status, provider, message_id, error, claimed_at, completed_at`,
      [campaignId, cleanEmail],
    );
    if (reclaimed.rows[0]) return { claimed: true, reclaimed: true, delivery: reclaimed.rows[0] };
    const existing = await postgresPool.query(
      `SELECT campaign_id, email, content_hash, status, provider, message_id, error, claimed_at, completed_at
       FROM llh_email_campaign_deliveries WHERE campaign_id = $1 AND email = $2`,
      [campaignId, cleanEmail],
    );
    return { claimed: false, delivery: existing.rows[0] || null };
  }
  const store = readStore();
  store.emailCampaignDeliveries = store.emailCampaignDeliveries || {};
  const key = `${campaignId}:${cleanEmail}`;
  if (store.emailCampaignDeliveries[key]) {
    return { claimed: false, delivery: store.emailCampaignDeliveries[key] };
  }
  const delivery = {
    campaign_id: campaignId,
    email: cleanEmail,
    content_hash: contentHash,
    status: "pending",
    provider: "",
    message_id: "",
    error: "",
    claimed_at: new Date().toISOString(),
    completed_at: null,
  };
  store.emailCampaignDeliveries[key] = delivery;
  await writeStoreAsync(store);
  return { claimed: true, delivery };
}

async function completeEmailCampaignDelivery({ campaignId, email, status, provider = "", messageId = "", error = "" }) {
  const cleanEmail = normalizeEmail(email);
  if (usePostgresStore()) {
    await postgresPool.query(
      `UPDATE llh_email_campaign_deliveries
       SET status = $3, provider = $4, message_id = $5, error = $6, completed_at = NOW()
       WHERE campaign_id = $1 AND email = $2`,
      [campaignId, cleanEmail, status, provider, messageId, error],
    );
    return;
  }
  const store = readStore();
  store.emailCampaignDeliveries = store.emailCampaignDeliveries || {};
  const key = `${campaignId}:${cleanEmail}`;
  if (store.emailCampaignDeliveries[key]) {
    Object.assign(store.emailCampaignDeliveries[key], {
      status,
      provider,
      message_id: messageId,
      error,
      completed_at: new Date().toISOString(),
    });
    await writeStoreAsync(store);
  }
}

async function listEmailCampaignDeliveries(campaignId) {
  if (usePostgresStore()) {
    const result = await postgresPool.query(
      `SELECT campaign_id, email, content_hash, status, provider, message_id, error, claimed_at, completed_at
       FROM llh_email_campaign_deliveries WHERE campaign_id = $1 ORDER BY claimed_at ASC`,
      [campaignId],
    );
    return result.rows;
  }
  const store = readStore();
  return Object.values(store.emailCampaignDeliveries || {}).filter((delivery) => delivery.campaign_id === campaignId);
}

async function patchEmailCampaignState(campaignId, patch = {}) {
  if (usePostgresStore()) {
    const previousWrites = postgresWriteChain;
    const patchPromise = (async () => {
      await previousWrites.catch(() => {});
      await postgresPool.query(
        `UPDATE llh_store
         SET data = jsonb_set(
           data, '{emailEngagement}',
           COALESCE(data -> 'emailEngagement', '{}'::jsonb)
           || jsonb_build_object(
             'campaigns',
             COALESCE(data #> '{emailEngagement,campaigns}', '{}'::jsonb)
             || jsonb_build_object(
               $2::text,
               COALESCE(data #> ARRAY['emailEngagement', 'campaigns', $2::text], '{}'::jsonb) || $3::jsonb
             )
           ),
           true
         ), updated_at = NOW()
         WHERE id = $1`,
        [storeRecordId, campaignId, JSON.stringify(patch)],
      );
      storeCache = storeCache || defaultStore();
      storeCache.emailEngagement = storeCache.emailEngagement && typeof storeCache.emailEngagement === "object"
        ? storeCache.emailEngagement
        : defaultEmailEngagementStore();
      storeCache.emailEngagement.campaigns = storeCache.emailEngagement.campaigns || {};
      storeCache.emailEngagement.campaigns[campaignId] = {
        ...(storeCache.emailEngagement.campaigns[campaignId] || {}),
        ...patch,
      };
      return storeCache.emailEngagement.campaigns[campaignId];
    })();
    postgresWriteChain = patchPromise.catch((error) => {
      databaseReady = false;
      lastPostgresError = error.message || "Postgres email campaign patch failed.";
      console.error(lastPostgresError);
    });
    return await patchPromise;
  }
  const store = readStore();
  store.emailEngagement = store.emailEngagement && typeof store.emailEngagement === "object"
    ? store.emailEngagement
    : defaultEmailEngagementStore();
  store.emailEngagement.campaigns = store.emailEngagement.campaigns || {};
  store.emailEngagement.campaigns[campaignId] = {
    ...(store.emailEngagement.campaigns[campaignId] || {}),
    ...patch,
  };
  await writeStoreAsync(store);
  return store.emailEngagement.campaigns[campaignId];
}

function securityResponseHeaders(extra = {}) {
  return {
    "Referrer-Policy": "strict-origin-when-cross-origin",
    ...extra,
  };
}

function jsonResponse(response, statusCode, payload, extraHeaders = null) {
  const headers = securityResponseHeaders({
    "Content-Type": "application/json; charset=utf-8",
    "Cache-Control": "no-store",
    ...(extraHeaders && typeof extraHeaders === "object" ? extraHeaders : {}),
  });
  if (payload && typeof payload === "object" && payload.correlationId) {
    headers["X-Correlation-Id"] = String(payload.correlationId).slice(0, 80);
    headers["X-Request-Id"] = String(payload.correlationId).slice(0, 80);
  }
  response.writeHead(statusCode, headers);
  response.end(JSON.stringify(payload));
}

function textResponse(response, statusCode, text, type = "text/plain; charset=utf-8") {
  response.writeHead(statusCode, securityResponseHeaders({ "Content-Type": type }));
  response.end(text);
}

function headResponse(response, statusCode, type = "text/plain; charset=utf-8") {
  response.writeHead(statusCode, securityResponseHeaders({ "Content-Type": type }));
  response.end();
}

function readBody(request) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    request.on("data", (chunk) => chunks.push(chunk));
    request.on("end", () => resolve(Buffer.concat(chunks)));
    request.on("error", reject);
  });
}

async function readJson(request) {
  const body = await readBody(request);
  if (!body.length) return {};
  return JSON.parse(body.toString("utf8"));
}

function timingSafeEqualText(left, right) {
  const leftBuffer = Buffer.from(String(left || ""));
  const rightBuffer = Buffer.from(String(right || ""));
  if (!leftBuffer.length || leftBuffer.length !== rightBuffer.length) return false;
  return crypto.timingSafeEqual(leftBuffer, rightBuffer);
}

function base64UrlJson(value) {
  const normalized = String(value || "").replace(/-/g, "+").replace(/_/g, "/");
  const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, "=");
  return JSON.parse(Buffer.from(padded, "base64").toString("utf8"));
}

function base64UrlBuffer(value) {
  const normalized = String(value || "").replace(/-/g, "+").replace(/_/g, "/");
  const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, "=");
  return Buffer.from(padded, "base64");
}

async function firebaseCertificates() {
  if (firebaseCertCache.expiresAt > Date.now() && Object.keys(firebaseCertCache.certs).length) {
    return firebaseCertCache.certs;
  }
  const response = await fetch(FIREBASE_CERT_URL);
  if (!response.ok) throw new Error("Could not load Firebase verification certificates.");
  const cacheControl = response.headers.get("cache-control") || "";
  const maxAge = Number(cacheControl.match(/max-age=(\d+)/)?.[1] || 3600);
  firebaseCertCache = {
    certs: await response.json(),
    expiresAt: Date.now() + (maxAge * 1000),
  };
  return firebaseCertCache.certs;
}

async function verifyFirebaseUser(request) {
  if (!firebaseConfigStatus().ready) throw new Error("Firebase Auth is not configured on the server.");
  const authHeader = String(request.headers.authorization || "");
  const token = authHeader.startsWith("Bearer ") ? authHeader.slice(7) : "";
  if (!token) throw new Error("Please log in before saving child data.");
  const parts = token.split(".");
  if (parts.length !== 3) throw new Error("Invalid login token.");
  const [encodedHeader, encodedPayload, encodedSignature] = parts;
  const header = base64UrlJson(encodedHeader);
  const payload = base64UrlJson(encodedPayload);
  if (header.alg !== "RS256" || !header.kid) throw new Error("Invalid login token.");
  const cert = (await firebaseCertificates())[header.kid];
  if (!cert) throw new Error("Firebase login token could not be verified.");
  const verifier = crypto.createVerify("RSA-SHA256");
  verifier.update(`${encodedHeader}.${encodedPayload}`);
  verifier.end();
  if (!verifier.verify(cert, base64UrlBuffer(encodedSignature))) {
    throw new Error("Firebase login token signature did not match.");
  }
  const now = Math.floor(Date.now() / 1000);
  if (payload.aud !== FIREBASE_PROJECT_ID) throw new Error("Firebase login token is for the wrong project.");
  if (payload.iss !== `https://securetoken.google.com/${FIREBASE_PROJECT_ID}`) throw new Error("Firebase login token issuer did not match.");
  if (Number(payload.exp || 0) <= now) throw new Error("Please log in again before saving child data.");
  if (Number(payload.iat || 0) > now + 300) throw new Error("Firebase login token time was invalid.");
  if (!payload.sub) throw new Error("Firebase login token is missing a user id.");
  return {
    uid: String(payload.sub),
    email: normalizeEmail(payload.email || ""),
  };
}

async function resolveCurriculumAccessUser(request, url) {
  // Prefer Authorization Bearer (same as other admin APIs); legacy ?adminToken= still works.
  const adminToken = extractAdminToken(request, url);
  if (adminToken && validAdminToken(adminToken)) {
    return { authorized: true, email: "", user: null, source: "admin" };
  }
  let identity = null;
  if (firebaseConfigStatus().ready) {
    try {
      identity = await verifyFirebaseUser(request);
    } catch {
      identity = null;
    }
  }
  if (!identity && process.env.NODE_ENV === "test") {
    const authHeader = String(request.headers.authorization || "");
    if (authHeader.startsWith("Bearer test:")) {
      const email = normalizeEmail(authHeader.slice("Bearer test:".length).trim());
      if (email) identity = { uid: `test-${email}`, email };
    }
  }
  // Local/demo fallback so Free grandfathering can personalize curriculum without Firebase.
  if (!identity) {
    const allowHeaderIdentity = process.env.NODE_ENV === "test"
      || String(process.env.DATABASE_PROVIDER || "").toLowerCase() === "local-json";
    if (allowHeaderIdentity) {
      const headerEmail = normalizeEmail(request.headers["x-llh-user-email"] || "");
      if (headerEmail) identity = { uid: `local-${headerEmail}`, email: headerEmail };
    }
  }
  if (!identity?.email) {
    return { authorized: false, email: "", user: null, source: "anonymous" };
  }
  const store = readStore();
  const user = store.users?.[identity.email] || { email: identity.email };
  // Platform owner aliases always receive full curriculum content, independent of
  // the Free/Pro membership row used for billing experiments.
  if (isConfiguredAdminEmail(identity.email)) {
    return {
      authorized: true,
      email: identity.email,
      user,
      source: "admin-owner",
    };
  }
  // Staff/directors inherit the program owner's paid access for curriculum gates.
  const ownerEmail = programOwnership.resolveOwnerEmailForUser(user, identity.email);
  const accessRecord = (ownerEmail && store.users?.[ownerEmail]) || user;
  return {
    authorized: membershipHasProAccess(accessRecord),
    email: identity.email,
    user: accessRecord,
    source: "user",
  };
}

// Admin sessions are persisted by adminSessionStore (its own Postgres table / local
// file — see server/admin-session-store.js), NOT inside storeCache.adminSessions.
// This used to call writeStoreAsync(storeCache), which serialized and rewrote the
// entire multi-MB application store on every single admin login; it now writes
// exactly one session row. store.adminSessions itself is retained only as the
// legacy field that boot-time migration reads once (see initializeStorage()).
async function createAdminToken(email) {
  return adminSessionStore.create(normalizeEmail(email));
}

function foundingClaimedCount(store) {
  purgeExpiredFoundingReservations(store);
  return Math.min(PUBLIC_FOUNDING_CLAIMED_BASE + (store.foundingMembers || []).length, FOUNDING_LIMIT);
}

/** Public acquisition for Founding is closed. Inventory helpers still track historical claims. */
const FOUNDING_ACQUISITION_CLOSED = true;

function foundingSpotsRemaining(store) {
  if (FOUNDING_ACQUISITION_CLOSED) return 0;
  return Math.max(FOUNDING_LIMIT - foundingClaimedCount(store), 0);
}

function foundingStatusPayload(store = readStore()) {
  seedDefaultPromoCodes(store);
  purgeExpiredFoundingReservations(store);
  const claimed = foundingClaimedCount(store);
  const remaining = foundingSpotsRemaining(store);
  return {
    limit: FOUNDING_LIMIT,
    claimed,
    remaining,
    soldOut: true,
    foundingPrice: "$9.99/month",
    regularMonthlyPrice: "$19.99/month",
    regularAnnualPrice: "$199/year",
    spotsLeftMessage: "Pro is $19.99/month.",
    acquisitionClosed: true,
  };
}

function foundingMemberNumberForEmail(store, email) {
  const clean = normalizeEmail(email);
  const idx = (store.foundingMembers || []).findIndex((value) => normalizeEmail(value) === clean);
  if (idx < 0) return null;
  return PUBLIC_FOUNDING_CLAIMED_BASE + idx + 1;
}

function foundingSoldOutMessage(store = peekStore()) {
  return "Choose Pro Monthly ($19.99/month) or Pro Annual ($199/year).";
}

/** Process-local mutex so two checkouts cannot claim the final Founding spot concurrently. */
let foundingClaimChain = Promise.resolve();
function withFoundingClaimLock(fn) {
  const run = foundingClaimChain.then(() => fn(), () => fn());
  foundingClaimChain = run.then(() => undefined, () => undefined);
  return run;
}

function applyFoundingMemberClaim(store, email) {
  seedDefaultPromoCodes(store);
  purgeExpiredFoundingReservations(store);
  store.foundingMembers = Array.isArray(store.foundingMembers) ? store.foundingMembers : [];
  const clean = normalizeEmail(email);
  if (!clean) {
    return { foundingMember: false, foundingMemberNumber: null, reason: "missing_email" };
  }
  const already = store.foundingMembers.some((value) => normalizeEmail(value) === clean);
  if (!already && foundingSpotsRemaining(store) <= 0) {
    return { foundingMember: false, foundingMemberNumber: null, reason: "sold_out" };
  }
  if (!already) store.foundingMembers.push(clean);
  return {
    foundingMember: true,
    foundingMemberNumber: foundingMemberNumberForEmail(store, clean),
    reason: already ? "already_claimed" : "claimed",
  };
}

function applyFoundingReservation(store, email, details = {}) {
  const clean = normalizeEmail(email);
  store.foundingReservations = Array.isArray(store.foundingReservations) ? store.foundingReservations : [];
  const holdMs = Number(details.ttlMs) > 0 ? Number(details.ttlMs) : FOUNDING_CHECKOUT_HOLD_MS;
  const expiresAt = details.expiresAt
    || (details.permanent ? "" : new Date(Date.now() + holdMs).toISOString());
  const row = {
    email: clean,
    status: "held",
    promoCode: normalizePromoCode(details.promoCode || ""),
    reservedAt: new Date().toISOString(),
    expiresAt,
    reason: details.reason || "checkout",
    sessionId: details.sessionId || "",
    releasableUntilFirstPayment: details.releasableUntilFirstPayment !== false,
  };
  const index = store.foundingReservations.findIndex((item) => normalizeEmail(item.email) === clean && item.status === "held");
  if (index >= 0) store.foundingReservations[index] = { ...store.foundingReservations[index], ...row };
  else store.foundingReservations.unshift(row);
  return expiresAt;
}

function claimFoundingSpot(email) {
  const store = readStore();
  const claim = applyFoundingMemberClaim(store, email);
  if (claim.reason === "claimed") writeStore(store, { immediate: true });
  return {
    foundingMember: Boolean(claim.foundingMember),
    foundingMemberNumber: claim.foundingMemberNumber,
  };
}

/** Hold a Founding spot at promo/checkout signup so inventory stays reserved through the free month. */
function reserveFoundingSpot(email, details = {}) {
  const clean = normalizeEmail(email);
  if (!clean) return { ok: false, reason: "missing_email" };
  const store = readStore();
  const claim = applyFoundingMemberClaim(store, email);
  if (!claim.foundingMember) return { ok: false, reason: claim.reason || "sold_out", ...claim };
  const expiresAt = applyFoundingReservation(store, clean, details);
  writeStore(store, { immediate: true });
  return { ok: true, reserved: true, foundingMember: true, foundingMemberNumber: claim.foundingMemberNumber, expiresAt };
}

/**
 * Persist Founding inventory inside a Postgres transaction:
 * advisory lock + row FOR UPDATE + jsonb patch. Safe across multiple Render instances.
 */
async function mutateFoundingInventoryInPostgres(mutator) {
  if (!postgresPool || !databaseReady) {
    throw new Error("Postgres store is not ready for Founding inventory claims.");
  }
  // Drain in-process writes first so this transaction sees durable state.
  await postgresWriteChain.catch(() => {});
  const client = await postgresPool.connect();
  try {
    await client.query("BEGIN");
    await client.query(
      "SELECT pg_advisory_xact_lock($1, hashtext($2))",
      [FOUNDING_ADVISORY_LOCK_NS, `founding:${storeRecordId}`],
    );
    const result = await client.query(
      "SELECT data FROM llh_store WHERE id = $1 FOR UPDATE",
      [storeRecordId],
    );
    if (!result.rows[0]?.data) {
      await client.query("ROLLBACK");
      return { ok: false, reason: "store_missing" };
    }
    const store = result.rows[0].data;
    const outcome = mutator(store);
    if (outcome?.persist === false) {
      await client.query("ROLLBACK");
      return outcome.result;
    }
    await client.query(
      `UPDATE llh_store
       SET data = jsonb_set(
             jsonb_set(COALESCE(data, '{}'::jsonb), '{foundingMembers}', $2::jsonb, true),
             '{foundingReservations}', $3::jsonb, true
           ),
           updated_at = NOW()
       WHERE id = $1`,
      [
        storeRecordId,
        JSON.stringify(Array.isArray(store.foundingMembers) ? store.foundingMembers : []),
        JSON.stringify(Array.isArray(store.foundingReservations) ? store.foundingReservations : []),
      ],
    );
    if (storeCache && typeof storeCache === "object") {
      storeCache.foundingMembers = Array.isArray(store.foundingMembers) ? store.foundingMembers : [];
      storeCache.foundingReservations = Array.isArray(store.foundingReservations) ? store.foundingReservations : [];
    }
    await client.query("COMMIT");
    return outcome.result;
  } catch (error) {
    try { await client.query("ROLLBACK"); } catch { /* ignore */ }
    throw error;
  } finally {
    client.release();
  }
}

/**
 * Atomic Founding inventory claim for checkout / concurrent last-spot races.
 * - Postgres (production): transaction advisory lock + SELECT FOR UPDATE + jsonb patch
 * - local-json (dev/tests): process mutex + synchronous file write
 * Full-document upserts also union foundingMembers so a stale instance write cannot drop a claim.
 */
async function reserveFoundingSpotAtomic(email, details = {}) {
  return withFoundingClaimLock(async () => {
    const clean = normalizeEmail(email);
    if (!clean) return { ok: false, reason: "missing_email" };

    if (usePostgresStore() && postgresPool && databaseReady) {
      return mutateFoundingInventoryInPostgres((store) => {
        const claim = applyFoundingMemberClaim(store, clean);
        if (!claim.foundingMember) {
          return {
            persist: false,
            result: {
              ok: false,
              reason: claim.reason || "sold_out",
              foundingMember: false,
              foundingMemberNumber: null,
            },
          };
        }
        const expiresAt = applyFoundingReservation(store, clean, details);
        return {
          persist: true,
          result: {
            ok: true,
            reserved: true,
            foundingMember: true,
            foundingMemberNumber: claim.foundingMemberNumber,
            expiresAt,
            reason: claim.reason,
            durable: "postgres",
          },
        };
      });
    }

    const store = readStore();
    const claim = applyFoundingMemberClaim(store, clean);
    if (!claim.foundingMember) {
      return { ok: false, reason: claim.reason || "sold_out", foundingMember: false, foundingMemberNumber: null };
    }
    const expiresAt = applyFoundingReservation(store, clean, details);
    writeStore(store);
    return {
      ok: true,
      reserved: true,
      foundingMember: true,
      foundingMemberNumber: claim.foundingMemberNumber,
      expiresAt,
      reason: claim.reason,
      durable: "local-json",
    };
  });
}

async function claimFoundingSpotAtomic(email) {
  return withFoundingClaimLock(async () => {
    const clean = normalizeEmail(email);
    if (!clean) return { foundingMember: false, foundingMemberNumber: null, reason: "missing_email" };

    if (usePostgresStore() && postgresPool && databaseReady) {
      return mutateFoundingInventoryInPostgres((store) => {
        const claim = applyFoundingMemberClaim(store, clean);
        if (claim.reason !== "claimed" && claim.reason !== "already_claimed") {
          return {
            persist: false,
            result: {
              foundingMember: false,
              foundingMemberNumber: null,
              reason: claim.reason || "sold_out",
            },
          };
        }
        return {
          persist: claim.reason === "claimed",
          result: {
            foundingMember: Boolean(claim.foundingMember),
            foundingMemberNumber: claim.foundingMemberNumber,
            reason: claim.reason,
            durable: "postgres",
          },
        };
      });
    }

    const store = readStore();
    const claim = applyFoundingMemberClaim(store, clean);
    if (claim.reason === "claimed") writeStore(store, { immediate: true });
    return {
      foundingMember: Boolean(claim.foundingMember),
      foundingMemberNumber: claim.foundingMemberNumber,
      reason: claim.reason,
      durable: "local-json",
    };
  });
}

function releaseFoundingSpot(email, reason = "canceled_before_first_payment", options = {}) {
  const clean = normalizeEmail(email);
  if (!clean) return { released: false };
  const store = writableStore();
  const before = (store.foundingMembers || []).length;
  store.foundingMembers = (store.foundingMembers || []).filter((value) => normalizeEmail(value) !== clean);
  store.foundingReservations = (Array.isArray(store.foundingReservations) ? store.foundingReservations : []).map((row) => {
    if (normalizeEmail(row.email) !== clean) return row;
    if (row.status === "released" || row.status === "converted") return row;
    return {
      ...row,
      status: "released",
      releasedAt: new Date().toISOString(),
      releaseReason: reason,
    };
  });
  const released = store.foundingMembers.length < before;
  if ((released || reason) && !options.deferPersist) writeStore(store);
  return { released, foundingMembersRemaining: store.foundingMembers.length };
}

function markFoundingReservationConverted(email, options = {}) {
  const clean = normalizeEmail(email);
  if (!clean) return;
  const store = writableStore();
  let changed = false;
  store.foundingReservations = (Array.isArray(store.foundingReservations) ? store.foundingReservations : []).map((row) => {
    if (normalizeEmail(row.email) !== clean || row.status === "converted") return row;
    changed = true;
    return {
      ...row,
      status: "converted",
      convertedAt: new Date().toISOString(),
      expiresAt: "",
    };
  });
  if (changed && !options.deferPersist) writeStore(store);
}

function userNeverCompletedPaidCycle(user = {}) {
  if (user.firstPaidInvoiceAt || user.firstPaidAt) return false;
  if (user.lastSuccessfulPaymentAt) {
    // Only treat as paid when we recorded a non-zero invoice (see webhook filter).
    return false;
  }
  const stripeStatus = String(user.stripeSubscriptionStatus || "").toLowerCase();
  if (stripeStatus === "trialing") return true;
  if (membershipUserInTrial(user)) return true;
  return !user.lastSuccessfulPaymentAt;
}

function shouldReleaseFoundingSpotOnCancel(user = {}) {
  if (!user) return false;
  const isFounding = Boolean(
    user.foundingMemberActive
    || user.foundingMember
    || user.foundingMemberHistorical
    || user.foundingMemberNumber
    || user.plan === "Founding",
  );
  if (!isFounding) return false;
  if (user.foundingSpotReleasable === false) return false;
  return userNeverCompletedPaidCycle(user);
}

function statusForPlan(planKey, stripeSubscriptionId, status) {
  const config = planConfig[planKey] || planConfig.monthly;
  const normalizedStatus = String(status || "Active").trim();
  const lower = normalizedStatus.toLowerCase();
  const stripeSubscriptionStatus = lower.includes("trial") ? "trialing" : "active";
  const periodDays = lower.includes("trial") ? STANDARD_TRIAL_DAYS : 30;
  const periodEndIso = new Date(Date.now() + periodDays * 86400000).toISOString();
  return {
    plan: config.plan,
    subscriptionCadence: config.cadence,
    subscriptionStatus: `${config.label} Subscription ${normalizedStatus || "Active"}`,
    monthlyPrice: config.amount,
    priceLock: config.priceLock,
    stripeSubscriptionId: stripeSubscriptionId || "",
    stripeSubscriptionStatus,
    currentPeriodEnd: periodEndIso,
    accessEndsAt: periodEndIso,
    cancelAtPeriodEnd: false,
    lastStripeSyncAt: new Date().toISOString(),
  };
}

function logMembershipTransition(stage, email, details = {}) {
  const plan = details.plan || details.membershipPlan || "";
  const status = details.subscriptionStatus || details.membershipStatus || details.stripeSubscriptionStatus || "";
  const access = details.hasProAccess === undefined ? "" : ` hasProAccess=${details.hasProAccess}`;
  console.log(
    `[membership] ${stage} email=${email || "unknown"} plan=${plan || "n/a"} status="${status || "n/a"}"${access}`,
    details.extra ? JSON.stringify(details.extra) : "",
  );
}

function findUserEntryByStripeCustomer(store, customerId, fallbackEmail = "") {
  const cleanCustomer = String(customerId || "").trim();
  if (cleanCustomer) {
    const byCustomer = Object.entries(store.users || {}).find(([, user]) => user.stripeCustomerId === cleanCustomer);
    if (byCustomer) return byCustomer;
  }
  const cleanEmail = normalizeEmail(fallbackEmail);
  if (cleanEmail && store.users?.[cleanEmail]) {
    return [cleanEmail, store.users[cleanEmail]];
  }
  return null;
}

function hasProcessedStripeEvent(eventId) {
  if (!eventId) return false;
  const store = readStore();
  return Boolean(store.processedStripeEvents?.[eventId]);
}

function markProcessedStripeEvent(eventId, options = {}) {
  if (!eventId) return;
  const store = writableStore();
  store.processedStripeEvents = store.processedStripeEvents || {};
  store.processedStripeEvents[eventId] = {
    processedAt: new Date().toISOString(),
  };
  // Keep a bounded idempotency window.
  const ids = Object.keys(store.processedStripeEvents);
  if (ids.length > 500) {
    ids
      .sort((a, b) => String(store.processedStripeEvents[a]?.processedAt || "").localeCompare(String(store.processedStripeEvents[b]?.processedAt || "")))
      .slice(0, ids.length - 500)
      .forEach((id) => {
        delete store.processedStripeEvents[id];
      });
  }
  if (!options.deferPersist) writeStore(store);
}

async function flushDurableStoreOrWebhookError(response, failMessage = "Webhook processing could not persist state.") {
  try {
    // Never re-read from disk here — deferred mutations live on storeCache only until flush.
    const target = storeCache || writableStore();
    if (usePostgresStore() && postgresPool && databaseReady) {
      await writeStoreAsync(target);
    } else {
      writeStore(target);
    }
    return true;
  } catch (error) {
    console.error("[membership] webhook_persist_failed:", error.message || error);
    jsonResponse(response, storePersistenceFailureStatus(error), {
      error: failMessage,
      code: error?.code || "store_write_failed",
    });
    return false;
  }
}

// Persisted (not just console-logged) audit trail for confirmed curriculum
// replace/restore actions — high-impact and rare enough to warrant their own record.
const ENRICHMENT_HISTORY_LIMIT = 250; // effectively unlimited for curriculum upgrade campaigns

function enrichmentHistoryFingerprint(payload) {
  try {
    const raw = JSON.stringify(payload || {});
    return crypto.createHash("sha256").update(raw).digest("hex").slice(0, 24);
  } catch (_error) {
    return `fp-${Date.now()}`;
  }
}

function appendEnrichmentEditorAudit(store, details = {}) {
  store.enrichmentEditorAudit = Array.isArray(store.enrichmentEditorAudit) ? store.enrichmentEditorAudit : [];
  const entry = {
    id: `enrich_audit_${Date.now()}_${crypto.randomBytes(4).toString("hex")}`,
    action: normalizedShortText(details.action, 40) || "unknown",
    lessonPlanId: normalizedShortText(details.lessonPlanId, 160) || "",
    versionId: normalizedShortText(details.versionId, 80) || "",
    adminEmail: normalizedShortText(details.adminEmail, 180) || "unknown",
    fingerprint: normalizedShortText(details.fingerprint, 80) || "",
    note: normalizedShortText(details.note, 300) || "",
    createdAt: new Date().toISOString(),
  };
  store.enrichmentEditorAudit.unshift(entry);
  store.enrichmentEditorAudit = store.enrichmentEditorAudit.slice(0, 2000);
  console.log("[enrichment-editor-audit]", JSON.stringify(entry));
  return entry;
}

function appendCurriculumRestoreAudit(store, { adminToken, before, after, note = "" } = {}) {
  store.curriculumRestoreAudit = Array.isArray(store.curriculumRestoreAudit) ? store.curriculumRestoreAudit : [];
  const session = adminSessionStore.validate(adminToken);
  const entry = {
    id: `curr_restore_${Date.now()}_${crypto.randomBytes(4).toString("hex")}`,
    adminEmail: session?.email || "unknown",
    note: note || "",
    beforeLessonPlans: before?.lessonPlans?.length || 0,
    beforeActivities: before?.activities?.length || 0,
    afterLessonPlans: after?.lessonPlans?.length || 0,
    afterActivities: after?.activities?.length || 0,
    createdAt: new Date().toISOString(),
  };
  store.curriculumRestoreAudit.unshift(entry);
  store.curriculumRestoreAudit = store.curriculumRestoreAudit.slice(0, 200);
  console.log("[curriculum-restore-audit]", JSON.stringify(entry));
  return entry;
}

function appendMembershipLifecycleAudit(email, action, details = {}, options = {}) {
  const store = writableStore();
  store.membershipAudit = store.membershipAudit || [];
  const entry = {
    id: `mem_${Date.now()}_${crypto.randomBytes(4).toString("hex")}`,
    email: normalizeEmail(email),
    action,
    updates: details.updates || {},
    // Optional: before-state and Stripe event/subscription/invoice references, used by
    // the billing reconciliation workflow so every correction has a full audit trail
    // (before/after values + exactly which Stripe records justified the change).
    before: details.before || undefined,
    stripeRefs: details.stripeRefs || undefined,
    adminEmail: details.adminEmail || "system",
    note: details.note || "",
    createdAt: new Date().toISOString(),
  };
  store.membershipAudit.unshift(entry);
  store.membershipAudit = store.membershipAudit.slice(0, 500);
  if (!options.deferPersist) writeStore(store);
  return entry;
}

function appendRoleReconciliationAudit({
  email = "",
  userId = "",
  programId = "",
  previousRole = "",
  newRole = "",
  reason = "",
} = {}, store = null) {
  const cleanEmail = normalizeEmail(email);
  if (!cleanEmail) return null;
  const targetStore = store || readStore();
  targetStore.roleReconciliationAudit = targetStore.roleReconciliationAudit || [];
  const entry = {
    id: `role_rc_${Date.now()}_${crypto.randomBytes(4).toString("hex")}`,
    email: cleanEmail,
    userId: String(userId || "").trim(),
    programId: String(programId || "").trim(),
    previousRole: String(previousRole || "").trim().toLowerCase(),
    newRole: String(newRole || "").trim().toLowerCase(),
    reason: String(reason || "linked_program_member_reconcile").trim(),
    createdAt: new Date().toISOString(),
  };
  targetStore.roleReconciliationAudit.unshift(entry);
  targetStore.roleReconciliationAudit = targetStore.roleReconciliationAudit.slice(0, 500);
  if (!store) writeStore(targetStore);
  console.log("[role-reconciliation-audit]", JSON.stringify(entry));
  return entry;
}

function applyCheckoutMembershipUpgrade(email, {
  planKey,
  customerId,
  subscriptionId,
  promoCode = "",
  promoTrialDays = 0,
  promoLabel = "",
  sessionId = "",
  source = "checkout",
} = {}, options = {}) {
  const persistOpts = options.deferPersist ? { deferPersist: true } : {};
  const cleanEmail = normalizeEmail(email);
  if (!cleanEmail) {
    logMembershipTransition("payment_received_missing_email", "", { extra: { planKey, source, sessionId } });
    return null;
  }
  const founding = planKey === "founding" ? claimFoundingSpot(cleanEmail) : { foundingMember: false, foundingMemberNumber: null };
  if (planKey === "founding" && founding.foundingMember) {
    reserveFoundingSpot(cleanEmail, {
      promoCode,
      reason: "checkout_completed",
      permanent: promoTrialDays > 0,
      releasableUntilFirstPayment: promoTrialDays > 0,
      expiresAt: promoTrialDays > 0 ? "" : "",
      ttlMs: promoTrialDays > 0 ? 0 : FOUNDING_CHECKOUT_HOLD_MS,
    });
  }
  const checkoutTrialUpdates = {};
  const statusLabel = promoTrialDays > 0 ? "trialing" : "Active";
  if (promoTrialDays > 0) {
    const isStandardIntro = Number(promoTrialDays) === STANDARD_TRIAL_DAYS
      && (!promoCode || String(promoLabel || "").includes("7-Day"));
    checkoutTrialUpdates.trialStatus = "In Trial";
    checkoutTrialUpdates.trialStart = new Date().toISOString();
    checkoutTrialUpdates.trialEnd = new Date(Date.now() + promoTrialDays * 86400000).toISOString();
    checkoutTrialUpdates.trialSource = isStandardIntro
      ? trialClassification.STANDARD_TRIAL_KIND
      : trialClassification.PROMO_TRIAL_KIND;
    checkoutTrialUpdates.trialExtensionSource = isStandardIntro
      ? STANDARD_TRIAL_LABEL
      : (promoCode
        ? `Promo code ${normalizePromoCode(promoCode)}${promoLabel ? ` (${promoLabel})` : ""}`
        : (promoLabel || `${promoTrialDays}-day promo trial`));
    checkoutTrialUpdates.promoTrialDays = promoTrialDays;
    // Card-required intro trial is consumed as soon as Checkout completes — even before the first paid invoice.
    checkoutTrialUpdates.introductoryTrialConsumed = true;
    // Seed server-authoritative trial export allowance (3 watermarked premium exports).
    const prior = readStore().users?.[cleanEmail]?.trialCurriculumExports;
    checkoutTrialUpdates.trialCurriculumExports = trialCurriculumExports.normalizeState(prior);
  }
  logMembershipTransition("payment_received", cleanEmail, {
    plan: planConfig[planKey]?.plan || planKey,
    subscriptionStatus: statusLabel,
    extra: { source, sessionId, subscriptionId, customerId },
  });
  const user = upsertUser(cleanEmail, {
    ...statusForPlan(planKey, subscriptionId, statusLabel),
    ...checkoutTrialUpdates,
    stripeCustomerId: customerId,
    foundingMember: planKey === "founding" || founding.foundingMember,
    foundingMemberActive: planKey === "founding",
    foundingMemberHistorical: planKey === "founding" || founding.foundingMember,
    foundingMemberNumber: founding.foundingMemberNumber,
    foundingSpotReleasable: planKey === "founding" && promoTrialDays > 0,
    subscriptionStartedAt: new Date().toISOString(),
    paymentMethod: "Managed in Stripe",
    hasPaymentMethod: true,
    internalAccessOverride: false,
    manualAccessGranted: false,
    pendingPlan: "",
    pendingPromoCode: "",
    pendingTrialDays: 0,
    pendingPromoLabel: "",
    promoCodeUsed: promoCode || undefined,
    promoLabelUsed: promoLabel || undefined,
  }, persistOpts);
  if (promoCode) {
    markPromoRedeemed(cleanEmail, promoCode, {
      label: promoLabel,
      trialDays: promoTrialDays,
      stripeSessionId: sessionId,
      stripeSubscriptionId: subscriptionId,
    }, persistOpts);
  }
  appendBillingEvent(cleanEmail, "checkout_success", planKey, planConfig[planKey]?.amount || "", persistOpts);
  appendMembershipLifecycleAudit(cleanEmail, "membership_assigned", {
    note: `Membership assigned from ${source}`,
    updates: {
      plan: user.plan,
      foundingMemberActive: user.foundingMemberActive,
      stripeSubscriptionStatus: user.stripeSubscriptionStatus,
      hasProAccess: membershipHasProAccess(user),
    },
  }, persistOpts);
  logMembershipTransition("membership_assigned", cleanEmail, {
    plan: user.plan,
    subscriptionStatus: user.subscriptionStatus,
    hasProAccess: membershipHasProAccess(user),
    extra: {
      foundingMemberActive: user.foundingMemberActive,
      foundingMemberNumber: user.foundingMemberNumber,
      stripeSubscriptionStatus: user.stripeSubscriptionStatus,
      source,
    },
  });
  // Welcome messages for NEW Trial/Pro members only (cutoff excludes existing Pros).
  // Never backfills older accounts. Failures must not block checkout membership assignment.
  // Run welcome then admin alert serially so a stale alert snapshot cannot wipe welcome stamps.
  const planLabel = user.plan || planConfig[planKey]?.plan || planKey;
  const isTrial = promoTrialDays > 0 || String(user.stripeSubscriptionStatus || "").toLowerCase() === "trialing";
  const checkoutAlertRef = subscriptionId || sessionId || `checkout:${cleanEmail}:${Date.now()}`;
  const shouldDeliverTrialWelcome = promoTrialDays > 0;
  const shouldDeliverProWelcome = !shouldDeliverTrialWelcome
    && (planKey === "monthly" || planKey === "annual" || planKey === "founding");
  void (async () => {
    try {
      if (typeof onboardingWelcome?.maybeDeliverOnTrialStart === "function" && shouldDeliverTrialWelcome) {
        await onboardingWelcome.maybeDeliverOnTrialStart(cleanEmail);
      } else if (typeof onboardingWelcome?.maybeDeliverOnProPurchase === "function" && shouldDeliverProWelcome) {
        await onboardingWelcome.maybeDeliverOnProPurchase(cleanEmail);
      }
    } catch (error) {
      console.warn("[onboarding-welcome] membership welcome hook skipped:", error.message || error);
    }
    try {
      const storeForAlert = writableStore();
      let type = "admin_new_subscription";
      let title = `New ${planLabel} subscription`;
      if (planKey === "founding") {
        type = "admin_new_founding";
        title = "New Founding Member signup";
      } else if (planKey === "annual") {
        type = "admin_new_annual";
        title = "New Pro Annual signup";
      } else if (isTrial) {
        type = "admin_new_trial";
        title = "New trial started";
      } else if (planKey === "monthly") {
        type = "admin_new_pro";
        title = "New Pro Monthly signup";
      }
      await emitAdminAlertSafe(storeForAlert, {
        category: "billing",
        type,
        title,
        preview: `${cleanEmail} · ${planLabel}${isTrial ? " (trial)" : ""}`,
        email: cleanEmail,
        name: storeForAlert.users?.[cleanEmail]?.name || "",
        refId: checkoutAlertRef,
        sendEmail: true,
        emailKind: "Billing",
        emailFields: [
          ["Plan", planLabel],
          ["Source", source],
          ["Subscription", subscriptionId || ""],
          ["Amount", storeForAlert.users?.[cleanEmail]?.monthlyPrice || ""],
          ["Billing frequency", storeForAlert.users?.[cleanEmail]?.subscriptionCadence || ""],
        ],
        emailExtras: {
          plan: planLabel,
          amount: storeForAlert.users?.[cleanEmail]?.monthlyPrice || "",
          billingFrequency: storeForAlert.users?.[cleanEmail]?.subscriptionCadence || (planKey === "annual" ? "annual" : planKey === "monthly" ? "monthly" : ""),
          trialStart: storeForAlert.users?.[cleanEmail]?.trialStart || storeForAlert.users?.[cleanEmail]?.trialStartedAt || "",
          trialEnd: storeForAlert.users?.[cleanEmail]?.trialEnd || "",
          subscriptionStatus: storeForAlert.users?.[cleanEmail]?.subscriptionStatus || "",
          nextRenewal: storeForAlert.users?.[cleanEmail]?.currentPeriodEnd || "",
        },
      });
      if (!options.deferPersist) {
        writeStore(storeForAlert, { immediate: true });
      }
    } catch (alertError) {
      console.warn("[admin-notifications] checkout alert failed:", alertError?.message || alertError);
    }
  })();
  logMembershipTransition("permissions_updated", cleanEmail, {
    plan: user.plan,
    membershipStatus: membershipStatusDisplay(user),
    hasProAccess: membershipHasProAccess(user),
    extra: { membershipPlan: membershipPlanDisplay(user), source },
  });
  return user;
}

function subscriptionNeedsStripeRepair(subscription) {
  if (!subscription) return false;
  const paidLooking = ["Pro", "Founding"].includes(String(subscription.plan || "").trim())
    || Boolean(subscription.foundingMemberActive)
    || String(subscription.subscriptionStatus || "").toLowerCase().includes("active")
    || String(subscription.subscriptionStatus || "").toLowerCase().includes("trial");
  if (!paidLooking) return false;
  if (!subscription.stripeSubscriptionStatus) return true;
  if (!subscription.stripeCustomerId && !subscription.stripeSubscriptionId) return true;
  return false;
}

function planKeyFromPriceId(priceId) {
  const cleanPriceId = String(priceId || "").trim();
  if (!cleanPriceId) return "";
  const match = Object.entries(planConfig).find(([planKey]) => getPriceId(planKey) === cleanPriceId);
  return match?.[0] || "";
}

function planKeyFromSubscriptionPrice(subscription) {
  const items = subscription?.items?.data || [];
  for (const item of items) {
    const planKey = planKeyFromPriceId(item?.price?.id || item?.plan?.id);
    if (planKey) return planKey;
  }
  return "";
}

function planKeyFromStripe(subscription, user = {}) {
  const metadataPlan = String(subscription?.metadata?.plan || "").trim().toLowerCase();
  if (planConfig[metadataPlan]) return metadataPlan;
  const pricePlan = planKeyFromSubscriptionPrice(subscription);
  if (planConfig[pricePlan]) return pricePlan;
  const pendingPlan = String(user.pendingPlan || "").trim().toLowerCase();
  if (planConfig[pendingPlan]) return pendingPlan;
  if (user.foundingMemberActive || String(user.plan || "").trim() === "Founding") return "founding";
  if (user.subscriptionCadence === "annual") return "annual";
  return "monthly";
}

function stripePriceIdToPlanKeyMap() {
  const map = {};
  Object.keys(planConfig).forEach((planKey) => {
    const priceId = String(getPriceId(planKey) || "").trim();
    if (priceId) map[priceId] = planKey;
  });
  return map;
}

function membershipUpdatesFromStripeSubscription(subscription, user = {}, eventType = "updated") {
  return membershipAccess.stripeSubscriptionToMembershipUpdates(
    subscription,
    { ...user, __priceIdToPlanKey: stripePriceIdToPlanKeyMap() },
    eventType,
  );
}

function repairFoundingMemberPricing(user = {}) {
  if (!user || !membershipAccess.membershipFoundingActive(user)) return user;
  if (user.monthlyPrice === "$9.99/month" && user.plan === "Founding" && user.priceLock === "Lifetime") {
    return user;
  }
  return {
    ...user,
    plan: "Founding",
    monthlyPrice: "$9.99/month",
    priceLock: "Lifetime",
    foundingMemberActive: true,
    foundingMemberHistorical: true,
    foundingMember: true,
  };
}

function reconcileStaleAuthFlags(user = {}) {
  if (!user?.mustChangePassword) return user;
  if (tempPasswordAuth.tempPasswordStillValid(user)) return user;
  if (user.tempPasswordHash || user.mustChangePassword) {
    return tempPasswordAuth.clearTempPasswordFields(user, {
      keepServerPasswordAuth: Boolean(user.serverPasswordAuth || user.passwordHash),
    });
  }
  return user;
}

function upsertUser(email, updates = {}, options = {}) {
  const cleanEmail = normalizeEmail(email);
  if (!options.allowTestAccount && testAccountGuard.shouldRejectTestAccountPersistence(cleanEmail)) {
    const store = writableStore();
    if (store.users?.[cleanEmail]) {
      delete store.users[cleanEmail];
      if (!options.deferPersist) writeStore(store);
    }
    return {
      email: cleanEmail,
      _skippedTestAccount: true,
      plan: updates.plan || "Free",
      ...updates,
    };
  }
  const store = writableStore();
  store.users = store.users || {};
  const existing = store.users[email] || { email };
  const beforeRole = String(existing.role || "").trim().toLowerCase();
  const beforeProgramId = String(existing.programId || "").trim();
  let merged = {
    ...existing,
    ...updates,
    email,
    updatedAt: new Date().toISOString(),
  };
  merged = programOwnership.reconcileLinkedProgramMember(merged, store);
  // Persist normalized accountType + role (defaults: home_daycare / owner).
  const accessFields = accountAccess.migrateAccountAccessFields(merged);
  merged.accountType = accessFields.accountType;
  merged.role = accessFields.role;
  // Keep active founding members on the locked $9.99 price in stored billing fields.
  merged = repairFoundingMemberPricing(merged);
  merged = reconcileStaleAuthFlags(merged);
  const afterRole = String(merged.role || "").trim().toLowerCase();
  const afterProgramId = String(merged.programId || "").trim();
  const linkedOwner = normalizeEmail(merged.linkedProgramOwnerEmail || "");
  const isLinkedMember = Boolean(linkedOwner && linkedOwner !== normalizeEmail(email));
  if (isLinkedMember && (afterRole !== beforeRole || (afterProgramId && afterProgramId !== beforeProgramId))) {
    appendRoleReconciliationAudit({
      email,
      userId: merged.firebaseUid || existing.firebaseUid || "",
      programId: afterProgramId,
      previousRole: beforeRole || "unknown",
      newRole: afterRole,
      reason: options.reconcileReason || "linked_program_member_reconcile",
    }, store);
  }
  store.users[email] = merged;
  if (!options.deferPersist) writeStore(store);
  return store.users[email];
}

function promoRedemptionRecords(store = readStore()) {
  return Array.isArray(store.promoRedemptions) ? store.promoRedemptions : [];
}

function promoUsedByAccount(email, code, store = readStore()) {
  const cleanEmail = normalizeEmail(email);
  const promoCode = normalizePromoCode(code);
  if (!cleanEmail || !promoCode) return false;
  const user = store.users?.[cleanEmail] || {};
  const accountRedemptions = Array.isArray(user.promoRedemptions) ? user.promoRedemptions : [];
  return [...promoRedemptionRecords(store), ...accountRedemptions].some((record) => (
    normalizeEmail(record?.email || cleanEmail) === cleanEmail
    && normalizePromoCode(record?.code || record) === promoCode
  ));
}

function markPromoRedeemed(email, code, details = {}, options = {}) {
  const cleanEmail = normalizeEmail(email);
  const promoCode = normalizePromoCode(code);
  if (!cleanEmail || !promoCode) return null;
  const store = writableStore();
  store.promoRedemptions = promoRedemptionRecords(store);
  const existing = store.promoRedemptions.find((record) => (
    normalizeEmail(record.email) === cleanEmail && normalizePromoCode(record.code) === promoCode
  ));
  const record = existing || {
    id: `promo_${Date.now()}_${crypto.randomBytes(4).toString("hex")}`,
    email: cleanEmail,
    code: promoCode,
    label: details.label || "",
    trialDays: details.trialDays || 0,
    stripeSessionId: details.stripeSessionId || "",
    stripeSubscriptionId: details.stripeSubscriptionId || "",
    redeemedAt: new Date().toISOString(),
  };
  if (!existing) store.promoRedemptions.push(record);
  store.users = store.users || {};
  const user = store.users[cleanEmail] || { email: cleanEmail };
  const userRedemptions = Array.isArray(user.promoRedemptions) ? user.promoRedemptions : [];
  const hasUserRecord = userRedemptions.some((item) => normalizePromoCode(item?.code || item) === promoCode);
  store.users[cleanEmail] = {
    ...user,
    email: cleanEmail,
    promoRedemptions: hasUserRecord ? userRedemptions : [...userRedemptions, record],
    promoTrialDays: details.trialDays || user.promoTrialDays || 0,
    promoRedeemedAt: user.promoRedeemedAt || record.redeemedAt,
    promoCodeUsed: promoCode,
    promoLabelUsed: details.label || user.promoLabelUsed || "",
    updatedAt: new Date().toISOString(),
  };
  if (!options.deferPersist) writeStore(store);
  return record;
}

function getPriceId(planKey) {
  const config = planConfig[planKey];
  if (!config) return "";
  const configured = process.env[config.priceEnv] || "";
  if (configured) return configured;
  if (STRIPE_CHECKOUT_SIMULATION) {
    if (planKey === "founding") return "price_sim_founding_monthly";
    if (planKey === "monthly") return "price_sim_pro_monthly";
    if (planKey === "annual") return "price_sim_pro_annual";
  }
  return "";
}

function requireStripe(response) {
  const status = stripeConfigStatus();
  if (status.checkoutReady || STRIPE_CHECKOUT_SIMULATION) return true;
  jsonResponse(response, 503, {
    error: "Stripe is not configured. Add real Stripe keys and price IDs to .env.",
    missing: status.missing,
  });
  return false;
}

async function stripeRequest(pathname, params) {
  if (STRIPE_CHECKOUT_SIMULATION) {
    if (pathname === "customers") {
      return { id: `cus_sim_${crypto.randomBytes(6).toString("hex")}`, email: params.email || "" };
    }
    if (pathname === "checkout/sessions") {
      const plan = params["metadata[plan]"] || params["subscription_data[metadata][plan]"] || "monthly";
      const price = params["line_items[0][price]"] || "";
      const trialDays = params["subscription_data[trial_period_days]"] || "";
      const paymentMethodCollection = params.payment_method_collection || "";
      const trialMissingPm = params["subscription_data[trial_settings][end_behavior][missing_payment_method]"] || "";
      const promoTrialDays = params["metadata[promoTrialDays]"] || "";
      const query = new URLSearchParams({
        checkout: "simulated",
        plan: String(plan),
        price: String(price),
      });
      if (trialDays) query.set("trial_days", String(trialDays));
      if (promoTrialDays) query.set("promo_trial_days", String(promoTrialDays));
      if (paymentMethodCollection) query.set("payment_method_collection", String(paymentMethodCollection));
      if (trialMissingPm) query.set("trial_missing_pm", String(trialMissingPm));
      return {
        id: `cs_sim_${crypto.randomBytes(8).toString("hex")}`,
        url: `${SITE_URL}/?${query.toString()}`,
        mode: "subscription",
        payment_method_collection: paymentMethodCollection || "always",
        metadata: {
          email: params["metadata[email]"] || "",
          plan,
          promoTrialDays: String(promoTrialDays || trialDays || ""),
          promoLabel: params["metadata[promoLabel]"] || "",
          trial7day: params["metadata[trial7day]"] || "",
        },
      };
    }
    return { id: `sim_${crypto.randomBytes(6).toString("hex")}`, object: pathname };
  }
  const response = await fetch(`https://api.stripe.com/v1/${pathname}`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${STRIPE_SECRET_KEY}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: new URLSearchParams(params),
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data?.error?.message || "Stripe request failed.");
  return data;
}

async function getOrCreateStripeCustomer(email) {
  const store = readStore();
  const user = store.users?.[email] || {};
  if (user.stripeCustomerId) return user.stripeCustomerId;
  const customer = await stripeRequest("customers", {
    email,
    "metadata[app]": "little-learner-hub",
  });
  upsertUser(email, { stripeCustomerId: customer.id });
  return customer.id;
}

function verifyStripeSignature(rawBody, signatureHeader) {
  if (!isConfiguredValue(STRIPE_WEBHOOK_SECRET)) return true;
  if (!signatureHeader) return false;
  const parts = signatureHeader.split(",").reduce((acc, part) => {
    const [key, value] = part.split("=");
    if (!key || !value) return acc;
    acc[key] = acc[key] || [];
    acc[key].push(value);
    return acc;
  }, {});
  const timestamp = parts.t?.[0];
  const signatures = parts.v1 || [];
  if (!timestamp || !signatures.length) return false;
  const ageSeconds = Math.abs(Date.now() / 1000 - Number(timestamp));
  if (!Number.isFinite(ageSeconds) || ageSeconds > 300) return false;
  const signedPayload = `${timestamp}.${rawBody.toString("utf8")}`;
  const expected = crypto.createHmac("sha256", STRIPE_WEBHOOK_SECRET).update(signedPayload).digest("hex");
  return signatures.some((signature) => timingSafeEqualText(signature, expected));
}

function currentAiCycle() {
  const now = new Date();
  return `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, "0")}`;
}

function aiLimitForPlan(plan) {
  return ["Pro", "Founding", "Trial"].includes(String(plan || "").trim()) ? 250 : 10;
}

function aiLimitForUser(user = {}) {
  // Prefer live access over bare plan string so Founding/Pro with lagging labels still get 250.
  if (membershipHasProAccess(user)) return aiLimitForPlan("Pro");
  return aiLimitForPlan(user?.plan || "Free");
}

function aiUsageKey(email) {
  return `${normalizeEmail(email)}:${currentAiCycle()}`;
}

function nextAiCycleResetDate() {
  const now = new Date();
  const nextMonth = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 1));
  return nextMonth.toISOString().slice(0, 10);
}

function canUseServerAi(email, plan, user = null) {
  const store = readStore();
  const key = aiUsageKey(email);
  const used = Number(store.aiUsage?.[key] || 0);
  const record = user || store.users?.[normalizeEmail(email)] || { plan };
  const limit = user || store.users?.[normalizeEmail(email)]
    ? aiLimitForUser(record)
    : aiLimitForPlan(plan);
  return {
    used,
    limit,
    allowed: used < limit,
    key,
    resetDate: nextAiCycleResetDate(),
  };
}

async function recordServerAiUse(email, plan, output, { tool = "", responseTimeMs = null, inputTokens = null, outputTokens = null, success = true, errorMessage = null, requestId = "" } = {}) {
  const store = readStore();
  const usage = canUseServerAi(email, plan);
  store.aiUsage = store.aiUsage || {};
  store.aiUsage[usage.key] = usage.used + 1;
  store.aiOutputs = store.aiOutputs || [];
  const logId = `ai_${Date.now()}_${crypto.randomBytes(5).toString("hex")}`;
  store.aiOutputs.unshift({
    id: logId,
    email,
    plan,
    output,
    createdAt: new Date().toISOString(),
  });
  store.aiOutputs = store.aiOutputs.slice(0, 1000);
  // Structured usage log for admin monitoring
  store.aiUsageLogs = store.aiUsageLogs || [];
  store.aiUsageLogs.unshift({
    id: logId,
    requestId: String(requestId || logId),
    tool: String(tool || "unknown"),
    email,
    plan,
    responseTimeMs: Number.isFinite(responseTimeMs) ? responseTimeMs : null,
    success,
    errorMessage: errorMessage ? String(errorMessage).slice(0, 500) : null,
    inputTokens: Number.isFinite(inputTokens) ? inputTokens : null,
    outputTokens: Number.isFinite(outputTokens) ? outputTokens : null,
    createdAt: new Date().toISOString(),
  });
  store.aiUsageLogs = store.aiUsageLogs.slice(0, 5000);
  await writeStoreAsync(store);
  return { used: usage.used + 1, limit: usage.limit };
}

function buildPromptSection(title, content) {
  return `${title}\n${content.trim()}`;
}

function buildObservationSystemPrompt() {
  const sections = [
    buildPromptSection("Master Observation Prompt", `
You are the professional Observation Assistant for Little Learner Hub.
Your purpose is to help childcare providers create high-quality, professional, objective, and developmentally appropriate observations from a short teacher note.
The provider using Little Learner Hub is busy caring for children. Assume they have very little time to type, so do the hard work for them.
Never require a long explanation. A quick sentence or two should be enough for a useful observation draft.
Never mention AI. Never apologize.
Use only information the provider actually supplied. Do not invent setting details, materials, peer names, emotions, injuries, timelines, diagnoses, or skills that are not supported by the note.
If a detail is missing, keep that section brief or write "Not enough detail provided" — do not fill gaps with assumptions.
`),
    buildPromptSection("Observation Writing Intelligence Rules", `
Step 1: Read the teacher's note closely. Identify what happened, what the child was trying to accomplish, and what skills were demonstrated — only when the note supports them.
Step 2: Understand the child. Use the child's age, developmental stage, goals, prior context, classroom details, and provider notes only when they are supplied. If age is unknown, do not assume Preschool.
Step 3: Identify only the learning that is actually supported by the note and context. Never invent unsupported learning.
Step 4: Write like an experienced childcare professional. Use natural, warm, professional language. Stay objective, specific, and non-judgmental. Do not copy the teacher's note word-for-word.
Step 5: Explain why the observed experience matters only when the note supports it; otherwise keep that section minimal.
Step 6: Recommend realistic next steps tied to the note. Prefer shorter accurate drafts over longer padded ones.
Step 7: Before returning, verify the writing is developmentally appropriate, licensing-friendly, clear, concise, and free of invented facts.
`),
    buildPromptSection("Observation Output Formatting Rules", `
Return the observation in this exact order:
1. Observation Title — 3-8 words summarizing the child's learning.
2. Observation Narrative — about 60-140 words for a typical note; shorter when the note is brief. Describe only what the note supports.
3. Developmental Areas — list only areas clearly supported by the observation.
4. Skills Demonstrated — only skills clearly shown (usually 2-5).
5. Why This Learning Matters — one short paragraph, or "Not enough detail provided".
6. Suggested Next Steps — 1-3 realistic recommendations tied to the note.
7. Suggested Activity — include activity name, materials needed, simple instructions, learning objective, and approximate time — or "Not enough detail provided".
8. Family Summary — warm, positive, jargon-free summary grounded in the note.
9. Teacher Reflection — one professional reflection statement, or "Not enough detail provided".
10. Tags — relevant tags only.
Prefer "Not enough detail provided" over invented filler.
`),
    buildPromptSection("Childcare Professional Reasoning Layer", `
Provider and teacher notes are the highest-priority source. Understand exactly what happened before writing.
Use only the details provided. Never invent injuries, triggers, witness names, diagnoses, timelines, or developmental concerns that were not entered.
Only include developmental areas, skills, recommendations, and milestone links that are clearly supported by the note and context.
Avoid generic developmental template language that could apply to any child. Make each response specific to this child and this exact situation.
If the note is brief, write "Based on the note provided..." and stay tightly grounded without inventing major facts.
Determine the primary developmental domain from the note itself. Do not default to Cognitive unless the note truly supports it.
When an age group is provided, match content to that age group. When it is not provided, do not invent one.
- Infant (0-12 months): tummy time, songs, simple sensory exploration, tracking objects, reaching/grasping, babbling, bonding, responsive feeding, safe floor play, safe sleep.
- Young Toddler (12-24 months): simple movement, stacking, naming objects, cause-and-effect, parallel play, simple songs, toddler-safe sensory play, early choices.
- Older Toddler (24-36 months): pretend play, matching, sorting, simple art, running/jumping, beginning sharing, short directions, simple routines.
- Preschool (3-5 years): vocabulary building, pre-literacy, counting, science exploration, cooperative play, problem-solving, growing independence, simple writing experiences.
- School Age (5+ years): projects, discussions, writing, STEM, problem-solving, leadership, reflection, responsibility, and age-appropriate independence.
`),
    buildPromptSection("Global Writing Quality Standards", `
Use warm, professional childcare language that providers can copy and use right away.
Write like a seasoned educator — not a template or a robot. Every output should feel specific, genuine, and freshly written.
Keep outputs organized, clearly labeled, concise, and easy to read.
Use the child's name, age, goals, observations, program name, and provider notes whenever they are provided — never invent missing ones.
Recommendations must be directly tied to what was observed, not generic filler.
Generate fresh, specific content every time. Vary sentence openings, vocabulary, structure, transitions, and examples.
Avoid empty filler phrases and repetitive AI-sounding wording.
Correct spelling, grammar, punctuation, and natural sentence structure before returning the final version.
Do not return incomplete drafts, duplicated paragraphs, placeholders, contradictions, or awkward formatting.
`),
  ];
  return sections.join("\n\n---\n\n");
}

function buildOpenAiUserPrompt(prompt, age, grounded = {}) {
  const isShortNote = !prompt || prompt.trim().length < AI_SHORT_NOTE_THRESHOLD;
  const childName = String(grounded.childName || "").trim();
  const date = String(grounded.date || "").trim();
  const classroom = String(grounded.classroom || "").trim();
  const programName = String(grounded.programName || "").trim();
  const providerNotes = String(grounded.providerNotes || "").trim();
  return [
    prompt || "Create a helpful childcare document.",
    "GROUNDED FACTS (authoritative — never invent or replace these):",
    childName ? `- Child name (use exactly): ${childName}` : "- Child name: not provided (use neutral wording like “your child” — do not invent a name).",
    age ? `- Age group: ${age}` : "",
    date ? `- Date (use exactly): ${date}` : "- Date: use today’s date only if a date is required and none was provided.",
    classroom ? `- Classroom: ${classroom}` : "",
    programName ? `- Program name: ${programName}` : "",
    providerNotes ? `- Provider note (highest priority source): ${providerNotes}` : "",
    "- Never refuse to draft a parent message, daily report, observation, incident report, behavior note, activity, lesson, or form when a note or request is provided.",
    "- Do not ask the provider to supply details that were already included above. Draft the best usable document from what was given; mark only truly missing critical fields as “Not provided.”",
    isShortNote ? "Note: The provider's note is brief. Stay tightly grounded in the exact details provided, use only minimal context to keep the response practical, and avoid generic developmental filler." : "",
  ].filter(Boolean).join("\n\n");
}

function buildDebugPromptSnapshot(systemPrompt, userPrompt) {
  return [
    "System Prompt:",
    systemPrompt,
    "",
    "---",
    "",
    "User Prompt:",
    userPrompt,
  ].join("\n");
}

