async function handleScheduleWeekAssign(request, response, weekStartParam) {
  let identity;
  try {
    identity = await resolveScheduleIdentity(request);
  } catch (error) {
    jsonResponse(response, 401, { error: error.message || "Please log in before using the schedule." });
    return;
  }
  try {
    const body = await readJson(request);
    const weekStart = scheduleLib.isoDateOnly(weekStartParam || body.weekStartDate);
    if (!weekStart) {
      jsonResponse(response, 400, { error: "weekStartDate is required (YYYY-MM-DD Monday)." });
      return;
    }
    const store = readStore();
    const current = readScheduleRecord(store, identity);
    const classroomId = String(body.classroomId || current.classrooms[0]?.id || "classroom-main").trim();
    const item = scheduleLib.normalizeScheduleItem({
      ...body,
      type: "lesson_plan",
      weekStartDate: weekStart,
      startDate: weekStart,
      endDate: scheduleLib.weekEndFromStart(weekStart),
      classroomId,
      assignedBy: identity.email,
    });
    const { doc, item: savedItem } = scheduleLib.upsertScheduleItem(current, item);
    const saved = writeScheduleRecord(store, identity, doc);
    await respondAfterPersist(store, response, 200, {
      ok: true,
      item: savedItem,
      updatedAt: saved.updatedAt,
      classrooms: saved.classrooms,
    }, "Could not assign lesson plan to week.");
  } catch (error) {
    jsonResponse(response, 400, { error: error.message || "Could not assign lesson plan to week." });
  }
}

async function handleScheduleMigrate(request, response) {
  let identity;
  try {
    identity = await resolveScheduleIdentity(request);
  } catch (error) {
    jsonResponse(response, 401, { error: error.message || "Please log in before using the schedule." });
    return;
  }
  try {
    const body = await readJson(request);
    const store = readStore();
    const current = readScheduleRecord(store, identity);
    const migrated = scheduleLib.migrateCurriculumAssignmentsToSchedule({
      curriculumAssignments: body.curriculumAssignments || [],
      weeklyPlanner: body.weeklyPlanner || null,
      classroomLabel: body.classroomLabel || "",
      classrooms: body.classrooms || current.classrooms,
    });
    // Prefer existing cloud items; fill gaps from migration.
    const byId = new Map();
    current.items.forEach((item) => byId.set(item.id, item));
    migrated.items.forEach((item) => {
      if (!byId.has(item.id)) byId.set(item.id, item);
    });
    // Also avoid duplicate lesson_plan weeks from migration when cloud already has that week.
    const cloudLessonWeeks = new Set(
      current.items
        .filter((item) => item.type === "lesson_plan")
        .map((item) => `${item.classroomId}:${item.weekStartDate}`),
    );
    const mergedItems = [];
    byId.forEach((item) => {
      if (item.type === "lesson_plan") {
        const key = `${item.classroomId}:${item.weekStartDate}`;
        const fromCloud = current.items.find((entry) => entry.id === item.id);
        if (!fromCloud && cloudLessonWeeks.has(key)) return;
      }
      mergedItems.push(item);
    });
    const saved = writeScheduleRecord(store, identity, {
      classrooms: migrated.classrooms.length ? migrated.classrooms : current.classrooms,
      items: mergedItems,
      updatedAt: new Date().toISOString(),
    });
    await respondAfterPersist(store, response, 200, {
      ok: true,
      migratedCount: migrated.items.length,
      itemCount: saved.items.length,
      classrooms: saved.classrooms,
      items: saved.items,
      updatedAt: saved.updatedAt,
    }, "Could not migrate schedule data.");
  } catch (error) {
    jsonResponse(response, 400, { error: error.message || "Could not migrate schedule data." });
  }
}

const childDataKeys = [
  "Profiles",
  "Observations",
  "SupportPlans",
  "Goals",
  "Differentiations",
  "Attendance",
  "Meals",
  "MealPresets",
  "Reports",
  "Communications",
  "Naps",
  "Diapers",
  "ActivityLogs",
  "Photos",
  "Documents",
];

function sanitizeChildDataPayload(data = {}) {
  return childDataKeys.reduce((payload, key) => {
    const items = Array.isArray(data[key]) ? data[key] : [];
    payload[key] = items.slice(0, 1000).map((item) => (
      item && typeof item === "object"
        ? JSON.parse(JSON.stringify(item))
        : {}
    ));
    return payload;
  }, {});
}

async function resolveChildDataIdentity(request) {
  // Prefer Firebase in production; allow the same test/email bridges as schedule.
  if (firebaseConfigStatus().ready) {
    try {
      return { ...(await verifyFirebaseUser(request)), source: "firebase" };
    } catch (error) {
      const authHeader = String(request.headers.authorization || "");
      if (authHeader.startsWith("Bearer ") && !authHeader.startsWith("Bearer test:")) {
        throw error;
      }
    }
  }
  return resolveScheduleIdentity(request);
}

const childDataMutations = require("./child-data-mutations");

async function handleChildData(request, response) {
  let identity;
  try {
    identity = await resolveChildDataIdentity(request);
  } catch (error) {
    jsonResponse(response, 401, { error: error.message || "Please log in before saving child data." });
    return;
  }
  const store = readStore();
  const context = programOwnership.resolveProgramContext(store, identity);
  if (!context.ok) {
    jsonResponse(response, 403, { error: context.error || "Could not resolve shared program." });
    return;
  }
  if (request.method === "GET") {
    const saved = programOwnership.readProgramChildData(store, context);
    jsonResponse(response, 200, {
      email: identity.email,
      uid: identity.uid,
      programId: context.programId,
      ownerEmail: context.ownerEmail,
      role: context.role || "",
      data: saved.data || null,
      updatedAt: saved.updatedAt || "",
      updatedByUid: saved.updatedByUid || "",
      updatedByEmail: saved.updatedByEmail || "",
      source: saved.source || "",
    });
    return;
  }
  try {
    const body = await readJson(request);
    const mutations = Array.isArray(body.mutations) ? body.mutations : [];
    // Preferred path: idempotent per-record mutations (Daily Logs / multi-device safe).
    if (mutations.length) {
      const applied = childDataMutations.applyMutations(store, context, mutations);
      if (applied.error && !applied.results) {
        jsonResponse(response, 400, { error: applied.error || "Could not apply child-data mutations." });
        return;
      }
      // Persist successful appends/updates even when sibling mutations conflict (409).
      const idempotencyMap = store.programData[context.programId]?.childIdempotency || {};
      programOwnership.writeProgramChildData(store, context, applied.data, { mirrorLegacy: true });
      store.programData[context.programId].childIdempotency = idempotencyMap;
      const status = applied.conflicts > 0 ? 409 : (applied.failed > 0 && applied.applied === 0 ? 403 : 200);
      await respondAfterPersist(store, response, status, {
        ok: Boolean(applied.ok),
        mode: "mutations",
        conflict: Boolean(applied.conflict),
        updatedAt: applied.updatedAt,
        programId: applied.programId,
        ownerEmail: context.ownerEmail,
        applied: applied.applied,
        duplicates: applied.duplicates,
        failed: applied.failed,
        conflicts: applied.conflicts || 0,
        results: applied.results,
        error: applied.conflicts > 0
          ? "One or more records were updated by someone else. Successful entries were kept; resolve conflicts to continue."
          : (applied.failed > 0 && applied.applied === 0 ? "Could not save — permission denied." : undefined),
      }, "Could not save child data.");
      return;
    }
    // Legacy full-snapshot replace (owner/director only) — staff must use mutations.
    const role = String(context.role || "").toLowerCase();
    if (role === "teacher" || role === "assistant") {
      jsonResponse(response, 400, {
        error: "Staff accounts must save Daily Logs through idempotent mutations.",
        code: "child_data_mutations_required",
      });
      return;
    }
    const data = sanitizeChildDataPayload(body.data || {});
    const result = programOwnership.writeProgramChildData(store, context, data);
    await respondAfterPersist(store, response, 200, {
      ok: true,
      mode: "snapshot",
      updatedAt: result.updatedAt,
      programId: result.programId,
      ownerEmail: context.ownerEmail,
    }, "Could not save child data.");
  } catch (error) {
    jsonResponse(response, 400, { error: error.message || "Could not save child data." });
  }
}

const FAMILY_HUB_INVITE_TTL_MS = 1000 * 60 * 60 * 24 * 14; // 14 days
const FAMILY_HUB_SESSION_TTL_MS = 1000 * 60 * 60 * 24 * 7; // 7 days
const familyHubLib = require("./family-hub-lib");
const LLH_ALLOW_EPHEMERAL_FAMILY_HUB = ["1", "true", "yes", "on"].includes(
  String(process.env.LLH_ALLOW_EPHEMERAL_FAMILY_HUB || "").trim().toLowerCase(),
);

function requireHomeDaycareHubTesting(response) {
  if (isHomeDaycareHubTestingEnabled()) return true;
  jsonResponse(response, 404, { error: "Family Hub is only available on the testing site." });
  return false;
}

function getFamilyHubStorageStatus() {
  return familyHubLib.familyHubStorageStatus({
    databaseProvider: DATABASE_PROVIDER,
    databaseReady,
    usePostgres: usePostgresStore(),
    storePath,
    allowEphemeral: LLH_ALLOW_EPHEMERAL_FAMILY_HUB,
    lastError: lastPostgresError || "",
  });
}

async function persistFamilyHubStore(store) {
  const status = getFamilyHubStorageStatus();
  if (!status.durable) {
    const error = new Error(
      status.reason
      || "Family Hub storage is not durable on this testing service. Connect Postgres or set a non-/tmp LLH_STORE_PATH on a persistent disk.",
    );
    error.code = "family_hub_storage_not_durable";
    error.storage = status;
    throw error;
  }
  if (usePostgresStore()) {
    await writeStoreAsync(store);
    return { ...status, persisted: true };
  }
  writeStore(store);
  return { ...status, persisted: true };
}

function readOwnerChildDataForFamilyHub(store, ownerEmail) {
  const email = normalizeEmail(ownerEmail);
  if (!email) return null;
  const user = store.users?.[email] || {};
  const identity = {
    email,
    uid: user.firebaseUid || user.uid || "",
  };
  try {
    const context = programOwnership.resolveProgramContext(store, identity);
    if (!context?.ok) return null;
    const saved = programOwnership.readProgramChildData(store, context);
    return saved?.data || null;
  } catch (_error) {
    return null;
  }
}

const aiGuideHandlers = createAiGuideHandlers({
  readStore: () => ensureAiGuideCollections(readStore()),
  writeStoreAsync,
  jsonResponse,
  readJson,
  normalizeEmail,
  generateOpenAiContent,
  resolveIdentity: resolveScheduleIdentity,
  requireAdmin: async (request, response) => {
    const token = extractAdminToken(request);
    if (!validAdminToken(token)) {
      jsonResponse(response, 401, { error: "Admin access is required." });
      return false;
    }
    return true;
  },
});

function ensureFamilyHubCollections(store) {
  store.familyHouseholds = store.familyHouseholds && typeof store.familyHouseholds === "object" ? store.familyHouseholds : {};
  store.familyMagicLinks = store.familyMagicLinks && typeof store.familyMagicLinks === "object" ? store.familyMagicLinks : {};
  store.familySessions = store.familySessions && typeof store.familySessions === "object" ? store.familySessions : {};
  store.familyHubMessages = Array.isArray(store.familyHubMessages) ? store.familyHubMessages : [];
  store.familyHubNotifications = Array.isArray(store.familyHubNotifications) ? store.familyHubNotifications : [];
  return store;
}

function familyHubMessagesForHousehold(store, householdId) {
  const id = String(householdId || "");
  return (store.familyHubMessages || [])
    .filter((msg) => msg && String(msg.householdId) === id)
    .sort((a, b) => String(a.createdAt || "").localeCompare(String(b.createdAt || "")));
}

function familyHubNotificationsForHousehold(store, householdId, { audience = "parent" } = {}) {
  const id = String(householdId || "");
  return (store.familyHubNotifications || [])
    .filter((item) => {
      if (!item || String(item.householdId) !== id) return false;
      const itemAudience = String(item.audience || "parent").toLowerCase();
      if (audience === "parent") return itemAudience !== "provider";
      if (audience === "provider") return itemAudience === "provider" || itemAudience === "both";
      return true;
    })
    .sort((a, b) => String(b.createdAt || "").localeCompare(String(a.createdAt || "")));
}

function touchFamilySession(store, token, session) {
  if (!token || !session) return session;
  const now = new Date();
  session.lastAccessAt = now.toISOString();
  session.expiresAt = new Date(now.getTime() + FAMILY_HUB_SESSION_TTL_MS).toISOString();
  store.familySessions[token] = session;
  return session;
}

function readOwnerScheduleForFamilyHub(store, ownerEmail) {
  const email = normalizeEmail(ownerEmail);
  if (!email) return null;
  const user = store.users?.[email] || {};
  try {
    const context = programOwnership.resolveProgramContext(store, {
      email,
      uid: user.firebaseUid || user.uid || "",
    });
    if (!context?.ok) return null;
    return programOwnership.readProgramSchedule(store, context, scheduleLib);
  } catch (_error) {
    return null;
  }
}

function buildFamilyHubParentPayload(store, household, { childId = "", date = "" } = {}) {
  const ownerChildData = readOwnerChildDataForFamilyHub(store, household.ownerEmail);
  const snapshotChildren = Array.isArray(household.children) ? household.children : [];
  const children = familyHubLib.overlayLiveChildren(snapshotChildren, ownerChildData);
  const childIds = children.map((child) => child.id).filter(Boolean);
  const documents = familyHubLib.liveDocumentsForChildren(ownerChildData, childIds, household.documents || []);
  const shared = familyHubLib.buildSharedFamilyFeed(ownerChildData, childIds);
  const threadMessages = familyHubMessagesForHousehold(store, household.id);
  const bridgedMessages = familyHubLib.sharedCommunicationsAsMessages(ownerChildData, childIds, household.id);
  const messages = familyHubLib.mergeFamilyHubMessages(threadMessages, bridgedMessages);
  const notifications = familyHubNotificationsForHousehold(store, household.id, { audience: "parent" });
  const scheduleDoc = readOwnerScheduleForFamilyHub(store, household.ownerEmail);
  const events = familyHubLib.buildFamilyHubCalendar(scheduleDoc, { fromDate: familyHubLib.todayIso(), days: 60 });
  // Prefer live Profiles name for Today hero even when household snapshot is stale.
  const today = familyHubLib.buildFamilyHubToday({
    childData: ownerChildData,
    children,
    childId: childId || children[0]?.id || "",
    date: date || familyHubLib.todayIso(),
    messages,
    events,
  });
  const focusChildId = String(today.childId || children[0]?.id || "");
  const pendingForms = (Array.isArray(documents) ? documents : []).filter((doc) => (
    (!focusChildId || String(doc.childId || "") === focusChildId || !doc.childId)
    && Boolean(doc.canAcknowledge)
  ));
  today.pendingForms = pendingForms.slice(0, 8).map((doc) => ({
    id: doc.id,
    title: doc.title,
    statusLabel: doc.statusLabel || doc.status,
    dueDate: doc.dueDate || "",
    childId: doc.childId || "",
  }));
  if (pendingForms.length) today.empty = false;
  const settings = familyHubLib.defaultHouseholdSettings(household.settings || {});
  const guardianEmails = familyHubLib.normalizeGuardianEmails(household.email || "", household.guardianEmails || []);
  const guardianLabels = household.guardianLabels && typeof household.guardianLabels === "object"
    ? household.guardianLabels
    : {};
  const guardians = guardianEmails.map((email) => ({
    email,
    name: String(guardianLabels[email] || "").trim() || email.split("@")[0] || email,
  }));
  const contacts = familyHubLib.buildFamilyContacts(ownerChildData, childIds);
  const requests = (Array.isArray(household.familyRequests) ? household.familyRequests : [])
    .map(familyHubLib.publicFamilyRequest)
    .sort((a, b) => String(b.createdAt || "").localeCompare(String(a.createdAt || "")))
    .slice(0, 40);
  // Classroom week's lesson for focus child (roster-aware)
  const focusClassroomId = String(
    (Array.isArray(ownerChildData?.Profiles) ? ownerChildData.Profiles : [])
      .find((profile) => String(profile?.id || "") === focusChildId)?.classroomId || "",
  ).trim();
  const weekLesson = focusClassroomId && scheduleDoc
    ? (Array.isArray(scheduleDoc.items) ? scheduleDoc.items : []).find((item) => (
      item
      && item.type === "lesson_plan"
      && !item.archived
      && String(item.classroomId || "") === focusClassroomId
      && String(item.weekStartDate || "") <= familyHubLib.todayIso()
      && String(item.endDate || item.weekStartDate || "") >= familyHubLib.todayIso()
    ))
    : null;
  if (weekLesson) {
    today.weekLesson = {
      id: String(weekLesson.id || ""),
      title: String(weekLesson.lessonPlanTitle || weekLesson.title || "This week’s lesson").trim(),
      weekStartDate: String(weekLesson.weekStartDate || "").slice(0, 10),
      classroomId: String(weekLesson.classroomId || ""),
    };
  }
  return {
    household: {
      ...publicFamilyHousehold(household),
      children,
      childIds,
      settings,
      guardians,
    },
    children,
    documents,
    shared,
    today,
    messages: messages.map(familyHubLib.publicFamilyMessage),
    notifications: notifications.map(familyHubLib.publicFamilyNotification),
    unreadNotifications: notifications.filter((item) => !item.read).length,
    calendar: events,
    settings,
    guardians,
    contacts,
    requests,
    storage: getFamilyHubStorageStatus(),
  };
}

function publicFamilyHousehold(household = {}) {
  const guardianEmails = familyHubLib.normalizeGuardianEmails(
    household.email || "",
    household.guardianEmails || [],
  );
  const guardianLabels = household.guardianLabels && typeof household.guardianLabels === "object"
    ? household.guardianLabels
    : {};
  return {
    id: household.id || "",
    label: household.label || "Family",
    email: household.email || "",
    phone: household.phone || "",
    guardianEmails,
    guardianLabels,
    childIds: Array.isArray(household.childIds) ? household.childIds : [],
    children: Array.isArray(household.children) ? household.children : [],
    status: household.status || "invited",
    invitedAt: household.invitedAt || "",
    expiresAt: household.expiresAt || "",
    lastAccessAt: household.lastAccessAt || "",
    emailSent: Boolean(household.emailSent),
    smsSimulated: Boolean(household.smsSimulated),
    programName: household.programName || "Little Learner Hub program",
    magicUrl: household.magicUrl || "",
    loginCodeHint: household.loginCode ? "A 6-digit login code was created for this household." : "",
    demoSeed: Boolean(household.demoSeed),
    familyRequests: (Array.isArray(household.familyRequests) ? household.familyRequests : [])
      .map(familyHubLib.publicFamilyRequest)
      .slice(0, 20),
  };
}

function familyInviteIsExpired(row, nowMs = Date.now()) {
  const exp = Date.parse(row?.expiresAt || "");
  if (Number.isFinite(exp)) return exp <= nowMs;
  const created = Date.parse(row?.invitedAt || row?.createdAt || "");
  if (!Number.isFinite(created)) return false;
  return created + FAMILY_HUB_INVITE_TTL_MS <= nowMs;
}

function familySessionIsExpired(session, nowMs = Date.now()) {
  const exp = Date.parse(session?.expiresAt || "");
  return Number.isFinite(exp) ? exp <= nowMs : true;
}

function hashFamilyLoginCode(code) {
  return crypto.createHash("sha256").update(String(code || "").trim()).digest("hex");
}

function createFamilyLoginCode() {
  return String(crypto.randomInt(100000, 1000000));
}

function listFamilyHouseholdsForOwner(store, ownerEmail) {
  const key = normalizeEmail(ownerEmail);
  return Object.values(store.familyHouseholds || {})
    .filter((item) => normalizeEmail(item.ownerEmail) === key && item.status !== "revoked")
    .sort((a, b) => String(b.invitedAt || "").localeCompare(String(a.invitedAt || "")));
}

function resolveFamilySession(request) {
  const authHeader = String(request.headers.authorization || "");
  const headerToken = authHeader.startsWith("Bearer ") ? authHeader.slice(7).trim() : "";
  const token = headerToken || String(request.headers["x-llh-family-session"] || "").trim();
  if (!token || !token.startsWith("llh_family_")) return null;
  const store = ensureFamilyHubCollections(readStore());
  const session = store.familySessions[token];
  if (!session || familySessionIsExpired(session)) return null;
  const household = store.familyHouseholds[session.householdId];
  if (!household || household.status === "revoked") return null;
  return { token, session, household, store };
}

function mintFamilySession(store, household) {
  const token = `llh_family_${crypto.randomBytes(24).toString("hex")}`;
  const now = new Date();
  store.familySessions[token] = {
    token,
    householdId: household.id,
    createdAt: now.toISOString(),
    expiresAt: new Date(now.getTime() + FAMILY_HUB_SESSION_TTL_MS).toISOString(),
  };
  household.status = "active";
  household.lastAccessAt = now.toISOString();
  store.familyHouseholds[household.id] = household;
  return token;
}

