async function handleFamilyHubRequestPost(request, response) {
  if (!requireHomeDaycareHubTesting(response)) return;
  const resolved = resolveFamilySession(request);
  if (!resolved) {
    jsonResponse(response, 401, { error: "Family Hub session missing or expired." });
    return;
  }
  let body;
  try { body = await readJson(request); } catch (_error) {
    jsonResponse(response, 400, { error: "Invalid request payload." });
    return;
  }
  const type = String(body?.type || "").trim().toLowerCase();
  const allowed = new Set(["absence", "pickup_change", "contact_update"]);
  if (!allowed.has(type)) {
    jsonResponse(response, 400, { error: "Choose absence, pickup change, or contact update." });
    return;
  }
  const { household, store, token, session } = resolved;
  touchFamilySession(store, token, session);
  const childIds = new Set([
    ...(Array.isArray(household.childIds) ? household.childIds : []).map(String),
    ...(Array.isArray(household.children) ? household.children : []).map((child) => String(child?.id || "")),
  ].filter(Boolean));
  const childId = String(body?.childId || "").trim();
  if (childId && !childIds.has(childId)) {
    jsonResponse(response, 400, { error: "That child is not linked to this household." });
    return;
  }
  const childName = String(
    body?.childName
    || (Array.isArray(household.children) ? household.children : []).find((child) => String(child?.id || "") === childId)?.name
    || "",
  ).trim();
  const details = String(body?.details || body?.notes || "").trim().slice(0, 1200);
  const date = String(body?.date || "").trim().slice(0, 10);
  if ((type === "absence" || type === "pickup_change") && !date) {
    jsonResponse(response, 400, { error: "Pick a date for this request." });
    return;
  }
  if (!details && type !== "absence") {
    jsonResponse(response, 400, { error: "Add a short note so your provider knows what you need." });
    return;
  }
  const now = new Date().toISOString();
  const item = {
    id: `fh-req-${Date.now().toString(36)}-${crypto.randomBytes(2).toString("hex")}`,
    type,
    childId,
    childName,
    date,
    time: String(body?.time || "").trim().slice(0, 20),
    details: details || (type === "absence" ? "Absence request" : ""),
    status: "pending",
    createdAt: now,
    updatedAt: now,
    createdBy: String(session?.email || household.email || "parent").trim(),
  };
  const list = Array.isArray(household.familyRequests) ? [...household.familyRequests] : [];
  list.unshift(item);
  household.familyRequests = list.slice(0, 80);
  store.familyHouseholds[household.id] = household;
  const titleMap = {
    absence: "Absence request",
    pickup_change: "Pickup change request",
    contact_update: "Contact update request",
  };
  store.familyHubNotifications = Array.isArray(store.familyHubNotifications) ? store.familyHubNotifications : [];
  // Parent-facing receipt
  store.familyHubNotifications.push({
    id: `fh-ntf-${Date.now().toString(36)}-${crypto.randomBytes(2).toString("hex")}`,
    householdId: household.id,
    type: "request",
    title: `${titleMap[type]} sent`,
    body: [childName, date, item.details].filter(Boolean).join(" · ").slice(0, 160),
    createdAt: now,
    read: false,
    href: "more",
    audience: "parent",
  });
  // Provider inbox notification
  store.familyHubNotifications.push({
    id: `fh-ntf-prov-${Date.now().toString(36)}-${crypto.randomBytes(2).toString("hex")}`,
    householdId: household.id,
    type: "request",
    title: titleMap[type] || "Parent request",
    body: [childName, date, item.details].filter(Boolean).join(" · ").slice(0, 160),
    createdAt: now,
    read: false,
    href: "family-hub",
    audience: "provider",
    requestId: item.id,
    childId,
  });
  try {
    await persistFamilyHubStore(store);
  } catch (error) {
    jsonResponse(response, 503, {
      error: error.message || "Could not save your request.",
      storage: error.storage || getFamilyHubStorageStatus(),
      testingOnly: true,
    });
    return;
  }
  jsonResponse(response, 200, {
    ok: true,
    testingOnly: true,
    request: familyHubLib.publicFamilyRequest(item),
    message: "Request sent to your provider.",
  });
}

async function handleFamilyHubRequestStatusPatch(request, response, requestId) {
  if (!requireHomeDaycareHubTesting(response)) return;
  let identity;
  try {
    identity = await resolveScheduleIdentity(request);
  } catch (_error) {
    jsonResponse(response, 401, { error: "Please log in as the provider to update requests." });
    return;
  }
  const id = String(requestId || "").trim();
  if (!id) {
    jsonResponse(response, 400, { error: "Request id is required." });
    return;
  }
  let body;
  try {
    body = await readJson(request);
  } catch (_error) {
    jsonResponse(response, 400, { error: "Invalid request update payload." });
    return;
  }
  const status = String(body?.status || "").trim().toLowerCase();
  if (!["approved", "declined", "pending"].includes(status)) {
    jsonResponse(response, 400, { error: "Status must be approved, declined, or pending." });
    return;
  }
  const store = ensureFamilyHubCollections(readStore());
  const ownerEmail = normalizeEmail(identity.email);
  const households = listFamilyHouseholdsForOwner(store, ownerEmail);
  let foundHousehold = null;
  let foundRequest = null;
  for (const household of households) {
    const list = Array.isArray(household.familyRequests) ? household.familyRequests : [];
    const match = list.find((item) => String(item?.id || "") === id);
    if (match) {
      foundHousehold = household;
      foundRequest = match;
      break;
    }
  }
  if (!foundHousehold || !foundRequest) {
    jsonResponse(response, 404, { error: "Parent request not found." });
    return;
  }
  const now = new Date().toISOString();
  foundHousehold.familyRequests = (foundHousehold.familyRequests || []).map((item) => (
    String(item.id) === id
      ? { ...item, status, updatedAt: now, reviewedBy: ownerEmail, providerNote: String(body?.note || "").trim().slice(0, 400) }
      : item
  ));
  store.familyHouseholds[foundHousehold.id] = foundHousehold;
  store.familyHubNotifications = Array.isArray(store.familyHubNotifications) ? store.familyHubNotifications : [];
  store.familyHubNotifications.unshift({
    id: `fh-ntf-req-${Date.now().toString(36)}`,
    householdId: foundHousehold.id,
    type: "request_update",
    title: status === "approved" ? "Request approved" : (status === "declined" ? "Request declined" : "Request updated"),
    body: `${foundRequest.type || "Request"} for ${foundRequest.childName || "your child"} is ${status}.`,
    href: "more",
    childId: foundRequest.childId || "",
    read: false,
    createdAt: now,
    audience: "parent",
  });
  try {
    await persistFamilyHubStore(store);
  } catch (error) {
    jsonResponse(response, 503, {
      error: error.message || "Could not update request.",
      storage: error.storage || getFamilyHubStorageStatus(),
      testingOnly: true,
    });
    return;
  }
  const updated = foundHousehold.familyRequests.find((item) => String(item.id) === id);
  jsonResponse(response, 200, {
    ok: true,
    testingOnly: true,
    request: familyHubLib.publicFamilyRequest(updated),
  });
}

async function handleFamilyHubProviderInboxGet(request, response) {
  if (!requireHomeDaycareHubTesting(response)) return;
  let identity;
  try {
    identity = await resolveScheduleIdentity(request);
  } catch (_error) {
    jsonResponse(response, 401, { error: "Please log in as the provider." });
    return;
  }
  const store = ensureFamilyHubCollections(readStore());
  const ownerEmail = normalizeEmail(identity.email);
  const households = listFamilyHouseholdsForOwner(store, ownerEmail)
    .filter((item) => item.status !== "revoked");
  const householdIds = new Set(households.map((item) => item.id));
  const notifications = (store.familyHubNotifications || [])
    .filter((item) => item && householdIds.has(String(item.householdId || "")))
    .filter((item) => {
      const audience = String(item.audience || "parent").toLowerCase();
      return audience === "provider" || audience === "both" || item.type === "form_signed" || item.type === "request";
    })
    .sort((a, b) => String(b.createdAt || "").localeCompare(String(a.createdAt || "")))
    .slice(0, 60)
    .map(familyHubLib.publicFamilyNotification);
  const pendingRequests = households.flatMap((household) => (
    (Array.isArray(household.familyRequests) ? household.familyRequests : [])
      .filter((item) => String(item.status || "pending") === "pending")
      .map((item) => ({
        ...familyHubLib.publicFamilyRequest(item),
        householdId: household.id,
        householdLabel: household.label || household.email || "Family",
      }))
  ));
  jsonResponse(response, 200, {
    ok: true,
    testingOnly: true,
    notifications,
    pendingRequests,
    unread: notifications.filter((item) => !item.read).length,
  });
}

async function handleFamilyHubUnlinkChildPost(request, response) {
  if (!requireHomeDaycareHubTesting(response)) return;
  let identity;
  try {
    identity = await resolveScheduleIdentity(request);
  } catch (_error) {
    jsonResponse(response, 401, { error: "Please log in as the provider." });
    return;
  }
  let body;
  try {
    body = await readJson(request);
  } catch (_error) {
    jsonResponse(response, 400, { error: "Invalid unlink payload." });
    return;
  }
  const childId = String(body?.childId || "").trim();
  if (!childId) {
    jsonResponse(response, 400, { error: "childId is required." });
    return;
  }
  const store = ensureFamilyHubCollections(readStore());
  const ownerEmail = normalizeEmail(identity.email);
  const now = new Date().toISOString();
  let unlinked = 0;
  let revoked = 0;
  listFamilyHouseholdsForOwner(store, ownerEmail).forEach((household) => {
    if (household.status === "revoked") return;
    const before = Array.isArray(household.children) ? household.children : [];
    const nextChildren = before.filter((child) => String(child?.id || "") !== childId);
    if (nextChildren.length === before.length) return;
    unlinked += 1;
    household.children = nextChildren;
    household.childIds = nextChildren.map((child) => child.id);
    household.updatedAt = now;
    if (!nextChildren.length) {
      household.status = "revoked";
      household.revokedAt = now;
      household.revokedReason = String(body?.reason || "child_archived").trim() || "child_archived";
      revoked += 1;
    }
    store.familyHouseholds[household.id] = household;
    store.familyHubNotifications = Array.isArray(store.familyHubNotifications) ? store.familyHubNotifications : [];
    store.familyHubNotifications.unshift({
      id: `fh-ntf-unlink-${Date.now().toString(36)}-${unlinked}`,
      householdId: household.id,
      type: "access_update",
      title: revoked && !nextChildren.length ? "Family Hub access ended" : "Child removed from Family Hub",
      body: nextChildren.length
        ? "One child was archived and removed from this household view."
        : "Access ended because linked children were archived.",
      href: "more",
      childId,
      read: false,
      createdAt: now,
      audience: "parent",
    });
  });
  try {
    await persistFamilyHubStore(store);
  } catch (error) {
    jsonResponse(response, 503, {
      error: error.message || "Could not unlink child from Family Hub.",
      storage: error.storage || getFamilyHubStorageStatus(),
      testingOnly: true,
    });
    return;
  }
  jsonResponse(response, 200, { ok: true, testingOnly: true, unlinked, revoked });
}

async function handleFamilyHubLogout(request, response) {
  if (!requireHomeDaycareHubTesting(response)) return;
  const resolved = resolveFamilySession(request);
  if (!resolved) {
    jsonResponse(response, 200, { ok: true, cleared: false, testingOnly: true });
    return;
  }
  const { store, token } = resolved;
  delete store.familySessions[token];
  try {
    await persistFamilyHubStore(store);
  } catch (_error) {
    try { writeStore(store); } catch (__error) { /* ignore */ }
  }
  jsonResponse(response, 200, { ok: true, cleared: true, testingOnly: true });
}

async function handleFamilyHubHouseholdRevoke(request, response, householdId) {
  if (!requireHomeDaycareHubTesting(response)) return;
  let identity;
  try {
    identity = await resolveScheduleIdentity(request);
  } catch (error) {
    jsonResponse(response, 401, { error: error.message || "Please log in before managing Family Hub." });
    return;
  }
  const store = ensureFamilyHubCollections(readStore());
  const household = store.familyHouseholds[householdId];
  if (!household || normalizeEmail(household.ownerEmail) !== normalizeEmail(identity.email)) {
    jsonResponse(response, 404, { error: "Household invite not found." });
    return;
  }
  household.status = "revoked";
  household.revokedAt = new Date().toISOString();
  store.familyHouseholds[householdId] = household;
  Object.values(store.familyMagicLinks).forEach((link) => {
    if (link.householdId === householdId) {
      link.status = "revoked";
      store.familyMagicLinks[link.token] = link;
    }
  });
  Object.entries(store.familySessions).forEach(([token, session]) => {
    if (session.householdId === householdId) delete store.familySessions[token];
  });
  try {
    await persistFamilyHubStore(store);
  } catch (error) {
    jsonResponse(response, 503, {
      error: error.message || "Could not revoke Family Hub invite in durable storage.",
      storage: error.storage || getFamilyHubStorageStatus(),
      testingOnly: true,
    });
    return;
  }
  jsonResponse(response, 200, { ok: true, household: publicFamilyHousehold(household) });
}

function handleFamilyHubStorageStatus(request, response) {
  if (!requireHomeDaycareHubTesting(response)) return;
  jsonResponse(response, 200, {
    ok: true,
    testingOnly: true,
    storage: getFamilyHubStorageStatus(),
    database: databaseConfigStatus(),
  });
}

async function handleFamilyHubSeedDemo(request, response) {
  if (!requireHomeDaycareHubTesting(response)) return;
  let identity;
  try {
    identity = await resolveScheduleIdentity(request);
  } catch (error) {
    jsonResponse(response, 401, { error: error.message || "Please log in before seeding Family Hub demo data." });
    return;
  }
  const storage = getFamilyHubStorageStatus();
  if (!storage.durable) {
    jsonResponse(response, 503, {
      error: storage.reason || "Cannot seed Family Hub demo until storage is durable.",
      storage,
      testingOnly: true,
    });
    return;
  }
  let body = {};
  try { body = await readJson(request); } catch (_error) { body = {}; }
  const origin = String(body.appOrigin || "").replace(/\/$/, "") || SITE_URL || "https://little-learner-hub-testing.onrender.com";
  const store = ensureFamilyHubCollections(readStore());
  const ownerEmail = normalizeEmail(identity.email);
  const seed = familyHubLib.buildFamilyHubDemoSeed({
    now: new Date(),
    origin,
    createLoginCode: createFamilyLoginCode,
    hashLoginCode: hashFamilyLoginCode,
    randomBytes: (n) => crypto.randomBytes(n),
  });
  seed.household.ownerEmail = ownerEmail;
  seed.household.programName = String(body.programName || seed.household.programName || "Little Learner Hub program");

  Object.values(store.familyHouseholds || {}).forEach((item) => {
    if (normalizeEmail(item.ownerEmail) === ownerEmail && item.demoSeed) {
      item.status = "revoked";
      item.revokedAt = new Date().toISOString();
      store.familyHouseholds[item.id] = item;
      Object.values(store.familyMagicLinks || {}).forEach((link) => {
        if (link.householdId === item.id) {
          link.status = "revoked";
          store.familyMagicLinks[link.token] = link;
        }
      });
    }
  });

  store.familyHouseholds[seed.household.id] = seed.household;
  store.familyMagicLinks[seed.magicToken] = seed.magicLink;
  store.users = store.users || {};
  store.users[ownerEmail] = {
    ...(store.users[ownerEmail] || {}),
    email: ownerEmail,
    role: store.users[ownerEmail]?.role || "owner",
    accountType: store.users[ownerEmail]?.accountType || "home_daycare",
  };
  const context = programOwnership.resolveProgramContext(store, {
    email: ownerEmail,
    uid: store.users[ownerEmail].firebaseUid || "",
  });
  if (context?.ok) {
    programOwnership.writeProgramChildData(store, context, seed.childData);
    if (Array.isArray(seed.scheduleItems) && seed.scheduleItems.length) {
      const currentSchedule = programOwnership.readProgramSchedule(store, context, scheduleLib);
      let doc = currentSchedule;
      seed.scheduleItems.forEach((item) => {
        const result = scheduleLib.upsertScheduleItem(doc, item);
        doc = result.doc;
      });
      programOwnership.writeProgramSchedule(store, context, doc, scheduleLib);
    }
  }

  // Replace prior demo messages/notifications for this owner’s demo households.
  const demoHouseholdIds = new Set(
    Object.values(store.familyHouseholds || {})
      .filter((item) => normalizeEmail(item.ownerEmail) === ownerEmail && item.demoSeed)
      .map((item) => item.id),
  );
  demoHouseholdIds.add(seed.household.id);
  store.familyHubMessages = (store.familyHubMessages || []).filter((msg) => !demoHouseholdIds.has(msg.householdId));
  store.familyHubNotifications = (store.familyHubNotifications || []).filter((item) => !demoHouseholdIds.has(item.householdId));
  (seed.messages || []).forEach((msg) => store.familyHubMessages.push(msg));
  (seed.notifications || []).forEach((item) => store.familyHubNotifications.push(item));

  try {
    await persistFamilyHubStore(store);
  } catch (error) {
    jsonResponse(response, 503, {
      error: error.message || "Could not seed Family Hub demo data.",
      storage: error.storage || storage,
      testingOnly: true,
    });
    return;
  }

  jsonResponse(response, 200, {
    ok: true,
    testingOnly: true,
    storage,
    testingHandoff: "Email may be disabled — use the magic link and login codes below for parent/guardian testing.",
    demo: {
      providerEmail: ownerEmail,
      parentEmail: seed.parentEmail,
      guardianEmail: seed.guardianEmail,
      loginCode: seed.loginCode,
      magicUrl: seed.magicUrl,
      children: seed.children,
      household: publicFamilyHousehold(seed.household),
      messageCount: (seed.messages || []).length,
      notificationCount: (seed.notifications || []).length,
      eventCount: (seed.scheduleItems || []).length,
    },
    message: "Seeded Family Hub demo household with Today feed data, guardians, messages, calendar events, forms, and shared updates.",
  });
}

const HDH_TESTER_INVITE_TTL_MS = 1000 * 60 * 60 * 24 * 14; // 14 days

function ensureHdhTesterInviteCollections(store) {
  store.hdhTesterInvites = store.hdhTesterInvites && typeof store.hdhTesterInvites === "object"
    ? store.hdhTesterInvites
    : {};
  return store;
}

function publicHdhTesterInvite(invite = {}, options = {}) {
  const origin = String(options.appOrigin || "").replace(/\/$/, "");
  const token = String(invite.token || "").trim();
  const pending = String(invite.status || "pending") === "pending" && token;
  return {
    id: invite.id || "",
    email: invite.email || "",
    childName: invite.childName || "Demo Child",
    status: invite.status || "pending",
    invitedAt: invite.invitedAt || "",
    invitedByEmail: invite.invitedByEmail || "",
    acceptedAt: invite.acceptedAt || "",
    expiresAt: invite.expiresAt || "",
    emailSent: Boolean(invite.emailSent),
    acceptUrl: pending && origin
      ? `${origin}/?testerInvite=${encodeURIComponent(token)}`
      : "",
  };
}

function hdhTesterInviteExpired(invite, nowMs = Date.now()) {
  const exp = Date.parse(invite?.expiresAt || "");
  if (Number.isFinite(exp)) return exp <= nowMs;
  const created = Date.parse(invite?.invitedAt || "");
  if (!Number.isFinite(created)) return false;
  return created + HDH_TESTER_INVITE_TTL_MS <= nowMs;
}

function listHdhTesterInvitesForOwner(store, ownerEmail) {
  const key = normalizeEmail(ownerEmail);
  return Object.values(store.hdhTesterInvites || {})
    .filter((invite) => normalizeEmail(invite.invitedByEmail) === key)
    .sort((a, b) => String(b.invitedAt || "").localeCompare(String(a.invitedAt || "")));
}

function buildIndependentTesterDemoChildData(childName = "Demo Child") {
  const now = new Date().toISOString();
  const name = String(childName || "Demo Child").trim() || "Demo Child";
  const empty = sanitizeChildDataPayload({});
  empty.Profiles = [{
    id: `tester-child-${Date.now().toString(36)}`,
    name,
    ageGroup: "Toddler",
    createdAt: now,
    notes: "Your own starter child for testing. Rename or add more kids anytime — this is not shared with other testers.",
  }];
  return empty;
}

async function handleHdhTesterInvitesList(request, response) {
  if (!requireHomeDaycareHubTesting(response)) return;
  let identity;
  try {
    identity = await resolveScheduleIdentity(request);
  } catch (error) {
    jsonResponse(response, 401, { error: error.message || "Please log in before managing tester invites." });
    return;
  }
  const store = ensureHdhTesterInviteCollections(readStore());
  let appOrigin = "";
  try {
    const raw = String(request.headers.origin || "").trim()
      || (request.headers.referer ? new URL(String(request.headers.referer)).origin : "");
    appOrigin = raw.replace(/\/$/, "");
  } catch {
    appOrigin = "";
  }
  jsonResponse(response, 200, {
    ok: true,
    invites: listHdhTesterInvitesForOwner(store, identity.email).map((invite) => publicHdhTesterInvite(invite, { appOrigin })),
    emailDeliveryReady: supportEmailConfigStatus().ready,
    testingOnly: true,
  });
}

async function handleHdhTesterInviteCreate(request, response) {
  if (!requireHomeDaycareHubTesting(response)) return;
  let identity;
  try {
    identity = await resolveScheduleIdentity(request);
  } catch (error) {
    jsonResponse(response, 401, { error: error.message || "Please log in before inviting a tester." });
    return;
  }
  let body;
  try {
    body = await readJson(request);
  } catch {
    jsonResponse(response, 400, { error: "Invalid tester invite payload." });
    return;
  }
  const email = normalizeEmail(body.email || "");
  if (!email) {
    jsonResponse(response, 400, { error: "Enter the tester's email address." });
    return;
  }
  if (email === normalizeEmail(identity.email)) {
    jsonResponse(response, 400, { error: "You cannot invite your own account." });
    return;
  }
  const store = ensureHdhTesterInviteCollections(readStore());
  const existing = listHdhTesterInvitesForOwner(store, identity.email).find(
    (invite) => invite.email === email && invite.status === "pending" && !hdhTesterInviteExpired(invite),
  );
  if (existing) {
    const origin = String(body.appOrigin || "").replace(/\/$/, "") || SITE_URL || "";
    jsonResponse(response, 409, {
      error: "That email already has a pending tester invite.",
      invite: publicHdhTesterInvite(existing, { appOrigin: origin }),
      acceptUrl: publicHdhTesterInvite(existing, { appOrigin: origin }).acceptUrl,
    });
    return;
  }
  const token = crypto.randomBytes(24).toString("hex");
  const now = new Date();
  const childName = String(body.childName || "Demo Child").trim() || "Demo Child";
  const origin = String(body.appOrigin || "").replace(/\/$/, "") || SITE_URL || "https://little-learner-hub-testing.onrender.com";
  const acceptUrl = `${origin}/?testerInvite=${encodeURIComponent(token)}`;
  const invite = {
    id: `tester-invite-${Date.now().toString(36)}`,
    token,
    email,
    childName,
    status: "pending",
    invitedAt: now.toISOString(),
    expiresAt: new Date(now.getTime() + HDH_TESTER_INVITE_TTL_MS).toISOString(),
    invitedByEmail: normalizeEmail(identity.email),
    invitedByUid: identity.uid || "",
    emailSent: false,
  };
  store.hdhTesterInvites[token] = invite;

  let emailResult = { sent: false, configured: supportEmailConfigStatus().ready };
  try {
    emailResult = await sendEmail({
      to: email,
      replyTo: identity.email,
      subject: "You're invited to test Little Learner Hub",
      text: [
        `Hi,`,
        ``,
        `${identity.email} invited you to test Little Learner Hub on the testing site.`,
        `You'll get your own Teacher account and your own starter child ("${childName}") — not shared with other testers.`,
        `You will not get Admin access. Message Leah anytime inside Messages.`,
        ``,
        `Accept your invite:`,
        acceptUrl,
        ``,
        `This invite expires on ${invite.expiresAt.slice(0, 10)}.`,
        ``,
        `— Little Learner Hub`,
      ].join("\n"),
      html: `
        <p>Hi,</p>
        <p><strong>${htmlEscape(identity.email)}</strong> invited you to test Little Learner Hub.</p>
        <p>You'll get your <strong>own Teacher account</strong> and your <strong>own starter child</strong> ("${htmlEscape(childName)}") — not shared with other testers. No Admin access. Message Leah in Messages anytime.</p>
        <p><a href="${htmlEscape(acceptUrl)}">Accept your invite</a></p>
        <p>This invite expires on ${htmlEscape(invite.expiresAt.slice(0, 10))}.</p>
        <p>— Little Learner Hub</p>
      `,
    });
  } catch (error) {
    emailResult = { sent: false, configured: supportEmailConfigStatus().ready, error: error.message };
  }
  invite.emailSent = Boolean(emailResult.sent);
  invite.emailError = emailResult.error || "";
  store.hdhTesterInvites[token] = invite;
  await respondAfterPersist(store, response, 200, {
    ok: true,
    invite: publicHdhTesterInvite(invite, { appOrigin: origin }),
    acceptUrl,
    email: emailResult,
    message: emailResult.sent
      ? "Tester invite created and email sent."
      : "Tester invite created. Share the accept link manually (email may be off on testing).",
  }, "Could not save tester invite.");
}

async function handleHdhTesterInvitePeek(request, response, url) {
  if (!requireHomeDaycareHubTesting(response)) return;
  const token = inviteTokenFromRequest(request, url);
  if (!token) {
    jsonResponse(response, 400, { error: "Missing invite token." });
    return;
  }
  const store = ensureHdhTesterInviteCollections(readStore());
  const invite = store.hdhTesterInvites[token];
  if (!invite) {
    jsonResponse(response, 404, { error: "This tester invite link is invalid or has already been removed." });
    return;
  }
  if (invite.status === "revoked") {
    jsonResponse(response, 410, { error: "This tester invite was revoked." });
    return;
  }
  if (hdhTesterInviteExpired(invite)) {
    invite.status = "expired";
    store.hdhTesterInvites[token] = invite;
    writeStore(store);
    jsonResponse(response, 410, { error: "This tester invite has expired. Ask for a new one." });
    return;
  }
  jsonResponse(response, 200, {
    ok: true,
    invite: {
      email: invite.email,
      childName: invite.childName || "Demo Child",
      status: invite.status,
      invitedByEmail: invite.invitedByEmail || "",
      expiresAt: invite.expiresAt || "",
    },
  });
}

async function handleHdhTesterInviteAccept(request, response) {
  if (!requireHomeDaycareHubTesting(response)) return;
  let identity;
  try {
    identity = await resolveScheduleIdentity(request);
  } catch (error) {
    jsonResponse(response, 401, { error: error.message || "Log in or create an account to accept this invite." });
    return;
  }
  let body;
  try {
    body = await readJson(request);
  } catch {
    jsonResponse(response, 400, { error: "Invalid accept payload." });
    return;
  }
  const token = String(body.token || "").trim();
  if (!token) {
    jsonResponse(response, 400, { error: "Missing invite token." });
    return;
  }
  const store = ensureHdhTesterInviteCollections(readStore());
  const invite = store.hdhTesterInvites[token];
  if (!invite) {
    jsonResponse(response, 404, { error: "This tester invite link is invalid or has already been removed." });
    return;
  }
  if (invite.status === "revoked") {
    jsonResponse(response, 410, { error: "This tester invite was revoked." });
    return;
  }
  if (hdhTesterInviteExpired(invite)) {
    invite.status = "expired";
    store.hdhTesterInvites[token] = invite;
    await respondAfterPersist(store, response, 410, { error: "This tester invite has expired. Ask for a new one." }, "Could not update invite.");
    return;
  }
  if (normalizeEmail(identity.email) !== normalizeEmail(invite.email)) {
    jsonResponse(response, 403, {
      error: `Sign in as ${invite.email} to accept this invite. You are currently signed in as ${identity.email}.`,
      requiredEmail: invite.email,
    });
    return;
  }

  const now = new Date().toISOString();
  const childName = String(body.childName || invite.childName || "Demo Child").trim() || "Demo Child";
  // Independent owner account — NOT linked to the inviter's program / children.
  const existingUser = store.users?.[identity.email] || { email: identity.email };
  store.users = store.users || {};
  store.users[identity.email] = {
    ...existingUser,
    email: identity.email,
    role: "owner",
    accountType: "home_daycare",
    linkedProgramOwnerEmail: "",
    programAccessViaOwner: false,
    hdhIndependentTester: true,
    hdhTesterInvitedByEmail: invite.invitedByEmail || "",
    testingInviteAcceptedAt: now,
    plan: "Pro",
    subscriptionStatus: "Pro Subscription Active",
    stripeSubscriptionStatus: "active",
    updatedAt: now,
  };
  const program = programOwnership.ensureProgramForOwner(store, identity.email, {
    ownerUid: identity.uid || existingUser.firebaseUid || "",
    name: `${childName}'s home daycare`,
    actorEmail: identity.email,
  });
  store.users[identity.email].programId = program.id;

  const context = programOwnership.resolveProgramContext(store, identity);
  const existingChild = programOwnership.readProgramChildData(store, context);
  const alreadyHasKids = Array.isArray(existingChild?.data?.Profiles) && existingChild.data.Profiles.length > 0;
  let demoChild = alreadyHasKids ? existingChild.data.Profiles[0] : null;
  if (!alreadyHasKids) {
    const seed = buildIndependentTesterDemoChildData(childName);
    demoChild = seed.Profiles[0];
    programOwnership.writeProgramChildData(store, context, seed);
  }

  invite.status = "accepted";
  invite.acceptedAt = now;
  invite.acceptedByUid = identity.uid || "";
  invite.childName = childName;
  store.hdhTesterInvites[token] = invite;

  await respondAfterPersist(store, response, 200, {
    ok: true,
    invite: publicHdhTesterInvite(invite),
    account: {
      email: identity.email,
      role: "owner",
      accountType: "home_daycare",
      linkedProgramOwnerEmail: "",
      programAccessViaOwner: false,
      hdhIndependentTester: true,
      hdhTesterInvitedByEmail: invite.invitedByEmail || "",
      testingInviteAcceptedAt: now,
      plan: "Pro",
      subscriptionStatus: "Pro Subscription Active",
      programId: program.id,
    },
    demoChild,
    message: alreadyHasKids
      ? "Invite accepted. Your own Teacher account is ready — keep using your existing child profiles."
      : `Invite accepted. You have your own Teacher account and a starter child named ${childName}.`,
  }, "Could not accept tester invite.");
}

async function handleHdhTesterRoleSwitchCreate(request, response) {
  if (!requireHomeDaycareHubTesting(response)) return;
  let identity;
  try {
    identity = await resolveScheduleIdentity(request);
  } catch (error) {
    jsonResponse(response, 401, { error: error.message || "Please log in before switching tester views." });
    return;
  }
  let body;
  try {
    body = await readJson(request);
  } catch {
    jsonResponse(response, 400, { error: "Invalid role-switch payload." });
    return;
  }
  const email = normalizeEmail(body.email || identity.email);
  if (email !== normalizeEmail(identity.email)) {
    jsonResponse(response, 403, { error: "You can only log role switches for your own account." });
    return;
  }
  const store = readStore();
  const user = store.users?.[email] || {};
  if (!user.multiRoleTester) {
    jsonResponse(response, 403, { error: "Multi-Role Tester is not enabled for this account." });
    return;
  }
  store.testerRoleSwitches = Array.isArray(store.testerRoleSwitches) ? store.testerRoleSwitches : [];
  const entry = {
    id: `trs-${Date.now().toString(36)}-${crypto.randomBytes(3).toString("hex")}`,
    email,
    fromRole: String(body.fromRole || "").slice(0, 80),
    toRole: String(body.toRole || "").slice(0, 80),
    source: String(body.source || "switch_view").slice(0, 80),
    at: String(body.at || new Date().toISOString()).slice(0, 40),
    context: body.context && typeof body.context === "object"
      ? {
          page: String(body.context.page || "").slice(0, 200),
          deviceClass: String(body.context.deviceClass || "").slice(0, 40),
          appVersion: String(body.context.appVersion || "").slice(0, 80),
        }
      : null,
  };
  store.testerRoleSwitches.unshift(entry);
  store.testerRoleSwitches = store.testerRoleSwitches.slice(0, 2000);
  await respondAfterPersist(store, response, 200, { ok: true, switch: entry }, "Could not save role switch.");
}

async function handleAdminTesterRoleSwitchesList(request, response, url) {
  const token = extractAdminToken(request, url) || extractAdminTokenFromBody(request, {});
  if (!validAdminToken(token)) {
    jsonResponse(response, 401, { error: "Admin access is required." });
    return;
  }
  const email = normalizeEmail(url.searchParams.get("email") || "");
  const store = peekStore();
  const all = Array.isArray(store.testerRoleSwitches) ? store.testerRoleSwitches : [];
  const switches = email ? all.filter((row) => normalizeEmail(row.email) === email) : all;
  jsonResponse(response, 200, { ok: true, switches: switches.slice(0, 200) });
}

async function handleHdhTesterInviteRevoke(request, response, inviteId) {
  if (!requireHomeDaycareHubTesting(response)) return;
  let identity;
  try {
    identity = await resolveScheduleIdentity(request);
  } catch (error) {
    jsonResponse(response, 401, { error: error.message || "Please log in before managing tester invites." });
    return;
  }
  const store = ensureHdhTesterInviteCollections(readStore());
  const match = Object.entries(store.hdhTesterInvites).find(([, invite]) => (
    invite.id === inviteId && normalizeEmail(invite.invitedByEmail) === normalizeEmail(identity.email)
  ));
  if (!match) {
    jsonResponse(response, 404, { error: "Tester invite not found." });
    return;
  }
  const [token, invite] = match;
  invite.status = "revoked";
  invite.revokedAt = new Date().toISOString();
  store.hdhTesterInvites[token] = invite;
  await respondAfterPersist(store, response, 200, {
    ok: true,
    invite: publicHdhTesterInvite(invite),
  }, "Could not revoke tester invite.");
}

const HDH_TRAINING_TYPES = Object.freeze([
  "CPR",
  "First Aid",
  "Bloodborne Pathogens",
  "Safe Sleep",
  "Child Abuse Prevention",
  "Other",
]);

function ensureHomeDaycareHubCollections(store) {
  store.staffTrainings = store.staffTrainings && typeof store.staffTrainings === "object" ? store.staffTrainings : {};
  store.formPackets = store.formPackets && typeof store.formPackets === "object" ? store.formPackets : {};
  return store;
}

function ownerTrainingKey(email) {
  return normalizeEmail(email);
}

function listStaffTrainingsForOwner(store, ownerEmail) {
  const list = Array.isArray(store.staffTrainings?.[ownerTrainingKey(ownerEmail)])
    ? store.staffTrainings[ownerTrainingKey(ownerEmail)]
    : [];
  return list.slice().sort((a, b) => String(b.completedAt || b.createdAt || "").localeCompare(String(a.completedAt || a.createdAt || "")));
}

function listFormPacketsForOwner(store, ownerEmail) {
  const list = Array.isArray(store.formPackets?.[ownerTrainingKey(ownerEmail)])
    ? store.formPackets[ownerTrainingKey(ownerEmail)]
    : [];
  return list.slice().sort((a, b) => String(b.createdAt || "").localeCompare(String(a.createdAt || "")));
}

function publicStaffTraining(item = {}) {
  return {
    id: item.id || "",
    staffEmail: item.staffEmail || "",
    staffName: item.staffName || "",
    type: item.type || "Other",
    completedAt: item.completedAt || "",
    expiresAt: item.expiresAt || "",
    notes: item.notes || "",
    createdAt: item.createdAt || "",
    expired: item.expiresAt ? Date.parse(item.expiresAt) < Date.now() : false,
  };
}

function publicFormPacket(packet = {}) {
  return {
    id: packet.id || "",
    title: packet.title || "Enrollment packet",
    childId: packet.childId || "",
    childName: packet.childName || "",
    householdId: packet.householdId || "",
    householdLabel: packet.householdLabel || "",
    status: packet.status || "open",
    createdAt: packet.createdAt || "",
    updatedAt: packet.updatedAt || "",
    items: Array.isArray(packet.items) ? packet.items : [],
  };
}

