/** In-flight enrichment AI keys → requestId (duplicate short-circuit). */
const enrichmentAiRecentRequests = new Map();

function enrichmentAiDedupeKey(planId, activityKey, scope, batchKey = "") {
  return `${planId}::${scope}::${activityKey || ""}::${batchKey || "0"}`;
}

async function handleAdminEnrichmentAiSuggest(request, response) {
  const started = Date.now();
  const body = await readJson(request);
  if (!requireTeachingKitOwnerAdminSession(request, body, response)) return;
  const store = readStore();
  const siteContent = store.siteContent && typeof store.siteContent === "object"
    ? store.siteContent
    : defaultSiteContentStore();
  const enrichFlags = normalizedFeatureFlags(siteContent.featureFlags);
  // AI assist for Enrichment Editor OR Binder Authoring — Enrichment Editor flag stays independent.
  if (!teachingKit.isTeachingKitAiAssistEnabled(enrichFlags)) {
    jsonResponse(response, 404, {
      error: "Teaching Kit AI assist is disabled.",
      code: "enrichment_editor_disabled",
    });
    return;
  }

  const planId = normalizedShortText(body.planId, 160);
  const activityKey = normalizedShortText(body.activityKey, 160);
  const scopeRaw = normalizedShortText(body.scope, 20).toLowerCase();
  const scope = scopeRaw === "week" || scopeRaw === "lesson" ? scopeRaw : "activity";
  const simulate = normalizedShortText(body.simulate, 40).toLowerCase();
  const activityOffset = Math.max(0, Number(body.activityOffset) || 0);
  const activityLimitRaw = Number(body.activityLimit);
  const activityLimit = Number.isFinite(activityLimitRaw) && activityLimitRaw > 0
    ? Math.min(Math.floor(activityLimitRaw), 20)
    : (enrichmentAi.LESSON_TEACHER_ACTIVITY_BATCH_SIZE || 5);
  const includeWeek = body.includeWeek !== false && activityOffset === 0;
  const requestId = enrichmentAi.createEnrichmentAiRequestId();

  if (!planId) {
    jsonResponse(response, 400, { error: "planId is required.", code: "invalid_enrichment_ai_target" });
    return;
  }
  if (scope === "activity" && !activityKey) {
    jsonResponse(response, 400, {
      error: "activityKey is required for activity-scoped suggestions.",
      code: "invalid_enrichment_ai_target",
    });
    return;
  }

  const curriculum = readSiteCurriculum(store);
  const plan = (curriculum.lessonPlans || []).find((item) => item.id === planId);
  if (!plan) {
    jsonResponse(response, 404, { error: "Lesson plan not found.", code: "lesson_not_found" });
    return;
  }

  // AI must never publish, upload images, or modify other lessons — suggest-only.
  const enrichmentApi = loadEnrichmentHelpers();
  const storeActs = (curriculum.activities || []).filter((item) => item.lessonPlanId === planId);
  const flat = enrichmentApi?.flattenLessonActivities
    ? enrichmentApi.flattenLessonActivities(plan, storeActs)
    : [];
  const activity = flat.find((item) => item.id === activityKey || item.itemId === activityKey) || null;
  if (scope === "activity" && !activity) {
    jsonResponse(response, 404, { error: "Activity not found on this lesson.", code: "activity_not_found" });
    return;
  }

  const draft = plan.enrichmentDraft && typeof plan.enrichmentDraft === "object" ? plan.enrichmentDraft : {};
  const activityDraft = activityKey && draft.activities && typeof draft.activities === "object"
    ? (draft.activities[activityKey] || {})
    : {};
  const weekDraft = draft.week && typeof draft.week === "object" ? draft.week : {};
  let lessonTeacherApi = null;
  try {
    lessonTeacherApi = require("../scripts/teaching-kit-ai-lesson-teacher.js");
  } catch (_error) {
    lessonTeacherApi = null;
  }
  const analysis = lessonTeacherApi?.analyzeLessonCompleteness
    ? lessonTeacherApi.analyzeLessonCompleteness(plan, flat, draft)
    : null;
  const ctx = {
    plan,
    activity: activity || flat[0] || null,
    activities: flat,
    scope,
    activityKey,
    activityDraft,
    weekDraft,
    draftActivities: draft.activities && typeof draft.activities === "object" ? draft.activities : {},
    activityOffset,
    activityLimit,
    includeWeek,
    existing: scope === "week" || scope === "lesson"
      ? {
        week: weekDraft,
        familyConnection: plan.familyConnection || "",
        analysisGaps: analysis?.gapSectionIds || [],
      }
      : {
        teacherTips: activityDraft.teacherTips || activity?.teacherTips || [],
        observationPrompts: activityDraft.observationPrompts || [],
        vocabulary: activityDraft.vocabulary || activity?.vocabulary || [],
        substitutions: activityDraft.substitutions || [],
        settingTags: activityDraft.settingTags || [],
      },
  };

  const batchKey = scope === "lesson" ? `off-${activityOffset}-lim-${activityLimit}` : "";
  const dedupeKey = enrichmentAiDedupeKey(planId, activityKey, scope, batchKey);
  const recent = enrichmentAiRecentRequests.get(dedupeKey);
  if (recent && (Date.now() - recent.at) < 2500 && !simulate) {
    enrichmentAi.logEnrichmentAiEvent({
      event: "enrichment_ai_suggest",
      status: "duplicate",
      requestId,
      planId,
      activityKey,
      scope,
      code: "duplicate_request",
      durationMs: Date.now() - started,
    });
    jsonResponse(response, 200, {
      ok: true,
      duplicate: true,
      requestId: recent.requestId,
      suggestions: recent.suggestions || [],
      batch: recent.batch || undefined,
      analysis: scope === "lesson" ? analysis : undefined,
      source: recent.source || "cache",
      message: "A matching suggestion request was already in progress. Reusing the prior result.",
      autoSaved: false,
      autoPublished: false,
      curriculumUnchanged: true,
      publishedContentPreserved: true,
    });
    return;
  }

  if (simulate === "timeout") {
    enrichmentAi.logEnrichmentAiEvent({
      event: "enrichment_ai_suggest",
      status: "timeout",
      requestId,
      planId,
      activityKey,
      scope,
      code: "enrichment_ai_timeout",
      durationMs: Date.now() - started,
    });
    jsonResponse(response, 504, {
      ok: false,
      requestId,
      code: "enrichment_ai_timeout",
      error: "AI suggestion timed out. Existing enrichment content was not changed.",
      suggestions: [],
    });
    return;
  }

  if (simulate === "malformed") {
    const parsed = enrichmentAi.parseEnrichmentAiOutput("NOT_JSON{{{", ctx);
    enrichmentAi.logEnrichmentAiEvent({
      event: "enrichment_ai_suggest",
      status: "malformed",
      requestId,
      planId,
      activityKey,
      scope,
      code: parsed.code,
      durationMs: Date.now() - started,
    });
    jsonResponse(response, 422, {
      ok: false,
      requestId,
      code: parsed.code,
      error: parsed.error,
      suggestions: [],
    });
    return;
  }

  if (simulate === "error") {
    enrichmentAi.logEnrichmentAiEvent({
      event: "enrichment_ai_suggest",
      status: "error",
      requestId,
      planId,
      activityKey,
      scope,
      code: "enrichment_ai_unavailable",
      durationMs: Date.now() - started,
    });
    jsonResponse(response, 503, {
      ok: false,
      requestId,
      code: "enrichment_ai_unavailable",
      error: "AI suggestions are temporarily unavailable. Existing content was not changed.",
      suggestions: [],
    });
    return;
  }

  const forceFixture = body.forceFixture === true
    || process.env.LLH_ENRICHMENT_AI_FIXTURE === "1"
    || process.env.NODE_ENV === "test"
    || !isConfiguredValue(OPENAI_API_KEY);

  let suggestions = [];
  let source = "fixture";
  let batch = null;
  try {
    // Lesson Teacher uses the structured lesson pack (gap-filtered, batched). Activity/week may use OpenAI.
    if (scope === "lesson") {
      const packed = enrichmentAi.getLessonTeacherFixturePack
        ? enrichmentAi.getLessonTeacherFixturePack(ctx)
        : enrichmentAi.buildLessonTeacherFixtureSuggestions(ctx);
      suggestions = Array.isArray(packed) ? packed : (packed?.suggestions || []);
      batch = Array.isArray(packed) ? null : (packed?.batch || null);
      source = "lesson_teacher_fixture";
    } else if (forceFixture || simulate === "fixture" || simulate === "ok") {
      suggestions = enrichmentAi.buildFixtureSuggestions(ctx);
      source = "fixture";
    } else {
      const systemPrompt = enrichmentAi.buildEnrichmentAiSystemPrompt();
      const userPrompt = enrichmentAi.buildEnrichmentAiUserPrompt({
        plan,
        activity,
        scope,
        existing: ctx.existing,
      });
      const raw = await Promise.race([
        callOpenAiRaw(systemPrompt, userPrompt),
        new Promise((_, reject) => {
          const err = new Error("enrichment_ai_timeout");
          err.code = "enrichment_ai_timeout";
          setTimeout(() => reject(err), enrichmentAi.ENRICHMENT_AI_TIMEOUT_MS);
        }),
      ]);
      const parsed = enrichmentAi.parseEnrichmentAiOutput(raw, ctx);
      if (!parsed.ok) {
        enrichmentAi.logEnrichmentAiEvent({
          event: "enrichment_ai_suggest",
          status: "malformed",
          requestId,
          planId,
          activityKey,
          scope,
          code: parsed.code,
          durationMs: Date.now() - started,
        });
        jsonResponse(response, 422, {
          ok: false,
          requestId,
          code: parsed.code,
          error: parsed.error,
          suggestions: [],
        });
        return;
      }
      suggestions = parsed.suggestions;
      source = "openai";
    }
    if (scope === "lesson" && analysis && lessonTeacherApi?.filterSuggestionsForGaps) {
      suggestions = lessonTeacherApi.filterSuggestionsForGaps(suggestions, analysis);
    }
  } catch (error) {
    const isTimeout = error?.code === "enrichment_ai_timeout"
      || /took too long|timeout/i.test(String(error?.message || ""));
    enrichmentAi.logEnrichmentAiEvent({
      event: "enrichment_ai_suggest",
      status: isTimeout ? "timeout" : "error",
      requestId,
      planId,
      activityKey,
      scope,
      code: isTimeout ? "enrichment_ai_timeout" : "enrichment_ai_failed",
      durationMs: Date.now() - started,
    });
    jsonResponse(response, isTimeout ? 504 : 503, {
      ok: false,
      requestId,
      code: isTimeout ? "enrichment_ai_timeout" : "enrichment_ai_failed",
      error: isTimeout
        ? "AI suggestion timed out. Existing enrichment content was not changed."
        : "AI suggestions failed. Existing enrichment content was not changed.",
      suggestions: [],
    });
    return;
  }

  enrichmentAiRecentRequests.set(dedupeKey, {
    requestId,
    at: Date.now(),
    suggestions,
    source,
    batch,
  });
  // Prune old dedupe entries
  if (enrichmentAiRecentRequests.size > 100) {
    const cutoff = Date.now() - 60_000;
    for (const [key, value] of enrichmentAiRecentRequests.entries()) {
      if (value.at < cutoff) enrichmentAiRecentRequests.delete(key);
    }
  }

  enrichmentAi.logEnrichmentAiEvent({
    event: "enrichment_ai_suggest",
    status: "ok",
    requestId,
    planId,
    activityKey,
    scope,
    suggestionCount: suggestions.length,
    fields: [...new Set(suggestions.map((s) => s.field))],
    durationMs: Date.now() - started,
    code: source,
    batchOffset: batch?.activityOffset,
    batchHasMore: batch?.hasMore,
  });

  jsonResponse(response, 200, {
    ok: true,
    requestId,
    planId,
    activityKey: activityKey || "",
    scope,
    source,
    suggestions,
    batch: scope === "lesson" ? batch : undefined,
    analysis: scope === "lesson" ? analysis : undefined,
    // Explicit guarantees for clients/tests
    autoSaved: false,
    autoPublished: false,
    curriculumUnchanged: true,
    publishedContentPreserved: true,
  });
}

async function handleAdminEnrichmentAiInsertLog(request, response) {
  const body = await readJson(request);
  if (!requireTeachingKitOwnerAdminSession(request, body, response)) return;
  const store = readStore();
  const flags = normalizedFeatureFlags(store.siteContent?.featureFlags);
  if (!teachingKit.isTeachingKitAiAssistEnabled(flags)) {
    jsonResponse(response, 404, {
      error: "Teaching Kit AI assist is disabled.",
      code: "enrichment_editor_disabled",
    });
    return;
  }
  const planId = normalizedShortText(body.planId, 160);
  const activityKey = normalizedShortText(body.activityKey, 160);
  const requestId = normalizedShortText(body.requestId, 80);
  const fields = Array.isArray(body.fields) ? body.fields.map((f) => normalizedShortText(f, 60)).filter(Boolean) : [];
  const insertedCount = Math.max(0, Math.min(50, Number(body.insertedCount) || 0));
  enrichmentAi.logEnrichmentAiEvent({
    event: "enrichment_ai_insert",
    status: insertedCount ? "inserted" : "noop",
    requestId,
    planId,
    activityKey,
    fields,
    insertedCount,
  });
  // Log only — never writes curriculum, never publishes.
  jsonResponse(response, 200, {
    ok: true,
    logged: true,
    autoSaved: false,
    autoPublished: false,
  });
}

/**
 * AI Teacher Assistant actions (draft-only suggestions + reusable library).
 * Never publishes. Reusable library / style prefs persist in siteContent.teachingKitAssistant.
 */
async function handleAdminAiTeacherAssistant(request, response) {
  const body = await readJson(request);
  if (!requireTeachingKitOwnerAdminSession(request, body, response)) return;
  const store = readStore();
  const flags = normalizedFeatureFlags(store.siteContent?.featureFlags);
  if (!teachingKit.isTeachingKitAiAssistEnabled(flags)) {
    jsonResponse(response, 404, {
      error: "Teaching Kit AI assist is disabled.",
      code: "enrichment_editor_disabled",
    });
    return;
  }

  let assistantApi = null;
  let reusableApi = null;
  try { assistantApi = require("../scripts/teaching-kit-ai-teacher-assistant.js"); } catch (_e) { assistantApi = null; }
  try { reusableApi = require("../scripts/teaching-kit-reusable-library.js"); } catch (_e) { reusableApi = null; }
  if (!assistantApi) {
    jsonResponse(response, 500, { error: "AI Teacher Assistant unavailable.", code: "assistant_unavailable" });
    return;
  }

  const action = normalizedShortText(body.action, 40).toLowerCase();
  const planId = normalizedShortText(body.planId, 160);
  const curriculum = readSiteCurriculum(store);
  const plan = planId
    ? (curriculum.lessonPlans || []).find((item) => item.id === planId)
    : null;
  const siteContent = store.siteContent && typeof store.siteContent === "object"
    ? store.siteContent
    : defaultSiteContentStore();
  let assistantState = assistantApi.normalizeAssistantState(siteContent.teachingKitAssistant);
  const stylePreferences = assistantState.stylePreferences;
  const enrichmentApi = loadEnrichmentHelpers();
  const storeActs = plan
    ? (curriculum.activities || []).filter((item) => item.lessonPlanId === plan.id)
    : [];
  const flat = plan && enrichmentApi?.flattenLessonActivities
    ? enrichmentApi.flattenLessonActivities(plan, storeActs)
    : [];
  const draft = plan?.enrichmentDraft && typeof plan.enrichmentDraft === "object"
    ? plan.enrichmentDraft
    : {};
  const activityKey = normalizedShortText(body.activityKey, 160);
  const activity = flat.find((item) => item.id === activityKey || item.itemId === activityKey) || flat[0] || null;
  const ctxBase = {
    theme: plan?.theme || plan?.title || "",
    age: plan?.age || "",
    lessonTitle: plan?.title || "",
    activityTitle: activity?.title || "",
    activityKey: activity ? (activity.id || activity.itemId || "") : "",
    stylePreferences,
    currentValue: normalizedMultilineText(body.currentValue, 4000),
    fallback: normalizedMultilineText(body.fallback, 4000),
    field: normalizedShortText(body.field, 80),
    fieldLabel: normalizedShortText(body.fieldLabel, 120),
    scope: activityKey ? "activity" : "week",
  };

  const persistAssistant = async (nextState) => {
    const now = new Date().toISOString();
    const next = assistantApi.normalizeAssistantState({
      ...nextState,
      updatedAt: now,
    });
    store.siteContent = {
      ...siteContent,
      teachingKitAssistant: next,
      updatedAt: now,
    };
    await writeStoreAsync(store);
    return next;
  };

  if (action === "connections" || action === "recommend_reusable") {
    const connections = reusableApi?.findLessonConnections
      ? reusableApi.findLessonConnections(plan || {}, curriculum, draft)
      : [];
    const recommendations = reusableApi?.recommendReusable
      ? reusableApi.recommendReusable(assistantState.reusableLibrary, {
        type: normalizedShortText(body.type, 40),
        query: normalizedShortText(body.query || plan?.theme || plan?.title, 160),
        theme: plan?.theme || "",
        age: plan?.age || "",
        limit: 10,
      })
      : [];
    // Curriculum Director intelligence (library-wide reuse hints) when flag is on.
    let curriculumIntelligence = null;
    if (teachingKit.isTeachingKitCurriculumDirectorEnabled(flags) && plan) {
      try {
        const directorApi = require("../scripts/teaching-kit-curriculum-director.js");
        const directorState = normalizedTeachingKitCurriculumDirector(siteContent.teachingKitCurriculumDirector);
        curriculumIntelligence = directorApi.intelligenceForLesson(
          plan,
          curriculum,
          directorState,
          assistantState,
        );
      } catch (_e) {
        curriculumIntelligence = null;
      }
    }
    jsonResponse(response, 200, {
      ok: true,
      action,
      connections: [
        ...connections,
        ...((curriculumIntelligence?.reuseHints || []).map((hint) => ({
          kind: hint.kind,
          message: hint.message,
          title: hint.title || hint.id || "",
          score: 0.6,
          source: "curriculum_director",
        }))),
      ],
      recommendations,
      curriculumIntelligence,
      autoSaved: false,
      autoPublished: false,
      curriculumUnchanged: true,
    });
    return;
  }

  if (action === "save_reusable") {
    if (!reusableApi?.saveReusableItem) {
      jsonResponse(response, 500, { error: "Reusable library unavailable." });
      return;
    }
    const result = reusableApi.saveReusableItem(assistantState.reusableLibrary, body.item || {});
    if (result.duplicate) {
      jsonResponse(response, 200, {
        ok: true,
        action,
        duplicate: result.duplicate,
        message: "A similar reusable item already exists — link it instead of duplicating.",
        autoSaved: false,
        autoPublished: false,
      });
      return;
    }
    assistantState = await persistAssistant({
      ...assistantState,
      reusableLibrary: result.library,
    });
    jsonResponse(response, 200, {
      ok: true,
      action,
      saved: result.saved,
      reusableLibrary: assistantState.reusableLibrary,
      autoPublished: false,
      publishedLessonsUnchanged: true,
    });
    return;
  }

  if (action === "learn_from_me") {
    const nextStyle = assistantApi.learnFromAcceptedEdit(stylePreferences, {
      field: body.field,
      before: body.before,
      after: body.after,
    });
    assistantState = await persistAssistant({
      ...assistantState,
      stylePreferences: nextStyle,
    });
    jsonResponse(response, 200, {
      ok: true,
      action,
      stylePreferences: assistantState.stylePreferences,
      message: "Style preferences updated from your accepted edit. Old lessons were not changed.",
      autoPublished: false,
    });
    return;
  }

  if (action === "quality_review") {
    if (!plan) {
      jsonResponse(response, 404, { error: "Lesson plan not found.", code: "lesson_not_found" });
      return;
    }
    const review = assistantApi.runQualityReview(plan, flat, draft);
    const connections = reusableApi?.findLessonConnections
      ? reusableApi.findLessonConnections(plan, curriculum, draft)
      : [];
    jsonResponse(response, 200, {
      ok: true,
      action,
      review,
      connections,
      autoSaved: false,
      autoPublished: false,
      blocksPublish: false,
    });
    return;
  }

  if (action === "make_better") {
    const suggestion = assistantApi.transformText(
      body.currentValue || body.text,
      normalizedShortText(body.improveAction || body.transform, 40),
      ctxBase,
    );
    suggestion.id = `better-${Date.now().toString(36)}`;
    jsonResponse(response, 200, {
      ok: true,
      action,
      suggestions: [suggestion],
      autoSaved: false,
      autoPublished: false,
    });
    return;
  }

  if (action === "teacher_chat") {
    const chat = assistantApi.buildTeacherChatReply(body.message || body.text, ctxBase);
    jsonResponse(response, 200, {
      ok: true,
      action,
      reply: chat.reply,
      suggestions: chat.suggestion ? [chat.suggestion] : [],
      autoSaved: false,
      autoPublished: false,
    });
    return;
  }

  if (action === "toolkit_builder") {
    const suggestion = assistantApi.buildToolkitItem(
      normalizedShortText(body.builderId || body.builder, 40),
      ctxBase,
    );
    // Prefer reusable library matches before brand-new toolkit copy.
    if (reusableApi?.recommendReusable) {
      const type = suggestion.category === "vocab_cards" ? "vocabulary"
        : (suggestion.category === "family_connection" ? "family_connection"
          : (suggestion.category === "teacher_tips" ? "teacher_tip"
            : (suggestion.category === "observation_prompts" ? "observation" : "toolkit")));
      const hits = reusableApi.recommendReusable(assistantState.reusableLibrary, {
        type,
        query: `${plan?.theme || ""} ${suggestion.proposedText}`,
        theme: plan?.theme || "",
        limit: 3,
      });
      if (hits[0] && hits[0].matchScore >= 0.35) {
        suggestion.reuseRecommended = true;
        suggestion.reusableItemId = hits[0].id;
        suggestion.proposedText = `REUSE: ${hits[0].title}\n${hits[0].body}`;
        suggestion.currentValue = suggestion.currentValue || "(empty)";
      }
    }
    jsonResponse(response, 200, {
      ok: true,
      action,
      suggestions: [suggestion],
      autoSaved: false,
      autoPublished: false,
    });
    return;
  }

  if (action === "printable_pack") {
    const pack = assistantApi.buildPrintablePack(ctxBase);
    jsonResponse(response, 200, {
      ok: true,
      action,
      printablePack: pack.cards,
      suggestions: [pack.suggestion],
      autoSaved: false,
      autoPublished: false,
    });
    return;
  }

  if (action === "example_image") {
    const image = assistantApi.buildExampleImageDraft(
      normalizedShortText(body.imageKind || body.kind, 40),
      ctxBase,
    );
    jsonResponse(response, 200, {
      ok: true,
      action,
      exampleImage: {
        kind: image.kind,
        brief: image.brief,
        previewDataUrl: image.previewDataUrl,
        approvalRequired: true,
        published: false,
      },
      suggestions: [image.suggestion],
      autoSaved: false,
      autoPublished: false,
      message: "Draft example image created. Approve before publish — never auto-publishes.",
    });
    return;
  }

  jsonResponse(response, 400, {
    error: "Unknown AI Teacher Assistant action.",
    code: "invalid_assistant_action",
    allowed: [
      "make_better",
      "teacher_chat",
      "toolkit_builder",
      "printable_pack",
      "example_image",
      "quality_review",
      "save_reusable",
      "recommend_reusable",
      "connections",
      "learn_from_me",
    ],
  });
}

/**
 * AI Curriculum Director — library-wide intelligence, masters, planning, business insights.
 * Gated by teachingKitCurriculumDirector (default false). Never auto-publishes.
 */
async function handleAdminCurriculumDirector(request, response) {
  const body = await readJson(request);
  if (!requireTeachingKitOwnerAdminSession(request, body, response)) return;
  const store = readStore();
  const flags = normalizedFeatureFlags(store.siteContent?.featureFlags);
  if (!teachingKit.isTeachingKitCurriculumDirectorEnabled(flags)) {
    jsonResponse(response, 404, {
      error: "AI Curriculum Director is disabled.",
      code: "curriculum_director_disabled",
    });
    return;
  }

  let directorApi = null;
  try { directorApi = require("../scripts/teaching-kit-curriculum-director.js"); } catch (_e) { directorApi = null; }
  if (!directorApi) {
    jsonResponse(response, 500, { error: "Curriculum Director unavailable.", code: "director_unavailable" });
    return;
  }

  const action = normalizedShortText(body.action, 40).toLowerCase() || "snapshot";
  const curriculum = readSiteCurriculum(store);
  const siteContent = store.siteContent && typeof store.siteContent === "object"
    ? store.siteContent
    : defaultSiteContentStore();
  let directorState = directorApi.normalizeDirectorState(siteContent.teachingKitCurriculumDirector);
  const assistantState = normalizedTeachingKitAssistant(siteContent.teachingKitAssistant);
  const usageByPlanId = buildCurriculumUsageByPlanId(store);
  const asArraySafe = (value) => (Array.isArray(value) ? value : []);
  const searchGaps = [];
  try {
    const insights = adminInsights.buildInsights(store, {
      hub: "search-analytics",
      range: "30d",
      events: store.analyticsEvents || [],
    });
    const noResults = insights?.data?.searchNoResults || insights?.data?.noResults || [];
    asArraySafe(noResults).forEach((row) => {
      searchGaps.push({
        query: row.key || row.query || row.name || String(row),
        count: row.count || row.value || 0,
      });
    });
  } catch (_e) {
    /* optional */
  }

  const persistDirector = async (nextState) => {
    const now = new Date().toISOString();
    const next = directorApi.normalizeDirectorState({ ...nextState, updatedAt: now });
    const latest = readStore();
    latest.siteContent = {
      ...(latest.siteContent || siteContent),
      teachingKitCurriculumDirector: next,
      updatedAt: now,
    };
    await writeStoreAsync(latest);
    Object.assign(store, latest);
    return next;
  };

  const applyDraftPatches = async (draftPatches) => {
    if (!Array.isArray(draftPatches) || !draftPatches.length) return 0;
    let applied = 0;
    const latest = readStore();
    const cur = readSiteCurriculum(latest);
    const nextPlans = (cur.lessonPlans || []).map((plan) => {
      const patch = draftPatches.find((p) => p.planId === plan.id);
      if (!patch) return plan;
      applied += 1;
      return {
        ...plan,
        enrichmentDraft: mergeEnrichmentDraftPatch(plan.enrichmentDraft, patch.enrichmentDraftPatch),
      };
    });
    const writeResult = writeSiteCurriculum(latest, {
      ...cur,
      lessonPlans: nextPlans,
    }, { updatedAt: new Date().toISOString() });
    if (writeResult.wipeBlocked) return 0;
    await writeStoreAsync(latest);
    Object.assign(store, latest);
    return applied;
  };

  if (action === "snapshot" || action === "coverage" || action === "recommendations") {
    const intelligence = directorApi.buildCurriculumIntelligence(curriculum, directorState, assistantState);
    const coverage = directorApi.buildCoverageDashboard(curriculum, usageByPlanId);
    const recommendations = directorApi.buildRecommendations(
      curriculum,
      directorState,
      assistantState,
      usageByPlanId,
    );
    const resourceHealth = directorApi.buildResourceHealth(directorState, curriculum);
    const businessInsights = directorApi.buildBusinessInsights(usageByPlanId, searchGaps, curriculum);
    jsonResponse(response, 200, {
      ok: true,
      action,
      intelligence,
      coverage,
      recommendations,
      resourceHealth,
      businessInsights,
      directorState,
      autoPublished: false,
      flagsDefaultSafe: true,
    });
    return;
  }

  if (action === "intelligence_for_lesson") {
    const planId = normalizedShortText(body.planId, 160);
    const plan = (curriculum.lessonPlans || []).find((p) => p.id === planId);
    if (!plan) {
      jsonResponse(response, 404, { error: "Lesson plan not found.", code: "lesson_not_found" });
      return;
    }
    const intel = directorApi.intelligenceForLesson(plan, curriculum, directorState, assistantState);
    jsonResponse(response, 200, {
      ok: true,
      action,
      ...intel,
      autoPublished: false,
    });
    return;
  }

  if (action === "planning") {
    const planning = directorApi.answerPlanningQuestion(
      body.question || body.text,
      curriculum,
      directorState,
      assistantState,
      usageByPlanId,
    );
    directorState = await persistDirector({
      ...directorState,
      planningNotes: [planning, ...asArraySafe(directorState.planningNotes)].slice(0, 40),
    });
    jsonResponse(response, 200, {
      ok: true,
      action,
      planning,
      autoPublished: false,
    });
    return;
  }

  if (action === "business_insights") {
    jsonResponse(response, 200, {
      ok: true,
      action,
      businessInsights: directorApi.buildBusinessInsights(usageByPlanId, searchGaps, curriculum),
      autoPublished: false,
    });
    return;
  }

  if (action === "save_master") {
    const result = directorApi.saveMasterResource(directorState, body.item || {});
    if (result.duplicate) {
      jsonResponse(response, 200, {
        ok: true,
        action,
        duplicate: result.duplicate,
        message: "A similar master resource already exists — link it instead of duplicating.",
        autoPublished: false,
      });
      return;
    }
    directorState = await persistDirector(result.director);
    jsonResponse(response, 200, {
      ok: true,
      action,
      saved: result.saved,
      directorState,
      publishedLessonsUnchanged: true,
      autoPublished: false,
    });
    return;
  }

  if (action === "link_master") {
    const result = directorApi.linkMasterToLessons(
      directorState,
      normalizedShortText(body.masterId, 80),
      Array.isArray(body.planIds) ? body.planIds : [],
    );
    if (!result.master) {
      jsonResponse(response, 404, { error: "Master resource not found." });
      return;
    }
    directorState = await persistDirector(result.director);
    const applied = await applyDraftPatches(result.draftPatches);
    jsonResponse(response, 200, {
      ok: true,
      action,
      master: result.master,
      linkedPlanIds: result.linkedPlanIds,
      draftReferencesUpdated: applied,
      autoPublished: false,
      message: `Linked master into ${result.linkedPlanIds.length} lesson(s); ${applied} draft reference(s) updated. Not published.`,
    });
    return;
  }

  if (action === "auto_link_master") {
    const masterId = normalizedShortText(body.masterId, 80);
    const master = directorState.masterResources.find((m) => m.id === masterId);
    if (!master) {
      jsonResponse(response, 404, { error: "Master resource not found." });
      return;
    }
    const themeKey = String(master.theme || master.title || "").toLowerCase();
    const relatedIds = (curriculum.lessonPlans || [])
      .filter((plan) => {
        const hay = `${plan.theme || ""} ${plan.title || ""}`.toLowerCase();
        if (!themeKey) return false;
        return themeKey.split(/\s+/).filter((t) => t.length > 3).some((token) => hay.includes(token))
          || hay.includes(themeKey.slice(0, 12));
      })
      .map((p) => p.id)
      .slice(0, 40);
    const result = directorApi.linkMasterToLessons(directorState, masterId, relatedIds);
    directorState = await persistDirector(result.director);
    const applied = await applyDraftPatches(result.draftPatches);
    jsonResponse(response, 200, {
      ok: true,
      action,
      master: result.master,
      linkedPlanIds: result.linkedPlanIds,
      draftReferencesUpdated: applied,
      autoPublished: false,
      message: `Auto-linked “${master.title}” to ${result.linkedPlanIds.length} related lesson draft(s). Published content unchanged.`,
    });
    return;
  }

  if (action === "propagate_master") {
    const result = directorApi.propagateMasterUpdate(
      directorState,
      normalizedShortText(body.masterId, 80),
    );
    if (!result.master) {
      jsonResponse(response, 404, { error: "Master resource not found." });
      return;
    }
    directorState = await persistDirector(result.director);
    const applied = await applyDraftPatches(result.draftPatches);
    jsonResponse(response, 200, {
      ok: true,
      action,
      master: result.master,
      draftReferencesUpdated: applied,
      autoPublished: false,
      message: result.message,
      publishedLessonsUnchanged: true,
    });
    return;
  }

  if (action === "resource_health") {
    jsonResponse(response, 200, {
      ok: true,
      action,
      resourceHealth: directorApi.buildResourceHealth(directorState, curriculum),
      autoPublished: false,
    });
    return;
  }

  jsonResponse(response, 400, {
    error: "Unknown Curriculum Director action.",
    code: "invalid_director_action",
    allowed: [
      "snapshot",
      "coverage",
      "recommendations",
      "intelligence_for_lesson",
      "planning",
      "business_insights",
      "save_master",
      "link_master",
      "auto_link_master",
      "propagate_master",
      "resource_health",
    ],
  });
}

/**
 * AI Curriculum Quality Review — specialist readiness reports + library health.
 * Gated by teachingKitQualityReview (default false). Never auto-publishes or auto-edits.
 */
async function handleAdminCurriculumQualityReview(request, response) {
  const body = await readJson(request);
  if (!requireTeachingKitOwnerAdminSession(request, body, response)) return;
  const store = readStore();
  const flags = normalizedFeatureFlags(store.siteContent?.featureFlags);
  if (!teachingKit.isTeachingKitQualityReviewEnabled(flags)) {
    jsonResponse(response, 404, {
      error: "AI Curriculum Quality Review is disabled.",
      code: "quality_review_disabled",
    });
    return;
  }

  let qualityApi = null;
  try { qualityApi = require("../scripts/teaching-kit-quality-review.js"); } catch (_e) { qualityApi = null; }
  if (!qualityApi) {
    jsonResponse(response, 500, { error: "Quality Review unavailable.", code: "quality_review_unavailable" });
    return;
  }

  const action = normalizedShortText(body.action, 40).toLowerCase() || "library_health";
  const curriculum = readSiteCurriculum(store);
  const enrichmentApi = loadEnrichmentHelpers();
  const usageByPlanId = buildCurriculumUsageByPlanId(store);
  const analyticsAvailable = Object.keys(usageByPlanId).some((id) => (usageByPlanId[id]?.views || 0) > 0);
  const searchGaps = [];
  try {
    const insights = adminInsights.buildInsights(store, {
      hub: "search-analytics",
      range: "30d",
      events: store.analyticsEvents || [],
    });
    const noResults = insights?.data?.searchNoResults || [];
    (Array.isArray(noResults) ? noResults : []).forEach((row) => {
      searchGaps.push({
        query: row.key || row.query || row.name || String(row),
        count: row.count || row.value || 0,
      });
    });
  } catch (_e) { /* optional */ }

  if (action === "library_health") {
    const libraryHealth = qualityApi.buildLibraryHealthDashboard(curriculum, usageByPlanId, {
      analyticsAvailable,
      searchGaps,
    });
    jsonResponse(response, 200, {
      ok: true,
      action,
      libraryHealth,
      autoPublished: false,
      autoChanged: false,
    });
    return;
  }

  if (action === "review_lesson" || action === "quality_report") {
    const planId = normalizedShortText(body.planId, 160);
    const plan = (curriculum.lessonPlans || []).find((p) => p.id === planId);
    if (!plan) {
      jsonResponse(response, 404, { error: "Lesson plan not found.", code: "lesson_not_found" });
      return;
    }
    const storeActs = (curriculum.activities || []).filter((item) => item.lessonPlanId === plan.id);
    const flat = enrichmentApi?.flattenLessonActivities
      ? enrichmentApi.flattenLessonActivities(plan, storeActs)
      : storeActs;
    const draft = body.enrichmentDraft && typeof body.enrichmentDraft === "object"
      ? body.enrichmentDraft
      : (plan.enrichmentDraft || {});
    const ignored = Array.isArray(body.ignoredCodes)
      ? body.ignoredCodes
      : (Array.isArray(draft?.week?.qualityReviewIgnored) ? draft.week.qualityReviewIgnored : []);
    const report = qualityApi.buildQualityReport(plan, flat, draft, { ignoredCodes: ignored });
    jsonResponse(response, 200, {
      ok: true,
      action,
      report,
      autoPublished: false,
      autoChanged: false,
    });
    return;
  }

  if (action === "decide_issue") {
    const planId = normalizedShortText(body.planId, 160);
    const plan = (curriculum.lessonPlans || []).find((p) => p.id === planId);
    if (!plan) {
      jsonResponse(response, 404, { error: "Lesson plan not found." });
      return;
    }
    const storeActs = (curriculum.activities || []).filter((item) => item.lessonPlanId === plan.id);
    const flat = enrichmentApi?.flattenLessonActivities
      ? enrichmentApi.flattenLessonActivities(plan, storeActs)
      : storeActs;
    const draft = body.enrichmentDraft && typeof body.enrichmentDraft === "object"
      ? body.enrichmentDraft
      : (plan.enrichmentDraft || {});
    const base = qualityApi.buildQualityReport(plan, flat, draft, {
      ignoredCodes: Array.isArray(body.ignoredCodes) ? body.ignoredCodes : [],
    });
    const decision = normalizedShortText(body.decision, 20).toLowerCase(); // ignore | pending | improved
    const report = qualityApi.applyIssueDecision(base, {
      findingId: body.findingId,
      code: body.code,
      decision,
    });
    jsonResponse(response, 200, {
      ok: true,
      action,
      report,
      ignoredCodes: report.ignoredCodes || [],
      // Client should persist ignored codes into draft.week.qualityReviewIgnored on save.
      draftPatchHint: {
        week: { qualityReviewIgnored: report.ignoredCodes || [] },
      },
      autoPublished: false,
      autoChanged: false,
    });
    return;
  }

  if (action === "improve_issue") {
    const planId = normalizedShortText(body.planId, 160);
    const plan = (curriculum.lessonPlans || []).find((p) => p.id === planId);
    if (!plan) {
      jsonResponse(response, 404, { error: "Lesson plan not found." });
      return;
    }
    const finding = body.finding && typeof body.finding === "object" ? body.finding : {
      code: body.code,
      section: body.section,
      sectionLabel: body.sectionLabel,
      suggestion: body.suggestion,
      message: body.message,
    };
    const suggestion = qualityApi.buildImprovementSuggestion(finding, plan, body.enrichmentDraft || plan.enrichmentDraft);
    jsonResponse(response, 200, {
      ok: true,
      action,
      suggestions: [suggestion],
      autoSaved: false,
      autoPublished: false,
      message: "Draft improvement ready for side-by-side review — not applied automatically.",
    });
    return;
  }

  jsonResponse(response, 400, {
    error: "Unknown Quality Review action.",
    code: "invalid_quality_action",
    allowed: ["library_health", "review_lesson", "quality_report", "decide_issue", "improve_issue"],
  });
}

function cloneJson(value) {
  return JSON.parse(JSON.stringify(value == null ? null : value));
}

function enrichmentPublishFingerprint(draft) {
  const safe = enrichmentMedia.sanitizeEnrichmentDraftPhotos(draft || {});
  return enrichmentMedia.sha256Buffer(Buffer.from(JSON.stringify({
    activities: safe.activities || {},
    week: safe.week || {},
  })));
}

function snapshotEnrichmentPublishedState(plan, activities) {
  const planId = normalizedShortText(plan?.id, 160);
  const linked = (activities || []).filter((item) => item.lessonPlanId === planId);
  return {
    dailyPlans: cloneJson(plan?.dailyPlans || {}),
    familyConnection: plan?.familyConnection || "",
    teachingKit: cloneJson(plan?.teachingKit || null),
    activities: linked.map((act) => ({
      id: act.id,
      itemId: act.itemId || "",
      setupImageUrl: act.setupImageUrl || "",
      exampleImageUrl: act.exampleImageUrl || "",
      setupMediaAssetId: act.setupMediaAssetId || "",
      exampleMediaAssetId: act.exampleMediaAssetId || "",
      teacherTips: Array.isArray(act.teacherTips) ? act.teacherTips : [],
      substitutions: Array.isArray(act.substitutions) ? act.substitutions : [],
      settingTags: Array.isArray(act.settingTags) ? act.settingTags : [],
      observationOpportunities: act.observationOpportunities || "",
      vocabulary: act.vocabulary || "",
    })),
  };
}

function applyMergedEnrichmentToActivities(existingActivities, mergedActivities, planId) {
  const byId = new Map();
  const byItem = new Map();
  mergedActivities.forEach((act) => {
    if (act?.id) byId.set(act.id, act);
    if (act?.itemId) byItem.set(act.itemId, act);
  });
  return (existingActivities || []).map((act) => {
    if (act.lessonPlanId !== planId) return act;
    const match = byId.get(act.id) || byItem.get(act.itemId);
    if (!match) return act;
    return normalizedCurriculumActivity({
      ...act,
      setupImageUrl: enrichmentMedia.sanitizedPublishedEnrichmentImageUrl(match.setupImageUrl || act.setupImageUrl || ""),
      exampleImageUrl: enrichmentMedia.sanitizedPublishedEnrichmentImageUrl(match.exampleImageUrl || act.exampleImageUrl || ""),
      setupMediaAssetId: enrichmentMedia.isEnrichmentMediaAssetId(match.setupMediaAssetId) ? match.setupMediaAssetId : (act.setupMediaAssetId || ""),
      exampleMediaAssetId: enrichmentMedia.isEnrichmentMediaAssetId(match.exampleMediaAssetId) ? match.exampleMediaAssetId : (act.exampleMediaAssetId || ""),
      teacherTips: Array.isArray(match.teacherTips) ? match.teacherTips : act.teacherTips,
      substitutions: Array.isArray(match.substitutions) ? match.substitutions : act.substitutions,
      settingTags: Array.isArray(match.settingTags) ? match.settingTags : act.settingTags,
      observationOpportunities: match.observationOpportunities || act.observationOpportunities || "",
      vocabulary: match.vocabulary || act.vocabulary || "",
      indoorAlternatives: match.indoorAlternatives || act.indoorAlternatives || "",
      outdoorAlternatives: match.outdoorAlternatives || act.outdoorAlternatives || "",
      adaptations: match.adaptations || act.adaptations || "",
      extensions: match.extensions || act.extensions || "",
      setup: match.setup || act.setup || "",
      steps: match.steps || act.steps || "",
      updatedAt: new Date().toISOString(),
    });
  }).filter(Boolean);
}

/**
 * Reversible publish: restore prior enrichment snapshot as the published lesson.
 * Does not auto-run; admin must call explicitly. Keeps history (adds a rollback entry).
 */
async function handlePermanentDeleteDisposableFixture(request, response) {
  const body = await readJson(request);
  if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
    jsonResponse(response, 401, { error: "Admin access is required.", code: "admin_required" });
    return;
  }
  const store = await readStore();
  if (curriculumConcurrencyConflict(store.siteContent, body.expectedUpdatedAt)) {
    curriculumConflictResponse(response, store.siteContent);
    return;
  }
  const planId = normalizedShortText(body.planId || body.lessonPlanId, 160);
  const confirmTitle = String(body.confirmTitle || "").trim();
  const confirmPhrase = String(body.confirmPhrase || "").trim();
  if (!planId) {
    jsonResponse(response, 400, { error: "planId is required.", code: "missing_plan_id" });
    return;
  }
  if (confirmPhrase !== "PERMANENTLY DELETE") {
    jsonResponse(response, 400, {
      error: "Secondary confirmation phrase must be exactly PERMANENTLY DELETE.",
      code: "confirm_phrase_required",
    });
    return;
  }
  const curriculum = store.siteContent?.curriculum || {};
  const existingPlan = (curriculum.lessonPlans || []).find((item) => item.id === planId);
  if (!existingPlan) {
    jsonResponse(response, 404, { error: "Lesson plan not found.", code: "lesson_not_found" });
    return;
  }
  if (!isDisposableQaFixturePlan(existingPlan)) {
    jsonResponse(response, 403, {
      error: "Permanent deletion is only available for records explicitly marked as disposable QA fixtures.",
      code: "not_disposable_fixture",
    });
    return;
  }
  if (String(existingPlan.status || "").toLowerCase() !== "archived") {
    jsonResponse(response, 409, {
      error: "Disposable fixtures must be archived before permanent deletion.",
      code: "fixture_not_archived",
    });
    return;
  }
  if (confirmTitle !== String(existingPlan.title || "").trim()) {
    jsonResponse(response, 400, {
      error: "Exact title confirmation does not match this fixture.",
      code: "confirm_title_mismatch",
    });
    return;
  }

  const beforePlans = (curriculum.lessonPlans || []).length;
  const beforeActs = (curriculum.activities || []).length;
  const linkedActivities = (curriculum.activities || []).filter((act) => act.lessonPlanId === planId);
  const linkedActivityIds = linkedActivities.map((act) => act.id);
  const mediaAssetIds = new Set();
  linkedActivities.forEach((act) => {
    if (enrichmentMedia.isEnrichmentMediaAssetId(act.setupMediaAssetId)) mediaAssetIds.add(act.setupMediaAssetId);
    if (enrichmentMedia.isEnrichmentMediaAssetId(act.exampleMediaAssetId)) mediaAssetIds.add(act.exampleMediaAssetId);
  });
  const draft = existingPlan.enrichmentDraft;
  if (draft) {
    enrichmentMedia.collectDraftMediaAssetIds(draft).forEach((id) => mediaAssetIds.add(id));
  }

  const adminEmail = normalizedShortText(body.adminEmail || "", 180) || "admin";
  const now = new Date().toISOString();
  const auditBefore = {
    id: `fixture_delete_${Date.now()}_${crypto.randomBytes(4).toString("hex")}`,
    action: "permanent_delete_disposable_fixture",
    lessonPlanId: planId,
    title: existingPlan.title || "",
    linkedActivityIds,
    mediaAssetIds: [...mediaAssetIds],
    historyEntries: Array.isArray(existingPlan.enrichmentPublishHistory) ? existingPlan.enrichmentPublishHistory.length : 0,
    adminEmail,
    createdAt: now,
    beforeLessonPlans: beforePlans,
    beforeActivities: beforeActs,
  };
  store.disposableFixtureDeleteAudit = Array.isArray(store.disposableFixtureDeleteAudit)
    ? store.disposableFixtureDeleteAudit
    : [];
  store.disposableFixtureDeleteAudit.unshift(auditBefore);
  store.disposableFixtureDeleteAudit = store.disposableFixtureDeleteAudit.slice(0, 200);
  appendEnrichmentEditorAudit(store, {
    action: "permanent_delete_disposable_fixture",
    lessonPlanId: planId,
    adminEmail,
    note: `Permanent delete of disposable fixture “${existingPlan.title || planId}” with ${linkedActivityIds.length} linked activities.`,
  });

  const nextPlans = (curriculum.lessonPlans || []).filter((item) => item.id !== planId);
  const nextActivities = (curriculum.activities || []).filter((act) => act.lessonPlanId !== planId);
  const nextCurriculum = normalizedCurriculumStore({
    ...curriculum,
    lessonPlans: nextPlans,
    activities: nextActivities,
    updatedAt: now,
  });
  const writeResult = writeSiteCurriculum(store, nextCurriculum, { updatedAt: now });
  if (writeResult.wipeBlocked) {
    jsonResponse(response, 409, {
      error: "Delete refused to protect curriculum integrity.",
      code: "curriculum_wipe_blocked",
    });
    return;
  }

  const cleanupLogs = [];
  for (const mediaId of mediaAssetIds) {
    try {
      cleanupLogs.push(await cleanupEnrichmentMediaAsset(store, {
        mediaAssetId: mediaId,
        lessonPlanId: planId,
        reason: "disposable_fixture_permanent_delete",
        sourceOperation: "fixture_delete",
      }));
    } catch (error) {
      cleanupLogs.push({ mediaAssetId: mediaId, error: error.message || String(error) });
    }
  }
  auditBefore.afterLessonPlans = (store.siteContent.curriculum.lessonPlans || []).length;
  auditBefore.afterActivities = (store.siteContent.curriculum.activities || []).length;
  auditBefore.cleanupLogs = cleanupLogs.slice(0, 50);
  await writeStoreAsync(store);

  jsonResponse(response, 200, {
    ok: true,
    deleted: true,
    deletedPlanId: planId,
    deletedTitle: existingPlan.title || "",
    deletedActivityIds: linkedActivityIds,
    deletedMediaAssetIds: [...mediaAssetIds],
    before: { lessonPlans: beforePlans, activities: beforeActs },
    after: {
      lessonPlans: auditBefore.afterLessonPlans,
      activities: auditBefore.afterActivities,
    },
    curriculum: store.siteContent.curriculum,
    siteContentUpdatedAt: store.siteContent.updatedAt,
  });
}

async function handleEnrichmentRollback(request, response) {
  const body = await readJson(request);
  if (!requireTeachingKitOwnerAdminSession(request, body, response)) return;
  const store = await readStore();
  const flags = normalizedFeatureFlags(store.siteContent?.featureFlags);
  if (!teachingKit.isTeachingKitEnrichmentEditorEnabled(flags)) {
    jsonResponse(response, 404, { error: "Enrichment Editor is disabled.", code: "enrichment_editor_disabled" });
    return;
  }
  if (curriculumConcurrencyConflict(store.siteContent, body.expectedUpdatedAt)) {
    curriculumConflictResponse(response, store.siteContent);
    return;
  }
  const planId = normalizedShortText(body.planId || body.lessonPlanId || body.lessonPlan?.id, 160);
  if (!planId) {
    jsonResponse(response, 400, { error: "planId is required.", code: "missing_plan_id" });
    return;
  }
  const curriculum = store.siteContent?.curriculum || {};
  const existingPlan = (curriculum.lessonPlans || []).find((item) => item.id === planId);
  if (!existingPlan) {
    jsonResponse(response, 404, { error: "Lesson plan not found.", code: "lesson_not_found" });
    return;
  }
  const history = Array.isArray(existingPlan.enrichmentPublishHistory)
    ? existingPlan.enrichmentPublishHistory
    : [];
  const versionId = normalizedShortText(body.versionId, 80);
  const entry = versionId
    ? history.find((item) => item.versionId === versionId)
    : history.find((item) => item?.snapshot && (item.kind || "publish") !== "draft") || history[0];
  if (!entry?.snapshot) {
    jsonResponse(response, 400, {
      error: "No enrichment version history is available to restore.",
      code: "enrichment_rollback_unavailable",
    });
    return;
  }
  const snap = entry.snapshot;
  const now = new Date().toISOString();
  const adminEmail = normalizedShortText(body.publishedBy || body.adminEmail || "", 180) || "admin";
  const entryKind = normalizedShortText(entry.kind, 20) || "publish";
  const isDraftRestore = entryKind === "draft" || (snap.enrichmentDraft && !snap.dailyPlans);

  if (isDraftRestore) {
    const draftSnap = snap.enrichmentDraft && typeof snap.enrichmentDraft === "object"
      ? snap.enrichmentDraft
      : null;
    if (!enrichmentDraftHasContent(draftSnap)) {
      jsonResponse(response, 400, {
        error: "That draft snapshot has no enrichment content to restore.",
        code: "enrichment_draft_restore_empty",
      });
      return;
    }
    const restoredPlan = normalizedCurriculumLessonPlan({
      ...existingPlan,
      enrichmentDraft: {
        ...draftSnap,
        updatedAt: now,
        lastEditedBy: adminEmail,
      },
      enrichmentPublishHistory: [
        {
          versionId: `eroll-${crypto.randomBytes(10).toString("hex")}`,
          kind: "rollback",
          publishedAt: now,
          publishedBy: adminEmail,
          fingerprint: `rollback-draft:${entry.versionId}`,
          lessonPlanId: planId,
          snapshot: { enrichmentDraft: cloneJson(existingPlan.enrichmentDraft || {}) },
          rollbackOf: entry.versionId,
        },
        ...history,
      ].slice(0, ENRICHMENT_HISTORY_LIMIT),
      updatedAt: existingPlan.updatedAt,
    });
    const nextCurriculum = normalizedCurriculumStore({
      ...curriculum,
      lessonPlans: (curriculum.lessonPlans || []).map((item) => (item.id === planId ? restoredPlan : item)),
      updatedAt: now,
    });
    const writeResult = writeSiteCurriculum(store, nextCurriculum, { updatedAt: now });
    if (writeResult.wipeBlocked) {
      jsonResponse(response, 409, {
        error: "Rollback refused to protect curriculum integrity.",
        code: "curriculum_wipe_blocked",
      });
      return;
    }
    appendEnrichmentEditorAudit(store, {
      action: "restore_draft",
      lessonPlanId: planId,
      versionId: entry.versionId,
      adminEmail,
      fingerprint: `rollback-draft:${entry.versionId}`,
      note: "Restored draft snapshot for this lesson only.",
    });
    await writeStoreAsync(store);
    const saved = (store.siteContent.curriculum.lessonPlans || []).find((item) => item.id === planId);
    jsonResponse(response, 200, {
      ok: true,
      rolledBack: true,
      restoredDraft: true,
      autoPublished: false,
      restoredFromVersionId: entry.versionId,
      lessonPlan: saved,
      curriculum: store.siteContent.curriculum,
      siteContentUpdatedAt: store.siteContent.updatedAt,
    });
    return;
  }

  // Publish/history snapshots restore into a NEW DRAFT only.
  // Customer-visible published content stays unchanged until an explicit Publish.
  const draftFromPublish = publishedEnrichmentSnapshotToDraft(snap, {
    adminEmail,
    now,
    versionId: entry.versionId,
  });
  if (!enrichmentDraftHasContent(draftFromPublish)) {
    jsonResponse(response, 400, {
      error: "That published snapshot has no enrichment content to restore into a draft.",
      code: "enrichment_publish_restore_empty",
    });
    return;
  }
  const priorDraftSnap = enrichmentDraftHasContent(existingPlan.enrichmentDraft)
    ? { enrichmentDraft: cloneJson(existingPlan.enrichmentDraft) }
    : snapshotEnrichmentPublishedState(existingPlan, curriculum.activities || []);
  const restoredPlan = normalizedCurriculumLessonPlan({
    ...existingPlan,
    enrichmentDraft: draftFromPublish,
    enrichmentPublishHistory: [
      {
        versionId: `eroll-${crypto.randomBytes(10).toString("hex")}`,
        kind: "rollback",
        publishedAt: now,
        publishedBy: adminEmail,
        fingerprint: `rollback-to-draft:${entry.versionId}`,
        lessonPlanId: planId,
        snapshot: priorDraftSnap,
        rollbackOf: entry.versionId,
      },
      ...history,
    ].slice(0, ENRICHMENT_HISTORY_LIMIT),
    updatedAt: existingPlan.updatedAt,
  });
  const nextCurriculum = normalizedCurriculumStore({
    ...curriculum,
    lessonPlans: (curriculum.lessonPlans || []).map((item) => (item.id === planId ? restoredPlan : item)),
    updatedAt: now,
  });
  const writeResult = writeSiteCurriculum(store, nextCurriculum, { updatedAt: now });
  if (writeResult.wipeBlocked) {
    jsonResponse(response, 409, {
      error: "Rollback refused to protect curriculum integrity.",
      code: "curriculum_wipe_blocked",
    });
    return;
  }
  appendEnrichmentEditorAudit(store, {
    action: "restore_publish_to_draft",
    lessonPlanId: planId,
    versionId: entry.versionId,
    adminEmail,
    fingerprint: `rollback-to-draft:${entry.versionId}`,
    note: "Restored published snapshot into draft for this lesson only. Customer-visible content unchanged until Publish.",
  });
  await writeStoreAsync(store);
  const saved = (store.siteContent.curriculum.lessonPlans || []).find((item) => item.id === planId);
  jsonResponse(response, 200, {
    ok: true,
    rolledBack: true,
    restoredDraft: true,
    restoredIntoDraft: true,
    customerVisibleUnchanged: true,
    autoPublished: false,
    restoredFromVersionId: entry.versionId,
    lessonPlan: saved,
    curriculum: store.siteContent.curriculum,
    siteContentUpdatedAt: store.siteContent.updatedAt,
  });
}

function publishedEnrichmentSnapshotToDraft(snap, { adminEmail = "admin", now = "", versionId = "" } = {}) {
  const activities = {};
  const pushAct = (key, fields = {}) => {
    const id = normalizedShortText(key, 160);
    if (!id) return;
    const prev = activities[id] || {};
    activities[id] = {
      teacherTips: Array.isArray(fields.teacherTips) && fields.teacherTips.length
        ? fields.teacherTips
        : (Array.isArray(prev.teacherTips) ? prev.teacherTips : []),
      setupImageUrl: fields.setupImageUrl || prev.setupImageUrl || "",
      exampleImageUrl: fields.exampleImageUrl || prev.exampleImageUrl || "",
      setupMediaAssetId: fields.setupMediaAssetId || prev.setupMediaAssetId || "",
      exampleMediaAssetId: fields.exampleMediaAssetId || prev.exampleMediaAssetId || "",
      substitutions: Array.isArray(fields.substitutions) ? fields.substitutions : (prev.substitutions || []),
      settingTags: Array.isArray(fields.settingTags) ? fields.settingTags : (prev.settingTags || []),
      observationOpportunities: fields.observationOpportunities || prev.observationOpportunities || "",
      vocabulary: fields.vocabulary || prev.vocabulary || "",
    };
  };
  (Array.isArray(snap?.activities) ? snap.activities : []).forEach((act) => {
    pushAct(act.itemId || act.id, act);
  });
  ["monday", "tuesday", "wednesday", "thursday", "friday"].forEach((day) => {
    (snap?.dailyPlans?.[day]?.items || []).forEach((item) => {
      pushAct(item.itemId || item.id || item.title, {
        teacherTips: Array.isArray(item.teacherTips) ? item.teacherTips : [],
        setupImageUrl: item.setupImageUrl || "",
        exampleImageUrl: item.exampleImageUrl || "",
      });
    });
  });
  return {
    activities,
    week: {
      familyConnection: snap?.familyConnection || "",
    },
    updatedAt: now || new Date().toISOString(),
    lastEditedBy: adminEmail,
    restoredFromPublishVersionId: normalizedShortText(versionId, 80) || "",
    previewReady: false,
  };
}


async function promoteEnrichmentAssetsToPublished(store, assetIds, lessonPlanId) {
  const dir = enrichmentMedia.localMediaDirFromStorePath(storePath);
  for (const assetId of assetIds) {
    if (!enrichmentMedia.isEnrichmentMediaAssetId(assetId)) continue;
    setEnrichmentMediaRegistryEntry(store, assetId, {
      visibility: "published",
      lessonPlanId,
      publishedAt: new Date().toISOString(),
    });
    try {
      enrichmentMedia.updateLocalEnrichmentAssetMeta(dir, assetId, {
        visibility: "published",
        publishedAt: new Date().toISOString(),
      });
    } catch (_error) {
      // Postgres path relies on registry only.
    }
  }
}

async function handlePublishEnrichment(request, response, ctx) {
  const {
    store,
    siteContent,
    existingCurriculum,
    existingPlan,
    incomingPlan,
    id,
    now,
    body,
  } = ctx;
  if (!requireTeachingKitOwnerAdminSession(request, body, response)) return;
  const enrichFlags = normalizedFeatureFlags(siteContent.featureFlags);
  if (!teachingKit.isTeachingKitEnrichmentEditorEnabled(enrichFlags)) {
    jsonResponse(response, 404, {
      error: "Teaching Kit Enrichment Editor is disabled.",
      code: "enrichment_editor_disabled",
    });
    return;
  }
  if (!existingPlan) {
    jsonResponse(response, 404, { error: "Lesson plan not found for enrichment publish." });
    return;
  }
  // Only the currently edited lesson id may be published.
  if (normalizedShortText(incomingPlan.id, 160) && normalizedShortText(incomingPlan.id, 160) !== id) {
    jsonResponse(response, 400, {
      error: "Publish payload lesson id mismatch.",
      code: "publish_lesson_mismatch",
    });
    return;
  }
  const enrichmentApi = loadEnrichmentHelpers();
  if (!enrichmentApi?.mergeDraftIntoPlan) {
    jsonResponse(response, 500, { error: "Enrichment helpers unavailable.", code: "enrichment_helpers_missing" });
    return;
  }

  const incomingDraft = incomingPlan.enrichmentDraft && typeof incomingPlan.enrichmentDraft === "object"
    ? enrichmentMedia.sanitizeEnrichmentDraftPhotos(incomingPlan.enrichmentDraft)
    : (existingPlan.enrichmentDraft && typeof existingPlan.enrichmentDraft === "object"
      ? enrichmentMedia.sanitizeEnrichmentDraftPhotos(existingPlan.enrichmentDraft)
      : null);

  // Optional Quality Review gate (flag default false). Report-only system can block
  // publish when unresolved blocking issues remain. Never auto-edits content.
  if (teachingKit.isTeachingKitQualityReviewEnabled(enrichFlags)) {
    try {
      const qualityApi = require("../scripts/teaching-kit-quality-review.js");
      const storeActs = (existingCurriculum.activities || []).filter((item) => item.lessonPlanId === id);
      const flat = enrichmentApi.flattenLessonActivities
        ? enrichmentApi.flattenLessonActivities(existingPlan, storeActs)
        : storeActs;
      const ignored = Array.isArray(incomingDraft?.week?.qualityReviewIgnored)
        ? incomingDraft.week.qualityReviewIgnored
        : [];
      const report = qualityApi.buildQualityReport(existingPlan, flat, incomingDraft, { ignoredCodes: ignored });
      if (report.blocksPublish) {
        const override = body?.ownerPublishOverride && typeof body.ownerPublishOverride === "object"
          ? body.ownerPublishOverride
          : null;
        const overrideReason = normalizedShortText(override?.reason, 500);
        const overrideOk = override?.confirmed === true && overrideReason.length >= 8;
        if (!overrideOk) {
          jsonResponse(response, 409, {
            error: "Quality Review blocked publish ("
              + (report.publishReadinessLabel || "Blocked")
              + "). Resolve issues, or provide an explicit owner override with a reason.",
            code: "quality_review_blocked",
            qualityReport: report,
            publishReadiness: report.publishReadiness || "blocked",
            autoPublished: false,
            ownerOverrideRequired: true,
          });
          return;
        }
        // Explicit owner override — logged; never silent.
        console.warn("[enrichment-publish-override]", {
          planId: id,
          reason: overrideReason,
          publishedBy: normalizedShortText(body.publishedBy || incomingDraft?.lastEditedBy || "", 180) || "admin",
          publishReadiness: report.publishReadiness,
          completionPercent: report.completionPercent,
          blockingCodes: (report.blockingIssues || []).map((b) => b.code),
          at: now,
        });
        body._ownerPublishOverrideApplied = {
          reason: overrideReason,
          at: now,
          publishReadiness: report.publishReadiness,
          completionPercent: report.completionPercent,
        };
      }
    } catch (error) {
      jsonResponse(response, 500, {
        error: "Quality Review failed before publish.",
        code: "quality_review_error",
        detail: error.message || String(error),
      });
      return;
    }
  }

  const fingerprint = enrichmentPublishFingerprint(incomingDraft || {});
  const lastVersion = Array.isArray(existingPlan.enrichmentPublishHistory)
    ? existingPlan.enrichmentPublishHistory[0]
    : null;

  const weekDraft = incomingDraft?.week && typeof incomingDraft.week === "object" ? incomingDraft.week : {};
  const weekToolkit = weekDraft.teacherToolkit && typeof weekDraft.teacherToolkit === "object"
    ? weekDraft.teacherToolkit
    : {};
  const hasWeekEnrichment = Boolean(
    String(weekDraft.familyConnection || "").trim()
    || String(weekDraft.weeklyOverview || "").trim()
    || String(weekDraft.objectives || "").trim()
    || String(weekDraft.weeklyMaterials || "").trim()
    || String(weekDraft.teacherPreparation || "").trim()
    || String(weekToolkit.teacherPreparation || "").trim()
    || String(weekToolkit.notes || "").trim()
    || (Array.isArray(weekDraft.milestones) && weekDraft.milestones.length)
    || (Array.isArray(weekDraft.printableIds) && weekDraft.printableIds.length)
    || (Array.isArray(weekDraft.printableIdeas) && weekDraft.printableIdeas.length)
    || (Array.isArray(weekDraft.vocabCards) && weekDraft.vocabCards.length)
    || (Array.isArray(weekDraft.books) && weekDraft.books.length)
    || (Array.isArray(weekDraft.songs) && weekDraft.songs.length)
    || (Array.isArray(weekToolkit.prepChecklist) && weekToolkit.prepChecklist.length)
    || (Array.isArray(weekToolkit.observationFocus) && weekToolkit.observationFocus.length),
  );
  const hasActivityEnrichment = Boolean(Object.keys(incomingDraft?.activities || {}).length);
  // Idempotent duplicate publish: no draft left / same fingerprint → no new version.
  const draftEmpty = !incomingDraft || (!hasActivityEnrichment && !hasWeekEnrichment);
  if (draftEmpty || (lastVersion && lastVersion.fingerprint === fingerprint)) {
    jsonResponse(response, 200, {
      ok: true,
      saveMode: "publish_enrichment",
      duplicate: true,
      versionId: lastVersion?.versionId || "",
      lessonPlan: existingPlan,
      curriculum: store.siteContent.curriculum,
      siteContentUpdatedAt: store.siteContent.updatedAt,
    });
    return;
  }
  if (!incomingDraft || (!hasActivityEnrichment && !hasWeekEnrichment)) {
    jsonResponse(response, 400, {
      error: "No enrichment draft to publish for this lesson.",
      code: "enrichment_draft_empty",
    });
    return;
  }

  const linkedActivities = (existingCurriculum.activities || []).filter((item) => item.lessonPlanId === id);
  // Promote photo URLs in a draft copy so merge writes public URLs (never admin draft URLs).
  const promotedDraft = {
    ...incomingDraft,
    activities: Object.fromEntries(
      Object.entries(incomingDraft.activities || {}).map(([key, act]) => [
        key,
        enrichmentMedia.promoteDraftPhotoUrlsToPublic(act),
      ]),
    ),
  };
  const merged = enrichmentApi.mergeDraftIntoPlan(existingPlan, linkedActivities, promotedDraft);
  const assetIds = [...enrichmentMedia.collectDraftMediaAssetIds(promotedDraft)];

  // Sanitize merged plan image fields — strip any leftover admin URLs.
  const mergedPlan = {
    ...merged.plan,
    dailyPlans: merged.plan.dailyPlans || {},
  };
  ["monday", "tuesday", "wednesday", "thursday", "friday"].forEach((day) => {
    const dayPlan = mergedPlan.dailyPlans[day];
    if (!dayPlan?.items) return;
    dayPlan.items = dayPlan.items.map((item) => ({
      ...item,
      setupImageUrl: enrichmentMedia.sanitizedPublishedEnrichmentImageUrl(item.setupImageUrl || ""),
      exampleImageUrl: enrichmentMedia.sanitizedPublishedEnrichmentImageUrl(item.exampleImageUrl || ""),
    }));
  });

  const priorSnapshot = snapshotEnrichmentPublishedState(existingPlan, existingCurriculum.activities || []);
  const versionId = `epub-${crypto.randomBytes(12).toString("hex")}`;
  const publishedBy = normalizedShortText(
    body.publishedBy || incomingDraft.lastEditedBy || "",
    180,
  ) || "admin";
  const history = [
    {
      versionId,
      kind: "publish",
      publishedAt: now,
      publishedBy,
      fingerprint,
      lessonPlanId: id,
      snapshot: priorSnapshot,
    },
    ...(Array.isArray(existingPlan.enrichmentPublishHistory) ? existingPlan.enrichmentPublishHistory : []),
  ].slice(0, ENRICHMENT_HISTORY_LIMIT);

  const nextActivities = applyMergedEnrichmentToActivities(
    existingCurriculum.activities || [],
    merged.activities,
    id,
  );
  const ownerOverrideMeta = body?._ownerPublishOverrideApplied || null;
  const nextPlan = normalizedCurriculumLessonPlan({
    ...existingPlan,
    ...mergedPlan,
    enrichmentDraft: null,
    enrichmentPublishHistory: history,
    teachingKit: {
      ...(mergedPlan.teachingKit || existingPlan.teachingKit || {}),
      lastEnrichmentPublishedAt: now,
      lastEnrichmentPublishedBy: publishedBy,
      lastEnrichmentPublishFingerprint: fingerprint,
      lastEnrichmentVersionId: versionId,
      ...(ownerOverrideMeta ? {
        lastPublishOverride: {
          reason: ownerOverrideMeta.reason,
          at: ownerOverrideMeta.at,
          publishedBy,
          publishReadiness: ownerOverrideMeta.publishReadiness || "blocked",
          completionPercent: ownerOverrideMeta.completionPercent,
        },
      } : {}),
    },
    updatedAt: now,
  });

  const nextCurriculum = normalizedCurriculumStore({
    ...existingCurriculum,
    lessonPlans: (existingCurriculum.lessonPlans || []).map((item) => (item.id === id ? nextPlan : item)),
    activities: nextActivities,
    updatedAt: now,
  });

  // Atomic apply: promote visibility + write curriculum in one store commit path.
  await promoteEnrichmentAssetsToPublished(store, assetIds, id);
  const writeResult = writeSiteCurriculum(store, nextCurriculum, { updatedAt: now });
  if (writeResult.wipeBlocked) {
    // Roll back registry promotions for this attempt (assets stay draft_private).
    assetIds.forEach((assetId) => {
      setEnrichmentMediaRegistryEntry(store, assetId, { visibility: "draft_private" });
      try {
        enrichmentMedia.updateLocalEnrichmentAssetMeta(
          enrichmentMedia.localMediaDirFromStorePath(storePath),
          assetId,
          { visibility: "draft_private" },
        );
      } catch (_error) {
        // ignore
      }
    });
    jsonResponse(response, 409, {
      error: "Publish refused to protect curriculum integrity. No changes were applied.",
      code: "curriculum_wipe_blocked",
    });
    return;
  }
  appendEnrichmentEditorAudit(store, {
    action: "publish",
    lessonPlanId: id,
    versionId,
    adminEmail: publishedBy,
    fingerprint,
    note: "Automatic backup snapshot retained before publish for this lesson only.",
  });
  await writeStoreAsync(store);
  const saved = (store.siteContent.curriculum.lessonPlans || []).find((item) => item.id === id);
  const summary = enrichmentApi.summarizePublishChanges
    ? enrichmentApi.summarizePublishChanges(existingPlan, linkedActivities, incomingDraft)
    : null;
  jsonResponse(response, 200, {
    ok: true,
    saveMode: "publish_enrichment",
    duplicate: false,
    versionId,
    fingerprint,
    publishSummary: summary,
    lessonPlan: saved,
    curriculum: store.siteContent.curriculum,
    siteContentUpdatedAt: store.siteContent.updatedAt,
    priorVersionAvailable: true,
    ownerOverrideApplied: Boolean(ownerOverrideMeta),
    ownerPublishOverride: ownerOverrideMeta || null,
  });
}

async function handleAdminCurriculumLessonPlanSave(request, response) {
  const startedAt = Date.now();
  let step = "received";
  console.log("[curriculum-lesson-save] request received");
  try {
    step = "readJson";
    const body = await readJson(request);
    step = "auth";
    if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
      jsonResponse(response, 401, { error: "Admin access is required to save curriculum lesson plans." });
      return;
    }
    const incomingPlan = body.lessonPlan && typeof body.lessonPlan === "object" ? body.lessonPlan : null;
    if (!incomingPlan) {
      jsonResponse(response, 400, { error: "A lesson plan payload is required." });
      return;
    }

    const saveMode = normalizedShortText(body.saveMode, 40) || "full";
    const incomingId = normalizedShortText(incomingPlan.id, 160);
    const id = incomingId || generateCurriculumLessonPlanId();
    const now = new Date().toISOString();
    step = "readStore";
    const store = readStore();
    // Read stamp/curriculum without re-normalizing the entire siteContent blob
    // (production lessonPlans can embed multi-MB data URLs).
    const siteContent = store.siteContent && typeof store.siteContent === "object"
      ? store.siteContent
      : defaultSiteContentStore();
    step = "concurrency";
    if (curriculumConcurrencyConflict(siteContent, body.expectedUpdatedAt)) {
      console.log("[curriculum-lesson-save] conflict 409", {
        id,
        expectedUpdatedAt: normalizedShortText(body.expectedUpdatedAt, 80),
        siteContentUpdatedAt: normalizedShortText(siteContent.updatedAt, 80),
      });
      curriculumConflictResponse(response, siteContent);
      return;
    }
    const existingCurriculum = siteContent.curriculum || defaultCurriculumStore();
    const existingPlan = (existingCurriculum.lessonPlans || []).find((item) => item.id === id);

    // Teaching Kit Enrichment Editor — draft-only save (published member view unchanged).
    if (saveMode === "enrichment_draft") {
      if (!requireTeachingKitOwnerAdminSession(request, body, response)) return;
      const enrichFlags = normalizedFeatureFlags(siteContent.featureFlags);
      if (!teachingKit.isTeachingKitEnrichmentEditorEnabled(enrichFlags)) {
        jsonResponse(response, 404, {
          error: "Teaching Kit Enrichment Editor is disabled.",
          code: "enrichment_editor_disabled",
        });
        return;
      }
      if (!existingPlan) {
        jsonResponse(response, 404, { error: "Lesson plan not found for enrichment draft." });
        return;
      }
      const previousDraft = existingPlan.enrichmentDraft && typeof existingPlan.enrichmentDraft === "object"
        ? existingPlan.enrichmentDraft
        : null;
      const draftInputRaw = incomingPlan.enrichmentDraft && typeof incomingPlan.enrichmentDraft === "object"
        ? enrichmentMedia.sanitizeEnrichmentDraftPhotos(incomingPlan.enrichmentDraft)
        : {};
      const allowEmptyOverwrite = body?.allowEmptyDraftOverwrite === true
        || incomingPlan?.allowEmptyDraftOverwrite === true;
      const mergeResult = mergeEnrichmentDraftForSave(previousDraft, draftInputRaw, { allowEmptyOverwrite });
      if (mergeResult.rejectedEmptyOverwrite) {
        jsonResponse(response, 409, {
          error: "Draft save refused: incoming draft would erase existing enrichment content. Refresh and try again, or clear the draft explicitly.",
          code: "enrichment_draft_empty_overwrite",
          lessonPlan: existingPlan,
          curriculum: existingCurriculum,
          siteContentUpdatedAt: siteContent.updatedAt,
        });
        return;
      }
      const draftInput = mergeResult.draft || {};
      const restoringDiscarded = body?.restoreDiscardedDraft === true
        || incomingPlan?.restoreDiscardedDraft === true;
      let undoStash = existingPlan.enrichmentDraftUndo && typeof existingPlan.enrichmentDraftUndo === "object"
        ? existingPlan.enrichmentDraftUndo
        : null;
      let draftForSave = draftInput;
      if (restoringDiscarded) {
        const stashDraft = undoStash?.draft && typeof undoStash.draft === "object" ? undoStash.draft : null;
        if (!enrichmentDraftHasContent(stashDraft)) {
          jsonResponse(response, 409, {
            error: "No discarded draft is available to undo.",
            code: "enrichment_draft_undo_missing",
            lessonPlan: existingPlan,
            curriculum: existingCurriculum,
            siteContentUpdatedAt: siteContent.updatedAt,
          });
          return;
        }
        draftForSave = {
          ...stashDraft,
          updatedAt: now,
          lastEditedBy: normalizedShortText(body?.adminEmail || incomingPlan?.lastEditedBy, 180) || stashDraft.lastEditedBy || "",
        };
        undoStash = null;
      } else if (
        allowEmptyOverwrite
        && enrichmentDraftHasContent(previousDraft)
        && !enrichmentDraftHasContent(draftInput)
      ) {
        // Discard Draft — keep one undo stash so admin can restore without republishing.
        undoStash = {
          discardedAt: now,
          discardedBy: normalizedShortText(body?.adminEmail || "", 180) || "",
          draft: previousDraft,
        };
      } else if (enrichmentDraftHasContent(draftInput)) {
        // A real draft save replaces any prior undo stash.
        undoStash = null;
      }
      const previousHistory = Array.isArray(existingPlan.enrichmentPublishHistory)
        ? existingPlan.enrichmentPublishHistory
        : [];
      let nextHistory = previousHistory;
      const adminEmail = normalizedShortText(
        body?.adminEmail || draftForSave.lastEditedBy || previousDraft?.lastEditedBy || "",
        180,
      ) || "admin";
      // Automatic version history before every meaningful draft save (previous draft snapshot).
      if (
        enrichmentDraftHasContent(previousDraft)
        && enrichmentHistoryFingerprint(previousDraft) !== enrichmentHistoryFingerprint(draftForSave)
      ) {
        nextHistory = [
          {
            versionId: `edraft-${crypto.randomBytes(10).toString("hex")}`,
            kind: "draft",
            publishedAt: now,
            publishedBy: adminEmail,
            fingerprint: `draft:${enrichmentHistoryFingerprint(previousDraft)}`,
            lessonPlanId: id,
            snapshot: { enrichmentDraft: cloneJson(previousDraft) },
          },
          ...previousHistory,
        ].slice(0, ENRICHMENT_HISTORY_LIMIT);
      }
      const draftPlan = normalizedCurriculumLessonPlan({
        ...existingPlan,
        enrichmentDraft: {
          ...draftForSave,
          updatedAt: now,
        },
        enrichmentDraftUndo: undoStash,
        enrichmentPublishHistory: nextHistory,
        updatedAt: existingPlan.updatedAt,
      });
      // Verify normalized draft still carries activity/week content when we intended to save it.
      if (enrichmentDraftHasContent(draftForSave) && !enrichmentDraftHasContent(draftPlan.enrichmentDraft)) {
        jsonResponse(response, 500, {
          error: "Draft save failed verification — enrichment content did not persist. Nothing was written.",
          code: "enrichment_draft_verify_failed",
        });
        return;
      }
      const nextCurriculum = normalizedCurriculumStore({
        ...existingCurriculum,
        lessonPlans: (existingCurriculum.lessonPlans || []).map((item) => (
          item.id === id ? { ...draftPlan, updatedAt: existingPlan.updatedAt } : item
        )),
        updatedAt: now,
      });
      const writeResult = writeSiteCurriculum(store, nextCurriculum, { updatedAt: now });
      if (writeResult.wipeBlocked) {
        jsonResponse(response, 409, {
          error: "This save was refused because it would have shrunk the live curriculum unexpectedly. Refresh and try again.",
          code: "curriculum_wipe_blocked",
        });
        return;
      }
      appendEnrichmentEditorAudit(store, {
        action: restoringDiscarded ? "undo_discard" : (allowEmptyOverwrite && !enrichmentDraftHasContent(draftForSave) ? "discard_draft" : "save_draft"),
        lessonPlanId: id,
        versionId: nextHistory[0]?.versionId || "",
        adminEmail,
        fingerprint: enrichmentHistoryFingerprint(draftForSave),
        note: restoringDiscarded
          ? "Restored discarded draft for this lesson only."
          : "Draft save for this lesson only; published content unchanged.",
      });
      await writeStoreAsync(store);
      // Delayed cleanup only: enqueue possible orphans — never delete during draft save.
      // Physical delete requires grace period + fresh authoritative ref scan (see process).
      const removedIds = enrichmentMedia.diffRemovedMediaAssetIds(previousDraft, draftPlan.enrichmentDraft);
      const prunedHistoryIds = enrichmentMedia.assetIdsOnlyInDroppedHistory(previousHistory, nextHistory);
      const cleanupCandidateIds = [...new Set([...removedIds, ...prunedHistoryIds])];
      const cleanupLogs = [];
      for (const removedId of cleanupCandidateIds) {
        cleanupLogs.push(enrichmentMedia.enqueueCleanupCandidate(store, {
          assetId: removedId,
          lessonPlanId: id,
          sourceOperation: removedIds.includes(removedId) ? "draft_save" : "history_prune",
          reason: removedIds.includes(removedId) ? "draft_save_unreferenced" : "history_prune_unreferenced",
        }));
      }
      if (cleanupCandidateIds.length) await writeStoreAsync(store);
      const saved = (store.siteContent.curriculum.lessonPlans || []).find((item) => item.id === id);
      jsonResponse(response, 200, {
        ok: true,
        saveMode: "enrichment_draft",
        lessonPlan: saved,
        curriculum: store.siteContent.curriculum,
        siteContentUpdatedAt: store.siteContent.updatedAt,
        publishedUnchanged: true,
        mediaCleanup: cleanupLogs,
        mediaCleanupMode: enrichmentMedia.cleanupModeFromEnv(),
      });
      return;
    }

    // Slice 5 — controlled enrichment publish (atomic, single lesson, versioned).
    if (saveMode === "publish_enrichment") {
      return await handlePublishEnrichment(request, response, {
        store,
        siteContent,
        existingCurriculum,
        existingPlan,
        incomingPlan,
        id,
        now,
        body,
      });
    }
    const nextStatus = normalizedShortText(incomingPlan.status, 20);
    const wasPublic = isCurriculumLessonPublic(existingPlan?.status || "");
    const willBePublic = isCurriculumLessonPublic(nextStatus);
    let publishedAt = normalizedShortText(existingPlan?.publishedAt, 80)
      || normalizedShortText(incomingPlan.publishedAt, 80)
      || "";
    if (willBePublic && !wasPublic) {
      publishedAt = now;
    } else if (willBePublic && !publishedAt) {
      // Legacy public plans: keep a stable stamp so weekly digests don't re-fire on every edit.
      publishedAt = existingPlan?.createdAt || now;
    }
    const planInput = withAutoAssignedLessonCover({
      ...incomingPlan,
      // Preserve an existing cover when the client omits cover fields on update.
      coverImageUrl: incomingPlan.coverImageUrl || existingPlan?.coverImageUrl || "",
      coverImageAlt: incomingPlan.coverImageAlt || existingPlan?.coverImageAlt || "",
      coverImageSource: incomingPlan.coverImageSource || existingPlan?.coverImageSource || "",
      coverImagePosition: incomingPlan.coverImagePosition || existingPlan?.coverImagePosition || "center",
      id,
      createdAt: existingPlan?.createdAt || normalizedShortText(incomingPlan.createdAt, 80) || now,
      updatedAt: now,
      publishedAt,
    });

    // Published/featured plans must keep activities on every weekday so the
    // lesson viewer never shows "No activities scheduled." after a save.
    if (willBePublic) {
      const emptyWeekdays = [];
      CURRICULUM_WEEKDAYS.forEach((day) => {
        const items = Array.isArray(planInput?.dailyPlans?.[day]?.items)
          ? planInput.dailyPlans[day].items
          : [];
        const hasTitle = items.some((item) => String(item?.title || "").trim());
        if (!hasTitle) emptyWeekdays.push(day);
      });
      if (emptyWeekdays.length) {
        jsonResponse(response, 400, {
          error: `Published lesson plans need activities on every weekday. Missing: ${emptyWeekdays.join(", ")}.`,
          emptyWeekdays,
        });
        return;
      }
    }

    step = "syncActivities";
    const syncedCurriculum = syncCurriculumActivitiesForLessonPlan(existingCurriculum, planInput);
    if (!syncedCurriculum) {
      jsonResponse(response, 400, { error: "Lesson plan could not be normalized." });
      return;
    }
    step = "integrity";
    const integrityError = assertCurriculumIntegrityOrError(syncedCurriculum);
    if (integrityError) {
      console.error("[curriculum-lesson-save] integrity failed", integrityError.details?.slice?.(0, 5) || integrityError);
      jsonResponse(response, 400, integrityError);
      return;
    }

    const savedPlan = syncedCurriculum.lessonPlans.find((item) => item.id === id);
    const savedActivities = syncedCurriculum.activities.filter((activity) => activity.lessonPlanId === id);
    step = "writeSiteCurriculum";
    const writeResult = writeSiteCurriculum(store, syncedCurriculum, { updatedAt: now });
    if (writeResult.wipeBlocked) {
      console.error("[curriculum-lesson-save] refused — would have shrunk the live curriculum unexpectedly", { id, step });
      jsonResponse(response, 409, {
        error: "This save was refused because it would have shrunk the live curriculum unexpectedly. Refresh and try again.",
        code: "curriculum_wipe_blocked",
      });
      return;
    }

    step = "writeStoreAsync";
    try {
      await writeStoreAsync(store);
    } catch (error) {
      console.error("Curriculum lesson plan save failed:", error.message, { step });
      jsonResponse(response, 503, { error: "Curriculum could not be saved. Please try again.", step });
      return;
    }

    console.log("[curriculum-lesson-save] ok", {
      id,
      activities: savedActivities.filter((item) => item.status !== "archived").length,
      ms: Date.now() - startedAt,
    });
    jsonResponse(response, 200, {
      lessonPlan: savedPlan,
      activities: savedActivities,
      curriculum: curriculumWithoutFileData(syncedCurriculum),
      siteContentUpdatedAt: writeResult.stamp,
    });
  } catch (error) {
    console.error("[curriculum-lesson-save] failed at step", step, error);
    jsonResponse(response, 500, {
      error: error.message || "Curriculum lesson plan save failed.",
      step,
    });
  }
}

async function persistCurriculumUploadToMediaAsset({ resourceId, parsed, fileName }) {
  if (!usePostgresStore() || !postgresPool || !databaseReady) {
    const error = new Error("Persistent media storage is unavailable.");
    error.code = "media_storage_unavailable";
    throw error;
  }
  const mediaAssetId = curriculumMedia.curriculumResourceMediaAssetId(resourceId);
  await curriculumMedia.insertMediaAsset(postgresPool, {
    id: mediaAssetId,
    kind: curriculumMedia.CURRICULUM_RESOURCE_MEDIA_KIND,
    mimeType: parsed.mimeType,
    fileName: fileName || "resource",
    buffer: parsed.buffer,
  });
  return {
    mediaAssetId,
    mediaUrl: curriculumMedia.curriculumResourceMediaUrl(mediaAssetId),
    mimeType: parsed.mimeType,
    fileName: fileName || "resource",
    sha256: curriculumMedia.sha256Buffer(parsed.buffer),
    byteLen: parsed.buffer.length,
  };
}

function findCurriculumResourceByMediaAssetId(store, mediaAssetId) {
  const curriculum = readSiteCurriculum(store);
  return (curriculum.resources || []).find((item) => item.mediaAssetId === mediaAssetId) || null;
}

async function buildCurriculumResourceFilePayload(resource) {
  const normalized = normalizedCurriculumResource(resource);
  if (!normalized) return null;
  if (normalized.mediaAssetId && usePostgresStore() && postgresPool && databaseReady) {
    const asset = await curriculumMedia.readMediaAsset(
      postgresPool,
      normalized.mediaAssetId,
      curriculumMedia.CURRICULUM_RESOURCE_MEDIA_KIND,
    );
    if (asset?.buffer?.length) {
      return curriculumMedia.curriculumResourcePublicDto(normalized, {
        fileData: "",
        mediaUrl: normalized.mediaUrl || curriculumMedia.curriculumResourceMediaUrl(normalized.mediaAssetId),
      });
    }
  }
  if (curriculumMedia.isHttpsCurriculumFileRef(normalized.fileData)) {
    return curriculumMedia.curriculumResourcePublicDto(normalized, {
      fileData: normalized.fileData,
      mediaUrl: normalized.fileData,
    });
  }
  if (curriculumMedia.isInlineCurriculumFileData(normalized.fileData)) {
    return curriculumMedia.curriculumResourcePublicDto(normalized, {
      fileData: normalized.fileData,
      mediaUrl: normalized.mediaUrl || "",
    });
  }
  if (normalized.mediaUrl) {
    return curriculumMedia.curriculumResourcePublicDto(normalized, {
      fileData: "",
      mediaUrl: normalized.mediaUrl,
    });
  }
  return null;
}

async function authorizePublicCurriculumResource(store, resource, request, url) {
  if (!resource || !isCurriculumResourcePublic(resource.status)) {
    return { ok: false, status: 404, error: "Resource not found." };
  }
  const curriculum = readSiteCurriculum(store);
  const publicLessons = curriculum.lessonPlans
    .map((plan) => curriculumParentPlanMeta(plan))
    .filter(Boolean);
  const linkedLessons = publicLessons.filter((plan) => (resource.lessonPlanIds || []).includes(plan.id));
  if (!linkedLessons.length) {
    return { ok: false, status: 404, error: "Resource not found." };
  }
  const requiresProAccess = linkedLessons.some((plan) => plan.plan === "Pro");
  if (requiresProAccess) {
    const access = await resolveCurriculumAccessUser(request, url);
    if (!access.authorized) {
      return { ok: false, status: 403, error: "Pro access is required for this resource." };
    }
  }
  return { ok: true };
}

function handleAdminCurriculumResourcesList(request, response, url) {
  const adminToken = extractAdminToken(request, url) || "";
  if (!validAdminToken(adminToken)) {
    jsonResponse(response, 401, { error: "Admin access is required to list curriculum resources." });
    return;
  }
  const store = readStore();
  const siteContent = normalizedSiteContent(store.siteContent || defaultSiteContentStore());
  const curriculum = siteContent.curriculum || defaultCurriculumStore();
  jsonResponse(response, 200, {
    resources: (curriculum.resources || []).map((item) => curriculumResourceMetadata(item)).filter(Boolean),
    curriculum: curriculumWithoutFileData(curriculum),
    siteContentUpdatedAt: normalizedShortText(siteContent.updatedAt, 80),
  });
}

async function handleAdminCurriculumResourceFile(request, response, url) {
  const adminToken = extractAdminToken(request, url) || "";
  if (!validAdminToken(adminToken)) {
    jsonResponse(response, 401, { error: "Admin access is required to open curriculum resource files." });
    return;
  }
  const id = normalizedShortText(url.searchParams.get("id"), 160);
  if (!id) {
    jsonResponse(response, 400, { error: "Resource id is required." });
    return;
  }
  const store = readStore();
  const curriculum = readSiteCurriculum(store);
  const resource = curriculum.resources.find((item) => item.id === id);
  if (!resource) {
    jsonResponse(response, 404, { error: "Resource not found." });
    return;
  }
  const payload = await buildCurriculumResourceFilePayload(resource);
  if (!payload) {
    jsonResponse(response, 404, { error: "Resource file data is not available." });
    return;
  }
  jsonResponse(response, 200, { resource: payload });
}

async function handleAdminCurriculumResourceUpload(request, response) {
  const body = await readJson(request);
  if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
    jsonResponse(response, 401, { error: "Admin access is required to upload curriculum resources." });
    return;
  }
  const resourceId = normalizedShortText(body.resourceId, 160) || generateCurriculumResourceId();
  const fileName = sanitizeCurriculumUploadFileName(body.fileName);
  const parsed = parseCurriculumUploadDataUrl(body.fileData);
  if (!parsed) {
    jsonResponse(response, 400, {
      error: `A valid PDF or image upload is required (max ${MAX_CURRICULUM_UPLOAD_MB} MB).`,
    });
    return;
  }
  if (usePostgresStore()) {
    if (!postgresPool || !databaseReady) {
      jsonResponse(response, 503, {
        error: "Persistent media storage is unavailable. The file was not saved to the curriculum store. Retry when Postgres is connected or paste a durable HTTPS URL instead.",
        code: "media_storage_unavailable",
      });
      return;
    }
    try {
      const stored = await persistCurriculumUploadToMediaAsset({ resourceId, parsed, fileName });
      jsonResponse(response, 200, {
        resourceId,
        fileName: stored.fileName,
        mimeType: stored.mimeType,
        mediaAssetId: stored.mediaAssetId,
        mediaUrl: stored.mediaUrl,
        persistent: true,
        byteLen: stored.byteLen,
        sha256: stored.sha256,
      });
      return;
    } catch (error) {
      console.error("[curriculum-resource-upload] media write failed", error.message);
      jsonResponse(response, 503, {
        error: "The file could not be saved to persistent media storage. It was not embedded in the main store.",
        code: error.code || "media_storage_unavailable",
      });
      return;
    }
  }
  jsonResponse(response, 200, {
    resourceId,
    fileName,
    mimeType: parsed.mimeType,
    fileData: parsed.fileData,
    persistent: false,
  });
}

/**
 * Cover-only patch — updates cover fields without rewriting daily plans/activities.
 * Body: { assignments: [{ id|title, coverImageUrl?, coverImageAlt?, clear?: boolean }] }
 * When coverImageUrl is omitted, auto-assigns from the cover resolver for that title/theme.
 */
async function handleAdminLessonCoverAssign(request, response) {
  const body = await readJson(request);
  if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
    jsonResponse(response, 401, { error: "Admin access is required to assign lesson-plan covers." });
    return;
  }
  const assignments = Array.isArray(body.assignments) ? body.assignments : [];
  if (!assignments.length) {
    jsonResponse(response, 400, { error: "assignments[] is required." });
    return;
  }
  if (assignments.length > 300) {
    jsonResponse(response, 400, { error: "Assign at most 300 covers per request." });
    return;
  }
  const store = readStore();
  const siteContent = store.siteContent && typeof store.siteContent === "object"
    ? store.siteContent
    : defaultSiteContentStore();
  const curriculum = siteContent.curriculum || defaultCurriculumStore();
  const plans = Array.isArray(curriculum.lessonPlans) ? curriculum.lessonPlans : [];
  const byId = new Map(plans.map((p) => [String(p.id || ""), p]));
  const now = new Date().toISOString();
  const updated = [];
  const missing = [];

  for (const row of assignments) {
    if (!row || typeof row !== "object") continue;
    const id = normalizedShortText(row.id, 160);
    const titleKey = String(row.title || "").trim().toLowerCase();
    let plan = id ? byId.get(id) : null;
    if (!plan && titleKey) {
      plan = plans.find((p) => String(p.title || "").trim().toLowerCase() === titleKey) || null;
    }
    if (!plan) {
      missing.push(id || titleKey || "(unknown)");
      continue;
    }
    let nextUrl = sanitizedLessonCoverUrl(row.coverImageUrl || "");
    let nextAlt = normalizedShortText(row.coverImageAlt, 180);
    let nextSource = normalizedShortText(row.coverImageSource, 40) || "mapped";
    if (row.clear === true) {
      nextUrl = "";
      nextAlt = "";
      nextSource = "";
    } else if (!nextUrl) {
      const assigned = withAutoAssignedLessonCover({
        ...plan,
        coverImageUrl: "",
        thumbnailUrl: "",
        coverImageSource: "",
      });
      nextUrl = sanitizedLessonCoverUrl(assigned.coverImageUrl || "");
      nextAlt = normalizedShortText(assigned.coverImageAlt || nextAlt || `Illustration for ${plan.title || "lesson plan"}`, 180);
      nextSource = normalizedShortText(assigned.coverImageSource, 40) || "mapped";
    }
    if (!nextUrl && row.clear !== true) {
      missing.push(plan.id);
      continue;
    }
    plan.coverImageUrl = nextUrl;
    plan.coverImageAlt = nextAlt || `Illustration for ${plan.title || "lesson plan"}`;
    plan.coverImageSource = nextSource || "mapped";
    plan.coverImagePosition = normalizedShortText(row.coverImagePosition || plan.coverImagePosition || "center", 40) || "center";
    plan.updatedAt = now;
    updated.push({
      id: plan.id,
      title: plan.title,
      coverImageUrl: plan.coverImageUrl,
    });
  }

  if (!updated.length) {
    jsonResponse(response, 404, { error: "No matching lesson plans found to update.", missing });
    return;
  }

  curriculum.updatedAt = now;
  siteContent.curriculum = curriculum;
  siteContent.updatedAt = now;
  store.siteContent = siteContent;
  try {
    await writeStoreAsync(store);
  } catch (error) {
    console.error("[lesson-cover-assign] write failed", error.message);
    jsonResponse(response, 503, { error: "Covers could not be saved. Please try again." });
    return;
  }
  jsonResponse(response, 200, {
    ok: true,
    updatedCount: updated.length,
    updated,
    missing,
    curriculumUpdatedAt: now,
  });
}

async function handleAdminLessonCoverUpload(request, response) {
  const body = await readJson(request);
  if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
    jsonResponse(response, 401, { error: "Admin access is required to upload lesson-plan covers." });
    return;
  }
  if (!usePostgresStore() || !postgresPool || !databaseReady) {
    jsonResponse(response, 503, {
      error: "Persistent media storage is unavailable. The image was not saved; choose an existing cover or paste a durable HTTPS URL.",
    });
    return;
  }
  const parsed = parseLessonCoverUploadDataUrl(body.fileData);
  if (!parsed) {
    jsonResponse(response, 400, {
      error: `Use a PNG, JPG, or WebP image no larger than ${MAX_LESSON_COVER_UPLOAD_MB} MB.`,
    });
    return;
  }
  const id = `lesson-cover-${crypto.randomBytes(16).toString("hex")}`;
  const fileName = sanitizeCurriculumUploadFileName(body.fileName || "lesson-cover");
  try {
    await postgresPool.query(
      `INSERT INTO llh_media_assets (id, kind, mime_type, file_name, bytes)
       VALUES ($1, $2, $3, $4, $5)`,
      [id, "lesson-plan-cover", parsed.mimeType, fileName, parsed.buffer],
    );
    jsonResponse(response, 200, {
      id,
      url: `/api/media/lesson-covers/${encodeURIComponent(id)}`,
      mimeType: parsed.mimeType,
      fileName,
      persistent: true,
    });
  } catch (error) {
    console.error("[lesson-cover-upload] persistent write failed", error.message);
    jsonResponse(response, 503, {
      error: "The cover could not be saved to persistent media storage. The lesson plan was not changed.",
    });
  }
}

function readEnrichmentMediaRegistry(store) {
  if (!store.enrichmentMediaRegistry || typeof store.enrichmentMediaRegistry !== "object") {
    store.enrichmentMediaRegistry = {};
  }
  return store.enrichmentMediaRegistry;
}

function setEnrichmentMediaRegistryEntry(store, assetId, patch) {
  const registry = readEnrichmentMediaRegistry(store);
  const prev = registry[assetId] && typeof registry[assetId] === "object" ? registry[assetId] : {};
  registry[assetId] = {
    ...prev,
    ...patch,
    id: assetId,
    updatedAt: new Date().toISOString(),
  };
  return registry[assetId];
}

function getEnrichmentMediaVisibility(store, assetId, localAsset) {
  const registry = readEnrichmentMediaRegistry(store);
  const fromRegistry = registry[assetId]?.visibility;
  if (fromRegistry) return String(fromRegistry);
  if (localAsset?.visibility) return String(localAsset.visibility);
  return "draft_private";
}

async function persistEnrichmentPhotoVariants({
  assetId,
  lessonPlanId,
  activityKey,
  field,
  fileName,
  variants,
  store,
}) {
  const meta = {
    lessonPlanId,
    activityKey,
    field,
    fileName: fileName || "photo",
    visibility: "draft_private",
    createdAt: new Date().toISOString(),
  };
  const writtenVariants = [];
  try {
    if (usePostgresStore() && postgresPool && databaseReady) {
      for (const variant of ["full", "thumb"]) {
        const row = variants[variant];
        const rowId = enrichmentMedia.enrichmentVariantAssetId(assetId, variant);
        await curriculumMedia.insertMediaAsset(postgresPool, {
          id: rowId,
          kind: enrichmentMedia.ENRICHMENT_MEDIA_KIND,
          mimeType: row.mimeType,
          fileName: `${fileName || "photo"}${variant === "thumb" ? "-thumb" : ""}`,
          buffer: row.buffer,
        });
        writtenVariants.push(variant);
      }
      if (store) {
        setEnrichmentMediaRegistryEntry(store, assetId, {
          ...meta,
          storage: "postgres",
        });
        await writeStoreAsync(store);
      }
      return { persistent: true, storage: "postgres" };
    }
    const dir = enrichmentMedia.localMediaDirFromStorePath(storePath);
    for (const variant of ["full", "thumb"]) {
      const row = variants[variant];
      enrichmentMedia.writeLocalEnrichmentAsset(dir, assetId, variant, {
        mimeType: row.mimeType,
        buffer: row.buffer,
        meta,
      });
      writtenVariants.push(variant);
    }
    if (store) {
      setEnrichmentMediaRegistryEntry(store, assetId, {
        ...meta,
        storage: "local-sidecar",
      });
      await writeStoreAsync(store);
    }
    return { persistent: true, storage: "local-sidecar" };
  } catch (error) {
    // Failed uploads must not leave partial full/thumb records.
    try {
      await deleteEnrichmentPhotoAsset(assetId, { force: true });
    } catch (_cleanupError) {
      // ignore secondary cleanup errors
    }
    if (store?.enrichmentMediaRegistry) {
      delete store.enrichmentMediaRegistry[assetId];
    }
    throw error;
  }
}

async function readEnrichmentPhotoVariant(assetId, variant) {
  const v = variant === "thumb" ? "thumb" : "full";
  if (usePostgresStore() && postgresPool && databaseReady) {
    const rowId = enrichmentMedia.enrichmentVariantAssetId(assetId, v);
    const asset = await curriculumMedia.readMediaAsset(
      postgresPool,
      rowId,
      enrichmentMedia.ENRICHMENT_MEDIA_KIND,
    );
    if (!asset?.buffer?.length) return null;
    return {
      id: assetId,
      variant: v,
      mimeType: asset.mimeType,
      fileName: asset.fileName,
      buffer: asset.buffer,
      byteLen: asset.byteLen,
      visibility: "draft_private",
    };
  }
  return enrichmentMedia.readLocalEnrichmentAsset(
    enrichmentMedia.localMediaDirFromStorePath(storePath),
    assetId,
    v,
  );
}

async function deleteEnrichmentPhotoAsset(assetId, { force = false } = {}) {
  if (usePostgresStore() && postgresPool && databaseReady) {
    for (const variant of ["full", "thumb"]) {
      const rowId = enrichmentMedia.enrichmentVariantAssetId(assetId, variant);
      try {
        await postgresPool.query(
          `DELETE FROM llh_media_assets WHERE id = $1 AND kind = $2`,
          [rowId, enrichmentMedia.ENRICHMENT_MEDIA_KIND],
        );
      } catch (error) {
        console.error("[enrichment-photo-delete] postgres delete failed", error.message);
        if (!force) throw error;
      }
    }
    return;
  }
  enrichmentMedia.deleteLocalEnrichmentAsset(
    enrichmentMedia.localMediaDirFromStorePath(storePath),
    assetId,
  );
}

/**
 * Enqueue a delayed cleanup candidate (no physical delete).
 * Published/shared assets are never enqueued.
 * Client-supplied reference lists are ignored — only server store state matters later.
 */
async function cleanupEnrichmentMediaAsset(store, {
  mediaAssetId,
  lessonPlanId = "",
  reason = "cleanup",
  sourceOperation = "manual_cleanup",
  actor = "",
} = {}) {
  const assetId = normalizedShortText(mediaAssetId, 120);
  const timestamp = new Date().toISOString();
  if (!enrichmentMedia.isEnrichmentMediaAssetId(assetId)) {
    return enrichmentMedia.logEnrichmentMediaCleanup(storePath, {
      assetId,
      lessonPlanId,
      reason,
      sourceOperation,
      actor,
      result: "rejected_invalid_id",
      timestamp,
    });
  }
  const visibility = getEnrichmentMediaVisibility(store, assetId);
  if (visibility === "published" || visibility === "shared") {
    return enrichmentMedia.logEnrichmentMediaCleanup(storePath, {
      assetId,
      lessonPlanId,
      reason,
      sourceOperation,
      actor,
      status: "skipped",
      result: "skipped_published_or_shared",
      timestamp,
    });
  }
  // Fast cancel if currently referenced in this store snapshot (still only enqueue otherwise).
  const refs = enrichmentMedia.collectStoreEnrichmentMediaRefs(store);
  const liveHits = refs.get(assetId) || [];
  if (liveHits.length) {
    return enrichmentMedia.logEnrichmentMediaCleanup(storePath, {
      assetId,
      lessonPlanId,
      reason,
      sourceOperation,
      actor,
      status: "skipped",
      result: `skipped_still_referenced:${liveHits.map((h) => h.source).slice(0, 4).join(",")}`,
      timestamp,
    });
  }
  const enqueued = enrichmentMedia.enqueueCleanupCandidate(store, {
    assetId,
    lessonPlanId,
    sourceOperation,
    reason,
    now: timestamp,
  });
  return enrichmentMedia.logEnrichmentMediaCleanup(storePath, {
    ...enqueued,
    actor,
  });
}

/**
 * Process delayed cleanup candidates using a fresh authoritative store read.
 * Default mode is dry-run (ENRICHMENT_MEDIA_CLEANUP_MODE); execute requires env opt-in.
 */
async function processEnrichmentMediaCleanupCandidates(store, {
  actor = "",
  mode = enrichmentMedia.cleanupModeFromEnv(),
  graceMs = enrichmentMedia.cleanupGraceMsFromEnv(),
  now = new Date(),
} = {}) {
  // Critical: re-load authoritative committed state so stale in-memory stores cannot delete.
  const authoritativeStore = typeof readStore === "function" ? readStore() : store;
  const result = await enrichmentMedia.processCleanupCandidates({
    workingStore: store,
    authoritativeStore,
    now,
    mode,
    graceMs,
    logPath: storePath,
    deleteAssetFn: async (assetId) => {
      await deleteEnrichmentPhotoAsset(assetId);
    },
  });
  result.logs.forEach((log) => {
    enrichmentMedia.logEnrichmentMediaCleanup(storePath, { ...log, actor });
  });
  return result;
}

async function handleAdminEnrichmentPhotoUpload(request, response) {
  const body = await readJson(request);
  if (!requireTeachingKitOwnerAdminSession(request, body, response)) return;
  const store = readStore();
  const siteContent = store.siteContent && typeof store.siteContent === "object"
    ? store.siteContent
    : defaultSiteContentStore();
  const enrichFlags = normalizedFeatureFlags(siteContent.featureFlags);
  if (!teachingKit.isTeachingKitEnrichmentEditorEnabled(enrichFlags)) {
    jsonResponse(response, 404, {
      error: "Teaching Kit Enrichment Editor is disabled.",
      code: "enrichment_editor_disabled",
    });
    return;
  }
  const lessonPlanId = normalizedShortText(body.lessonPlanId, 160);
  const activityKey = normalizedShortText(body.activityKey, 160);
  const field = normalizedShortText(body.field, 40);
  if (!lessonPlanId || !activityKey || !["setupImageUrl", "exampleImageUrl"].includes(field)) {
    jsonResponse(response, 400, {
      error: "lessonPlanId, activityKey, and field (setupImageUrl|exampleImageUrl) are required.",
      code: "invalid_enrichment_photo_target",
    });
    return;
  }
  const curriculum = readSiteCurriculum(store);
  const plan = (curriculum.lessonPlans || []).find((item) => item.id === lessonPlanId);
  if (!plan) {
    jsonResponse(response, 404, { error: "Lesson plan not found." });
    return;
  }
  const parsed = enrichmentMedia.parseEnrichmentUploadDataUrl(body.fileData);
  if (!parsed.ok) {
    jsonResponse(response, 400, {
      error: parsed.error,
      code: parsed.code,
    });
    return;
  }
  const fileName = sanitizeCurriculumUploadFileName(body.fileName || "activity-photo");
  let variants;
  try {
    variants = await enrichmentMedia.buildEnrichmentVariants(parsed.buffer);
  } catch (error) {
    console.error("[enrichment-photo-upload] optimize failed", error.message);
    jsonResponse(response, 400, {
      error: "Could not process image. Try a different JPEG, PNG, or WebP.",
      code: "image_process_failed",
    });
    return;
  }
  const assetId = enrichmentMedia.enrichmentMediaAssetId();
  try {
    const stored = await persistEnrichmentPhotoVariants({
      assetId,
      lessonPlanId,
      activityKey,
      field,
      fileName,
      variants,
      store,
    });
    const mediaUrl = enrichmentMedia.enrichmentMediaUrl(assetId, "full");
    const thumbUrl = enrichmentMedia.enrichmentMediaUrl(assetId, "thumb");
    jsonResponse(response, 200, {
      ok: true,
      mediaAssetId: assetId,
      mediaUrl,
      thumbUrl,
      field,
      lessonPlanId,
      activityKey,
      mimeType: variants.full.mimeType,
      thumbMimeType: variants.thumb.mimeType,
      fileName,
      byteLen: variants.full.buffer.length,
      thumbByteLen: variants.thumb.buffer.length,
      originalByteLen: parsed.buffer.length,
      optimized: variants.full.optimized && variants.thumb.optimized,
      sharpAvailable: enrichmentMedia.sharpAvailable(),
      persistent: stored.persistent,
      storage: stored.storage,
      visibility: "draft_private",
      sha256: enrichmentMedia.sha256Buffer(variants.full.buffer),
    });
  } catch (error) {
    console.error("[enrichment-photo-upload] store failed", error.message);
    jsonResponse(response, 503, {
      error: "Enrichment photo could not be saved to media storage.",
      code: "media_storage_unavailable",
    });
  }
}

async function handleAdminEnrichmentPhotoMedia(request, response, assetId, url) {
  const id = normalizedShortText(assetId, 120);
  if (!enrichmentMedia.isEnrichmentMediaAssetId(id)) {
    textResponse(response, 404, "Photo not found.");
    return;
  }
  const adminToken = extractAdminToken(request, url)
    || normalizedShortText(url.searchParams.get("adminToken"), 500);
  if (!validAdminToken(adminToken)) {
    // Draft photos are never public — fail closed.
    textResponse(response, 404, "Photo not found.");
    return;
  }
  const store = readStore();
  const enrichFlags = normalizedFeatureFlags(store.siteContent?.featureFlags);
  if (!teachingKit.isTeachingKitEnrichmentEditorEnabled(enrichFlags)) {
    textResponse(response, 404, "Photo not found.");
    return;
  }
  const variant = String(url.searchParams.get("variant") || "full").toLowerCase() === "thumb"
    ? "thumb"
    : "full";
  try {
    const asset = await readEnrichmentPhotoVariant(id, variant);
    if (!asset?.buffer?.length) {
      textResponse(response, 404, "Photo not found.");
      return;
    }
    const visibility = getEnrichmentMediaVisibility(store, id, asset);
    response.writeHead(200, {
      "Content-Type": asset.mimeType || "application/octet-stream",
      "Content-Length": asset.buffer.length,
      "Cache-Control": "private, no-store",
      "X-Content-Type-Options": "nosniff",
      "X-LLH-Enrichment-Visibility": visibility,
    });
    if (request.method === "HEAD") {
      response.end();
      return;
    }
    response.end(asset.buffer);
  } catch (error) {
    console.error("[enrichment-photo-media] read failed", error.message);
    textResponse(response, 503, "Photo temporarily unavailable.");
  }
}

/** Provider-facing enrichment photos — only after successful publish (visibility=published). */
async function handlePublicEnrichmentPhotoMedia(request, response, assetId, url) {
  const id = normalizedShortText(assetId, 120);
  if (!enrichmentMedia.isEnrichmentMediaAssetId(id)) {
    textResponse(response, 404, "Photo not found.");
    return;
  }
  const store = readStore();
  const visibility = getEnrichmentMediaVisibility(store, id);
  if (visibility !== "published" && visibility !== "shared") {
    // Draft rollback / unpublished assets stay private.
    textResponse(response, 404, "Photo not found.");
    return;
  }
  const variant = String(url.searchParams.get("variant") || "full").toLowerCase() === "thumb"
    ? "thumb"
    : "full";
  try {
    const asset = await readEnrichmentPhotoVariant(id, variant);
    if (!asset?.buffer?.length) {
      textResponse(response, 404, "Photo not found.");
      return;
    }
    response.writeHead(200, {
      "Content-Type": asset.mimeType || "application/octet-stream",
      "Content-Length": asset.buffer.length,
      "Cache-Control": "public, max-age=86400",
      "X-Content-Type-Options": "nosniff",
      "X-LLH-Enrichment-Visibility": visibility,
    });
    if (request.method === "HEAD") {
      response.end();
      return;
    }
    response.end(asset.buffer);
  } catch (error) {
    console.error("[enrichment-photo-public] read failed", error.message);
    textResponse(response, 503, "Photo temporarily unavailable.");
  }
}

async function handleAdminEnrichmentPhotoDelete(request, response) {
  const body = await readJson(request);
  if (!requireTeachingKitOwnerAdminSession(request, body, response)) return;
  const store = readStore();
  const enrichFlags = normalizedFeatureFlags(store.siteContent?.featureFlags);
  if (!teachingKit.isTeachingKitEnrichmentEditorEnabled(enrichFlags)) {
    jsonResponse(response, 404, {
      error: "Teaching Kit Enrichment Editor is disabled.",
      code: "enrichment_editor_disabled",
    });
    return;
  }
  const mediaAssetId = normalizedShortText(body.mediaAssetId, 120);
  const lessonPlanId = normalizedShortText(body.lessonPlanId, 160);
  const reason = normalizedShortText(body.reason, 80) || "admin_delete";
  const actor = normalizedShortText(body.adminEmail || "", 120);
  if (!enrichmentMedia.isEnrichmentMediaAssetId(mediaAssetId)) {
    jsonResponse(response, 400, { error: "Valid mediaAssetId is required.", code: "invalid_media_asset" });
    return;
  }
  // Never trust client-provided reference lists — enqueue only after server ref check.
  const log = await cleanupEnrichmentMediaAsset(store, {
    mediaAssetId,
    lessonPlanId,
    reason,
    sourceOperation: "manual_enqueue",
    actor,
  });
  await writeStoreAsync(store);

  if (String(log.result || "").startsWith("skipped_still_referenced")) {
    jsonResponse(response, 409, {
      ok: false,
      mediaAssetId,
      deleted: false,
      code: "asset_still_referenced",
      error: "Photo asset is still referenced and was not deleted.",
      cleanup: log,
    });
    return;
  }
  if (log.result === "skipped_published_or_shared") {
    jsonResponse(response, 409, {
      ok: false,
      mediaAssetId,
      deleted: false,
      code: "asset_published_or_shared",
      error: "Published or shared photo assets cannot be deleted by draft cleanup.",
      cleanup: log,
    });
    return;
  }
  if (log.result === "candidate_enqueued") {
    // Optionally process immediately (still dry-run by default; execute only when env allows).
    const processNow = body.processNow === true;
    let processResult = null;
    if (processNow) {
      const envMode = enrichmentMedia.cleanupModeFromEnv();
      processResult = await processEnrichmentMediaCleanupCandidates(store, {
        actor,
        mode: body.dryRun === true || envMode !== "execute" ? "dry-run" : "execute",
        graceMs: body.ignoreGrace === true ? 0 : enrichmentMedia.cleanupGraceMsFromEnv(),
      });
      await writeStoreAsync(store);
    }
    jsonResponse(response, 200, {
      ok: true,
      mediaAssetId,
      deleted: false,
      candidateEnqueued: true,
      cleanup: log,
      processResult,
      mediaCleanupMode: enrichmentMedia.cleanupModeFromEnv(),
    });
    return;
  }
  jsonResponse(response, 400, {
    ok: false,
    mediaAssetId,
    deleted: false,
    code: "cleanup_rejected",
    cleanup: log,
  });
}

async function handleAdminEnrichmentMediaCleanupProcess(request, response) {
  const body = await readJson(request);
  if (!requireTeachingKitOwnerAdminSession(request, body, response)) return;
  const store = readStore();
  const enrichFlags = normalizedFeatureFlags(store.siteContent?.featureFlags);
  if (!teachingKit.isTeachingKitEnrichmentEditorEnabled(enrichFlags)) {
    jsonResponse(response, 404, {
      error: "Teaching Kit Enrichment Editor is disabled.",
      code: "enrichment_editor_disabled",
    });
    return;
  }
  const actor = normalizedShortText(body.adminEmail || "", 120);
  // Production default is dry-run. Execute only when env ENRICHMENT_MEDIA_CLEANUP_MODE=execute
  // AND the caller did not force dryRun:true.
  const envMode = enrichmentMedia.cleanupModeFromEnv();
  const effectiveMode = body.dryRun === true || envMode !== "execute" ? "dry-run" : "execute";
  const graceMs = body.ignoreGrace === true ? 0 : enrichmentMedia.cleanupGraceMsFromEnv();
  const result = await processEnrichmentMediaCleanupCandidates(store, {
    actor,
    mode: effectiveMode,
    graceMs,
  });
  await writeStoreAsync(store);
  jsonResponse(response, 200, {
    ok: true,
    mode: result.mode,
    graceMs: result.graceMs,
    logs: result.logs,
    candidateCount: Object.keys(store.enrichmentMediaCleanupCandidates || {}).length,
  });
}

async function handleLessonCoverMedia(request, response, assetId) {
  const id = normalizedShortText(assetId, 120);
  if (!id || !id.startsWith("lesson-cover-") || !usePostgresStore() || !postgresPool || !databaseReady) {
    textResponse(response, 404, "Cover not found.");
    return;
  }
  try {
    const result = await postgresPool.query(
      `SELECT mime_type, bytes
       FROM llh_media_assets
       WHERE id = $1 AND kind = $2
       LIMIT 1`,
      [id, "lesson-plan-cover"],
    );
    const asset = result.rows[0];
    if (!asset?.bytes) {
      textResponse(response, 404, "Cover not found.");
      return;
    }
    response.writeHead(200, {
      "Content-Type": asset.mime_type,
      "Content-Length": asset.bytes.length,
      "Cache-Control": "public, max-age=31536000, immutable",
      "X-Content-Type-Options": "nosniff",
    });
    if (request.method === "HEAD") {
      response.end();
      return;
    }
    response.end(asset.bytes);
  } catch (error) {
    console.error("[lesson-cover-media] read failed", error.message);
    textResponse(response, 503, "Cover temporarily unavailable.");
  }
}

async function handleCurriculumResourceMedia(request, response, assetId, { admin = false, requestUrl = null } = {}) {
  const id = normalizedShortText(assetId, 160);
  if (!id || !id.startsWith("curriculum-resource-") || !usePostgresStore() || !postgresPool || !databaseReady) {
    textResponse(response, 404, "Resource not found.");
    return;
  }
  const store = readStore();
  const resource = findCurriculumResourceByMediaAssetId(store, id);
  if (!resource) {
    textResponse(response, 404, "Resource not found.");
    return;
  }
  if (!admin) {
    const auth = await authorizePublicCurriculumResource(store, resource, request, requestUrl || new URL(request.url, SITE_URL));
    if (!auth.ok) {
      textResponse(response, auth.status || 404, auth.error || "Resource not found.");
      return;
    }
  }
  try {
    const asset = await curriculumMedia.readMediaAsset(
      postgresPool,
      id,
      curriculumMedia.CURRICULUM_RESOURCE_MEDIA_KIND,
    );
    if (!asset?.buffer?.length) {
      textResponse(response, 404, "Resource not found.");
      return;
    }
    response.writeHead(200, {
      "Content-Type": asset.mimeType,
      "Content-Length": asset.buffer.length,
      "Cache-Control": "public, max-age=31536000, immutable",
      "X-Content-Type-Options": "nosniff",
    });
    if (request.method === "HEAD") {
      response.end();
      return;
    }
    response.end(asset.buffer);
  } catch (error) {
    console.error("[curriculum-resource-media] read failed", error.message);
    textResponse(response, 503, "Resource temporarily unavailable.");
  }
}

async function handleAdminCurriculumInlineInventory(request, response) {
  const body = request.method === "POST" ? await readJson(request) : {};
  const token = extractAdminToken(request, new URL(request.url, SITE_URL))
    || extractAdminTokenFromBody(request, body);
  if (!validAdminToken(token)) {
    jsonResponse(response, 401, { error: "Admin access is required." });
    return;
  }
  const store = readStore();
  const inventory = curriculumResourceMigration.inventoryInlineCurriculumResources(store);
  const storeBytes = Buffer.byteLength(JSON.stringify(store), "utf8");
  jsonResponse(response, 200, {
    ok: true,
    count: inventory.length,
    storeBytes,
    storeMegabytes: +(storeBytes / 1024 / 1024).toFixed(2),
    inlineBytes: inventory.reduce((sum, row) => sum + (row.base64Chars || 0), 0),
    inventory,
  });
}

async function handleAdminCurriculumMigrateInlineMedia(request, response) {
  const body = await readJson(request);
  if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
    jsonResponse(response, 401, { error: "Admin access is required to migrate curriculum media." });
    return;
  }
  if (!usePostgresStore() || !postgresPool || !databaseReady) {
    jsonResponse(response, 503, {
      error: "Postgres media storage must be connected before running curriculum media migration.",
      code: "media_storage_unavailable",
    });
    return;
  }
  const dryRun = body.dryRun !== false && body.execute !== true;
  const limit = Math.max(0, Math.min(100, Number(body.limit) || 0));
  const resourceIds = Array.isArray(body.resourceIds)
    ? body.resourceIds.map((id) => normalizedShortText(id, 160)).filter(Boolean)
    : (normalizedShortText(body.resourceId, 160) ? [normalizedShortText(body.resourceId, 160)] : []);
  const removeInlineAfterVerify = body.removeInlineAfterVerify === true;
  const store = readStore();
  const beforeBytes = Buffer.byteLength(JSON.stringify(store), "utf8");
  const summary = await curriculumResourceMigration.runInlineResourceMigration(postgresPool, store, {
    dryRun,
    limit,
    resourceIds,
    removeInlineAfterVerify,
  });
  if (!dryRun) {
    try {
      await writeStoreAsync(store);
    } catch (error) {
      jsonResponse(response, 503, {
        error: "Migration steps completed in media storage but the store could not be persisted.",
        code: "store_write_failed",
        summary,
      });
      return;
    }
  }
  const afterBytes = Buffer.byteLength(JSON.stringify(store), "utf8");
  jsonResponse(response, 200, {
    ok: true,
    dryRun,
    beforeBytes,
    afterBytes,
    bytesRemoved: Math.max(0, beforeBytes - afterBytes),
    summary,
  });
}

async function handleAdminCurriculumResourceSave(request, response) {
  const body = await readJson(request);
  if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
    jsonResponse(response, 401, { error: "Admin access is required to save curriculum resources." });
    return;
  }
  const incoming = body.resource && typeof body.resource === "object" ? body.resource : null;
  if (!incoming) {
    jsonResponse(response, 400, { error: "A resource payload is required." });
    return;
  }
  const incomingInlineFileData = sanitizedCurriculumFileData(incoming.fileData)
    || sanitizedCurriculumFileData(incoming.fileUrl);
  if (
    usePostgresStore()
    && curriculumMedia.isInlineCurriculumFileData(incomingInlineFileData)
    && !normalizedShortText(incoming.mediaAssetId, 160)
  ) {
    jsonResponse(response, 400, {
      error: "Inline base64 curriculum files cannot be saved in Postgres mode. Upload the file again so it is stored in llh_media_assets, or provide an HTTPS URL.",
      code: "inline_curriculum_file_blocked",
    });
    return;
  }
  const now = new Date().toISOString();
  const store = readStore();
  const siteContent = normalizedSiteContent(store.siteContent || defaultSiteContentStore());
  if (curriculumConcurrencyConflict(siteContent, body.expectedUpdatedAt)) {
    curriculumConflictResponse(response, siteContent);
    return;
  }
  const curriculum = siteContent.curriculum || defaultCurriculumStore();
  const incomingId = normalizedShortText(incoming.id, 160);
  const id = incomingId || generateCurriculumResourceId();
  const existing = curriculum.resources.find((item) => item.id === id);
  const incomingFileData = sanitizedCurriculumFileData(incoming.fileData)
    || sanitizedCurriculumFileData(incoming.fileUrl);
  const incomingMediaAssetId = normalizedShortText(incoming.mediaAssetId, 160);
  const incomingMediaUrl = normalizedShortText(incoming.mediaUrl, 400);
  let fileData = incomingFileData || existing?.fileData || "";
  let mediaAssetId = incomingMediaAssetId || existing?.mediaAssetId || "";
  let mediaUrl = incomingMediaUrl || existing?.mediaUrl || "";
  if (incomingMediaAssetId) {
    mediaAssetId = incomingMediaAssetId;
    mediaUrl = incomingMediaUrl || curriculumMedia.curriculumResourceMediaUrl(mediaAssetId);
    if (usePostgresStore() && curriculumMedia.isInlineCurriculumFileData(fileData)) {
      fileData = existing?.fileData?.startsWith("https://") ? existing.fileData : "";
    }
  }
  if (!fileData && !mediaAssetId) {
    jsonResponse(response, 400, { error: "A file upload, media asset, or HTTPS URL is required." });
    return;
  }
  if (usePostgresStore() && curriculumMedia.isInlineCurriculumFileData(fileData)) {
    jsonResponse(response, 400, {
      error: "Inline base64 curriculum files cannot be saved in Postgres mode. Upload the file again so it is stored in llh_media_assets, or provide an HTTPS URL.",
      code: "inline_curriculum_file_blocked",
    });
    return;
  }
  if (fileData.startsWith("data:")) {
    const parsed = parseCurriculumUploadDataUrl(fileData);
    if (!parsed) {
      jsonResponse(response, 400, {
        error: `Uploaded file must be a PDF or image under ${MAX_CURRICULUM_UPLOAD_MB} MB.`,
      });
      return;
    }
  }
  const nextStatus = normalizedShortText(incoming.status || existing?.status || "draft", 20);
  const wasPublished = existing?.status === "published";
  const willBePublished = nextStatus === "published";
  let publishedAt = existing?.publishedAt || "";
  if (willBePublished && !wasPublished) publishedAt = now;
  else if (willBePublished && !publishedAt) publishedAt = existing?.createdAt || now;
  const resource = normalizedCurriculumResource({
    ...existing,
    ...incoming,
    id,
    fileData,
    mediaAssetId,
    mediaUrl: mediaUrl || (mediaAssetId ? curriculumMedia.curriculumResourceMediaUrl(mediaAssetId) : ""),
    fileName: normalizedShortText(incoming.fileName, 180) || existing?.fileName || "",
    mimeType: normalizedShortText(incoming.mimeType, 80) || existing?.mimeType || "",
    lessonPlanIds: existing?.lessonPlanIds || incoming.lessonPlanIds || [],
    status: nextStatus,
    createdAt: existing?.createdAt || normalizedShortText(incoming.createdAt, 80) || now,
    updatedAt: now,
    publishedAt,
  });
  if (!resource) {
    jsonResponse(response, 400, { error: "Resource could not be normalized." });
    return;
  }
  const nextResources = [...curriculum.resources.filter((item) => item.id !== id), resource];
  const nextCurriculum = normalizedCurriculumStore({
    ...curriculum,
    resources: nextResources,
    updatedAt: now,
  });
  const integrityError = assertCurriculumIntegrityOrError(nextCurriculum);
  if (integrityError) {
    jsonResponse(response, 400, integrityError);
    return;
  }
  const writeResult = writeSiteCurriculum(store, nextCurriculum, { updatedAt: now });
  if (writeResult.wipeBlocked) {
    jsonResponse(response, 409, {
      error: "This save was refused because it would have shrunk the live curriculum unexpectedly. Refresh and try again.",
      code: "curriculum_wipe_blocked",
    });
    return;
  }
  try {
    await writeStoreAsync(store);
  } catch (error) {
    console.error("Curriculum resource save failed:", error.message);
    jsonResponse(response, 503, { error: "Resource could not be saved." });
    return;
  }
  jsonResponse(response, 200, {
    resource,
    curriculum: curriculumWithoutFileData(nextCurriculum),
    siteContentUpdatedAt: writeResult.stamp,
  });
}

async function handleAdminCurriculumResourceArchive(request, response) {
  const body = await readJson(request);
  if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
    jsonResponse(response, 401, { error: "Admin access is required to archive curriculum resources." });
    return;
  }
  const id = normalizedShortText(body.id, 160);
  if (!id) {
    jsonResponse(response, 400, { error: "Resource id is required." });
    return;
  }
  const now = new Date().toISOString();
  const store = readStore();
  const siteContent = normalizedSiteContent(store.siteContent || defaultSiteContentStore());
  if (curriculumConcurrencyConflict(siteContent, body.expectedUpdatedAt)) {
    curriculumConflictResponse(response, siteContent);
    return;
  }
  const curriculum = siteContent.curriculum || defaultCurriculumStore();
  const existing = curriculum.resources.find((item) => item.id === id);
  if (!existing) {
    jsonResponse(response, 404, { error: "Resource not found." });
    return;
  }
  const unlinked = unlinkCurriculumResourceFromAllLessonPlans(curriculum, id);
  if (!unlinked) {
    jsonResponse(response, 400, { error: "Resource could not be unlinked from lesson plans." });
    return;
  }
  const resource = normalizedCurriculumResource({
    ...(unlinked.resources.find((item) => item.id === id) || existing),
    status: "archived",
    lessonPlanIds: [],
    updatedAt: now,
  });
  const nextCurriculum = normalizedCurriculumStore({
    ...unlinked,
    resources: unlinked.resources.map((item) => (item.id === id ? resource : item)),
    updatedAt: now,
  });
  const integrityError = assertCurriculumIntegrityOrError(nextCurriculum);
  if (integrityError) {
    jsonResponse(response, 400, integrityError);
    return;
  }
  const writeResult = writeSiteCurriculum(store, nextCurriculum, { updatedAt: now });
  if (writeResult.wipeBlocked) {
    jsonResponse(response, 409, {
      error: "This save was refused because it would have shrunk the live curriculum unexpectedly. Refresh and try again.",
      code: "curriculum_wipe_blocked",
    });
    return;
  }
  try {
    await writeStoreAsync(store);
  } catch (error) {
    jsonResponse(response, 503, { error: "Resource could not be archived." });
    return;
  }
  jsonResponse(response, 200, {
    resource: curriculumResourceMetadata(resource),
    curriculum: curriculumWithoutFileData(nextCurriculum),
    siteContentUpdatedAt: writeResult.stamp,
  });
}

async function handleAdminCurriculumResourceLink(request, response) {
  const body = await readJson(request);
  if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
    jsonResponse(response, 401, { error: "Admin access is required to link curriculum resources." });
    return;
  }
  const resourceId = normalizedShortText(body.resourceId, 160);
  const lessonPlanId = normalizedShortText(body.lessonPlanId, 160);
  if (!resourceId || !lessonPlanId) {
    jsonResponse(response, 400, { error: "resourceId and lessonPlanId are required." });
    return;
  }
  const store = readStore();
  const siteContent = normalizedSiteContent(store.siteContent || defaultSiteContentStore());
  if (curriculumConcurrencyConflict(siteContent, body.expectedUpdatedAt)) {
    curriculumConflictResponse(response, siteContent);
    return;
  }
  const curriculum = siteContent.curriculum || defaultCurriculumStore();
  const nextCurriculum = linkCurriculumResourceToLessonPlan(curriculum, resourceId, lessonPlanId);
  if (!nextCurriculum) {
    jsonResponse(response, 404, { error: "Resource or lesson plan not found." });
    return;
  }
  const integrityError = assertCurriculumIntegrityOrError(nextCurriculum);
  if (integrityError) {
    jsonResponse(response, 400, integrityError);
    return;
  }
  const now = new Date().toISOString();
  const writeResult = writeSiteCurriculum(store, nextCurriculum, { updatedAt: now });
  if (writeResult.wipeBlocked) {
    jsonResponse(response, 409, {
      error: "This save was refused because it would have shrunk the live curriculum unexpectedly. Refresh and try again.",
      code: "curriculum_wipe_blocked",
    });
    return;
  }
  try {
    await writeStoreAsync(store);
  } catch (error) {
    jsonResponse(response, 503, { error: "Resource could not be linked." });
    return;
  }
  jsonResponse(response, 200, {
    resource: curriculumResourceMetadata(nextCurriculum.resources.find((item) => item.id === resourceId)),
    lessonPlan: nextCurriculum.lessonPlans.find((item) => item.id === lessonPlanId),
    curriculum: curriculumWithoutFileData(nextCurriculum),
    siteContentUpdatedAt: writeResult.stamp,
  });
}

async function handleAdminCurriculumResourceUnlink(request, response) {
  const body = await readJson(request);
  if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
    jsonResponse(response, 401, { error: "Admin access is required to unlink curriculum resources." });
    return;
  }
  const resourceId = normalizedShortText(body.resourceId, 160);
  const lessonPlanId = normalizedShortText(body.lessonPlanId, 160);
  if (!resourceId || !lessonPlanId) {
    jsonResponse(response, 400, { error: "resourceId and lessonPlanId are required." });
    return;
  }
  const store = readStore();
  const siteContent = normalizedSiteContent(store.siteContent || defaultSiteContentStore());
  if (curriculumConcurrencyConflict(siteContent, body.expectedUpdatedAt)) {
    curriculumConflictResponse(response, siteContent);
    return;
  }
  const curriculum = siteContent.curriculum || defaultCurriculumStore();
  const nextCurriculum = unlinkCurriculumResourceFromLessonPlan(curriculum, resourceId, lessonPlanId);
  if (!nextCurriculum) {
    jsonResponse(response, 404, { error: "Resource or lesson plan not found." });
    return;
  }
  const integrityError = assertCurriculumIntegrityOrError(nextCurriculum);
  if (integrityError) {
    jsonResponse(response, 400, integrityError);
    return;
  }
  const now = new Date().toISOString();
  const writeResult = writeSiteCurriculum(store, nextCurriculum, { updatedAt: now });
  if (writeResult.wipeBlocked) {
    jsonResponse(response, 409, {
      error: "This save was refused because it would have shrunk the live curriculum unexpectedly. Refresh and try again.",
      code: "curriculum_wipe_blocked",
    });
    return;
  }
  try {
    await writeStoreAsync(store);
  } catch (error) {
    jsonResponse(response, 503, { error: "Resource could not be unlinked." });
    return;
  }
  jsonResponse(response, 200, {
    resource: curriculumResourceMetadata(nextCurriculum.resources.find((item) => item.id === resourceId)),
    lessonPlan: nextCurriculum.lessonPlans.find((item) => item.id === lessonPlanId),
    curriculum: curriculumWithoutFileData(nextCurriculum),
    siteContentUpdatedAt: writeResult.stamp,
  });
}

function handleUploadedResourcesList(request, response, url) {
  const adminToken = extractAdminToken(request, url) || "";
  const admin = validAdminToken(adminToken);
  const store = readStore();
  store.uploadedResources = dedupeUploadedResources(store.uploadedResources || [], MAX_UPLOADED_RESOURCES);
  jsonResponse(response, 200, { uploads: uploadedResourcesForResponse(store.uploadedResources, { admin }) });
}

async function handleAdminUploadedResourcesMigrate(request, response) {
  const body = await readJson(request);
  if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
    jsonResponse(response, 401, { error: "Admin access is required for upload migration." });
    return;
  }
  const incoming = Array.isArray(body.uploads) ? body.uploads : [];
  const store = readStore();
  const existing = store.uploadedResources || [];
  const merged = mergeUploadedResources(existing, incoming);
  const before = dedupeUploadedResources(existing, MAX_UPLOADED_RESOURCES).length;
  const after = merged.length;
  store.uploadedResources = merged;
  try {
    await writeStoreAsync(store);
  } catch (error) {
    console.error("Admin upload migration failed:", error.message);
    jsonResponse(response, 503, { error: "Uploads could not be saved to the database. Please try again." });
    return;
  }
  jsonResponse(response, 200, {
    uploads: uploadedResourcesForResponse(merged, { admin: true }),
    migration: {
      incoming: incoming.length,
      before,
      after,
      added: Math.max(0, after - before),
    },
  });
}

async function handleAdminUploadedResourceUpsert(request, response) {
  const body = await readJson(request);
  if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
    jsonResponse(response, 401, { error: "Admin access is required to save uploads." });
    return;
  }
  const upload = normalizedUploadedResourceEntry(body.upload || {});
  if (!upload) {
    jsonResponse(response, 400, { error: "A valid upload with an id is required." });
    return;
  }
  upload.updatedAt = new Date().toISOString();
  const store = readStore();
  store.uploadedResources = mergeUploadedResources(store.uploadedResources || [], [upload]);
  try {
    await writeStoreAsync(store);
  } catch (error) {
    console.error("Admin upload upsert failed:", error.message);
    jsonResponse(response, 503, { error: "Upload could not be saved to the database. Please try again." });
    return;
  }
  jsonResponse(response, 200, {
    upload,
    uploads: uploadedResourcesForResponse(store.uploadedResources, { admin: true }),
  });
}

async function handleAdminUploadedResourceDelete(request, response) {
  const body = await readJson(request);
  if (!validAdminToken(extractAdminTokenFromBody(request, body))) {
    jsonResponse(response, 401, { error: "Admin access is required to delete uploads." });
    return;
  }
  const id = normalizedShortText(body.id, 180);
  if (!id) {
    jsonResponse(response, 400, { error: "Upload id is required." });
    return;
  }
  const store = readStore();
  const existing = dedupeUploadedResources(store.uploadedResources || [], MAX_UPLOADED_RESOURCES);
  store.uploadedResources = existing.filter((item) => item.id !== id);
  try {
    await writeStoreAsync(store);
  } catch (error) {
    console.error("Admin upload delete failed:", error.message);
    jsonResponse(response, 503, { error: "Upload could not be deleted from the database. Please try again." });
    return;
  }
  jsonResponse(response, 200, { uploads: uploadedResourcesForResponse(store.uploadedResources, { admin: true }) });
}

