function readShellVersionFromDisk() {
  try {
    const swPath = path.join(__dirname, "..", "service-worker.js");
    const sw = fs.readFileSync(swPath, "utf8");
    const match = sw.match(/const\s+SHELL_VERSION\s*=\s*["']([^"']+)["']/);
    return match ? match[1] : null;
  } catch {
    return null;
  }
}

function buildVersionPayload() {
  const commit =
    String(process.env.RENDER_GIT_COMMIT || process.env.GIT_COMMIT || process.env.COMMIT_SHA || "").trim()
    || null;
  const branch =
    String(process.env.RENDER_GIT_BRANCH || process.env.GIT_BRANCH || "").trim()
    || null;
  const serviceId =
    String(process.env.RENDER_SERVICE_ID || "").trim()
    || null;
  const shellVersion = readShellVersionFromDisk();
  return {
    ok: true,
    service: "Little Learner Hub",
    time: new Date().toISOString(),
    commit,
    shortSha: commit ? commit.slice(0, 7) : null,
    branch,
    serviceId,
    shellVersion,
    nodeEnv: process.env.NODE_ENV || null,
  };
}

function handleBuildVersion(request, response) {
  // Read-only deploy identity — available even during storage boot so health
  // dashboards can confirm which SHA is serving before the DB is ready.
  jsonResponse(response, 200, buildVersionPayload());
}

function handleHealth(request, response) {
  if (!storageBootReady) {
    jsonResponse(response, 503, {
      ok: false,
      starting: true,
      service: "Little Learner Hub",
      time: new Date().toISOString(),
      note: "Storage is still initializing after a cold start or deploy.",
    });
    return;
  }
  const store = peekStore();
  const host = String(request.headers.host || "").split(":")[0].toLowerCase();
  const configuredHost = (() => {
    try {
      return new URL(SITE_URL).hostname.toLowerCase();
    } catch {
      return "";
    }
  })();
  const knownAppHosts = new Set([
    configuredHost,
    RENDER_SERVICE_HOST,
    "localhost",
    "127.0.0.1",
    ...WORKING_BRAND_DOMAINS,
    ...WORKING_BRAND_DOMAINS,
  ].filter(Boolean));
  jsonResponse(response, 200, {
    ok: true,
    service: "Little Learner Hub",
    time: new Date().toISOString(),
    stripeCheckoutReady: stripeConfigStatus().checkoutReady,
    launchReady: launchReadinessStatus().ready,
    supportEmailReady: supportEmailConfigStatus().ready,
    homeDaycareHubTesting: isHomeDaycareHubTestingEnabled(),
    homeDaycareHub: homeDaycareHubStatus(),
    aiGuideEnabled: isAiGuideEnabled(),
    aiGuide: aiGuideStatus(),
    founding: foundingStatusPayload(store),
    domain: {
      requestHost: host || null,
      configuredSiteUrl: SITE_URL,
      configuredHost: configuredHost || null,
      servingKnownAppHost: knownAppHosts.has(host),
      officialDomainTargets: OFFICIAL_DOMAINS,
      workingBrandDomains: WORKING_BRAND_DOMAINS,
      officialSiteUrl: `https://${OFFICIAL_APEX_HOST}`,
      renderServiceHost: RENDER_SERVICE_HOST,
      renderApexARecord: RENDER_LOAD_BALANCER_IPV4,
      dnsCheckEndpoint: "/api/domain-dns-check",
      note: `Official site: https://${OFFICIAL_APEX_HOST}. www should CNAME → ${RENDER_SERVICE_HOST}, apex A → ${RENDER_LOAD_BALANCER_IPV4}.`,
    },
  });
}

