function adminMessageMatchesSearch(message, query) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return true;
  const haystack = [
    message.subject,
    message.body,
    message.toEmail,
    message.conversationEmail,
    message.senderName,
  ].map((value) => String(value || "").toLowerCase()).join(" ");
  return haystack.includes(q);
}

function handleAdminMessagesSentList(request, response, url) {
  const adminToken = extractAdminToken(request, url) || "";
  if (!validAdminToken(adminToken)) {
    jsonResponse(response, 401, { error: "Admin access is required." });
    return;
  }
  const query = String(url.searchParams.get("q") || "");
  const store = ensureMessagingStore(readStore());
  const messages = store.messages
    .filter((m) => m.senderType === "admin" && (m.audience === "private" || m.toEmail))
    .filter((m) => adminMessageMatchesSearch(m, query))
    .sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1))
    .slice(0, 500)
    .map((m) => {
      const profile = publicConversationUserProfile(store, m.conversationEmail || m.toEmail);
      return {
        ...publicMessage(m, { admin: true }),
        userName: profile.name || m.toEmail || "",
        userEmail: m.conversationEmail || m.toEmail || "",
      };
    });
  jsonResponse(response, 200, { messages });
}

function handleAdminMessagesArchivedList(request, response, url) {
  const adminToken = extractAdminToken(request, url) || "";
  if (!validAdminToken(adminToken)) {
    jsonResponse(response, 401, { error: "Admin access is required." });
    return;
  }
  const query = String(url.searchParams.get("q") || "").trim().toLowerCase();
  const store = ensureMessagingStore(readStore());
  const commsStore = store;
  const inboxRows = (commsStore.adminInboxArchive || [])
    .map((row) => ({
      id: row.id,
      kind: "inbox",
      title: row.title || row.id || "Archived inbox item",
      email: row.email || "",
      archivedAt: row.archivedAt || "",
      preview: row.preview || "",
    }))
    .filter((row) => {
      if (!query) return true;
      const hay = `${row.title} ${row.email} ${row.preview}`.toLowerCase();
      return hay.includes(query);
    });
  const conversationRows = (commsStore.archivedConversations || [])
    .map((row) => {
      const email = normalizeEmail(row.conversationEmail || row.email);
      const profile = email ? publicConversationUserProfile(store, email) : { name: "", email: "" };
      return {
        id: `archived-${email}`,
        kind: "conversation",
        title: profile.name || email || "Archived conversation",
        email,
        archivedAt: row.archivedAt || "",
        preview: "Member archived this thread on their side — history is preserved.",
      };
    })
    .filter((row) => {
      if (!query) return true;
      const hay = `${row.title} ${row.email} ${row.preview}`.toLowerCase();
      return hay.includes(query);
    });
  jsonResponse(response, 200, {
    inbox: inboxRows,
    conversations: conversationRows,
    total: inboxRows.length + conversationRows.length,
  });
}

function isAdminConversationUnreadNotification(n, adminEmail = ADMIN_EMAIL) {
  if (!n || n.read) return false;
  if (!isConfiguredAdminEmail(n.email) && normalizeEmail(n.email) !== normalizeEmail(adminEmail || "")) {
    return false;
  }
  if (!normalizeEmail(n.conversationEmail || "")) return false;
  const type = String(n.type || "");
  return type === "message"
    || type === "admin_new_message"
    || type === "admin_message_reply";
}

function handleAdminConversationsList(request, response, url) {
  const adminToken = extractAdminToken(request, url) || "";
  if (!validAdminToken(adminToken)) {
    jsonResponse(response, 401, { error: "Admin access is required." });
    return;
  }
  const store = ensureMessagingStore(readStore());
  const bucketFilter = String(url.searchParams.get("bucket") || "all").trim().toLowerCase();
  const byUser = new Map();
  store.messages
    .filter((m) => m.audience === "private" && m.conversationEmail)
    .forEach((m) => {
      const key = normalizeEmail(m.conversationEmail);
      const existing = byUser.get(key);
      if (!existing || m.createdAt > existing.lastMessageAt) {
        byUser.set(key, {
          userEmail: key,
          lastMessageAt: m.createdAt,
          lastMessagePreview: messagePreviewText(m.body, 100),
          lastMessageSender: m.senderType,
        });
      }
    });
  // Count unread user messages once per messageId — admin aliases each get a
  // notification copy, which must not inflate the Conversations badge.
  const unreadFromUser = new Map();
  const seenUnreadKeys = new Set();
  store.notifications
    .filter((n) => isAdminConversationUnreadNotification(n))
    .forEach((n) => {
      const key = normalizeEmail(n.conversationEmail);
      if (!key) return;
      const dedupe = `${key}:${String(n.messageId || n.refId || n.id || "")}`;
      if (seenUnreadKeys.has(dedupe)) return;
      seenUnreadKeys.add(dedupe);
      unreadFromUser.set(key, (unreadFromUser.get(key) || 0) + 1);
    });
  let conversations = [...byUser.values()]
    .map((c) => {
      const profile = publicConversationUserProfile(store, c.userEmail);
      const classification = adminMessagingInbox.classifyConversation(store, c.userEmail);
      const unread = unreadFromUser.get(normalizeEmail(c.userEmail)) || 0;
      return {
        ...c,
        userName: profile.name || c.userEmail,
        businessName: profile.businessName || "",
        plan: profile.plan || "Free",
        unreadFromUser: unread,
        hasUserReply: classification.hasUserReply,
        isWelcomeOnly: classification.isWelcomeOnly,
        isAdminOutreachOnly: classification.isAdminOutreachOnly,
        bucket: classification.bucket,
        // New Messages = member has written (or has unread inbound). Welcome automations stay out.
        inNewMessages: classification.hasUserReply || unread > 0,
      };
    });

  if (bucketFilter === "new" || bucketFilter === "inbox") {
    conversations = conversations.filter((c) => c.inNewMessages);
  } else if (bucketFilter === "welcome" || bucketFilter === "automations") {
    conversations = conversations.filter((c) => c.isWelcomeOnly);
  } else if (bucketFilter === "unread") {
    conversations = conversations.filter((c) => Number(c.unreadFromUser || 0) > 0);
  }

  conversations.sort((a, b) => {
    const aUnread = Number(a.unreadFromUser || 0) > 0 ? 1 : 0;
    const bUnread = Number(b.unreadFromUser || 0) > 0 ? 1 : 0;
    if (aUnread !== bUnread) return bUnread - aUnread;
    return a.lastMessageAt < b.lastMessageAt ? 1 : -1;
  });

  const settings = adminMessagingInbox.ensureAdminMessagingSettings(store);
  const allClassified = [...byUser.keys()].map((email) => {
    const unread = unreadFromUser.get(email) || 0;
    const cls = adminMessagingInbox.classifyConversation(store, email);
    return {
      email,
      unread,
      inNewMessages: cls.hasUserReply || unread > 0,
      isWelcomeOnly: cls.isWelcomeOnly,
    };
  });

  jsonResponse(response, 200, {
    conversations,
    summary: {
      newMessages: allClassified.filter((c) => c.inNewMessages).length,
      unreadConversations: allClassified.filter((c) => c.unread > 0).length,
      welcomeOnly: allClassified.filter((c) => c.isWelcomeOnly).length,
      emailOnMemberMessage: settings.emailOnMemberMessage !== false,
    },
  });
}

function publicConversationUserProfile(store, email) {
  const user = store.users?.[email] || { email };
  const accessGroup = messagingCenter.accessGroupForUser(store, user);
  const planLabel = accessGroup === "founding"
    ? "Founding Member"
    : accessGroup === "pro"
      ? "Pro"
      : "Free";
  const displayName = [user.firstName, user.lastName].filter(Boolean).join(" ")
    || user.name
    || user.displayName
    || "";
  return {
    email,
    name: displayName || email,
    firstName: user.firstName || "",
    lastName: user.lastName || "",
    businessName: user.businessName || user.daycareName || user.programName || "",
    accountType: accountAccess.accountTypeLabel(accountAccess.resolveAccountType(user)),
    role: accountAccess.roleLabel(accountAccess.resolveUserRole(user)),
    plan: planLabel,
    accessGroup,
    signupAt: user.signupAt || user.createdAt || "",
    lastActiveAt: user.lastSeenAt || user.lastLoginAt || user.updatedAt || "",
    lastLoginAt: user.lastLoginAt || "",
  };
}

async function handleAdminConversationMessages(request, response, url) {
  const adminToken = extractAdminToken(request, url) || "";
  if (!validAdminToken(adminToken)) {
    jsonResponse(response, 401, { error: "Admin access is required." });
    return;
  }
  const userEmail = normalizeEmail(url.searchParams.get("userEmail") || "");
  if (!userEmail) {
    jsonResponse(response, 400, { error: "userEmail is required." });
    return;
  }
  const markReadParam = String(url.searchParams.get("markRead") || "1").trim().toLowerCase();
  const shouldMarkRead = !(markReadParam === "0" || markReadParam === "false" || markReadParam === "no");
  const store = ensureMessagingStore(readStore());
  // Opening a thread marks unread badges read — but live poll must pass markRead=0
  // so background refresh never clears badges accidentally.
  let marked = 0;
  if (shouldMarkRead && ADMIN_EMAILS.length) {
    marked = adminMessagingInbox.setConversationNotificationsRead(store, {
      userEmail,
      adminEmails: ADMIN_EMAILS,
      read: true,
      isAdminConversationUnreadNotification,
    });
    if (marked && !(await persistStoreOr503(store, response, "Could not save conversation read state."))) return;
  }
  const messages = store.messages
    .filter((m) => m.audience === "private" && normalizeEmail(m.conversationEmail) === userEmail)
    .sort((a, b) => (a.createdAt < b.createdAt ? -1 : 1))
    .map((m) => publicMessage(m, { admin: true }));
  const classification = adminMessagingInbox.classifyConversation(store, userEmail);
  jsonResponse(response, 200, {
    userEmail,
    messages,
    user: publicConversationUserProfile(store, userEmail),
    markedRead: shouldMarkRead ? marked : 0,
    ...classification,
  });
}

